INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('sharh-al-masail-ghulam-hussain', 1, 'Lawful Earning and the Table', 'The treatise opens where a person''s day actually opens — at work, and then at the table. Three teachings: that earning a lawful living is ranked with striving in the way of God and measured by whether a family is spared from having to ask; that the manners of eating, feeding, hosting and being hosted form a single discipline aimed away from the self; and that the boundary of the lawful runs from what may be eaten, through how an animal must be killed and what may be hunted, to what may be worn and displayed.
', 'deep_dive', 'sharh-al-masail-ghulam-hussain/audio/ep01.m4a', NULL, 2132, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('sharh-al-masail-ghulam-hussain', 2, 'Sale, Debt, and the Trust', 'The treatise turns to the transaction itself. Three teachings: that a sale stands on three pillars and five conditions, all of them defending against a single flaw — anything left indeterminate, from air to an uncaught fish to an unnamed garment; that all lending divides by intention alone, so that the loan made for God''s sake may yield its lender no benefit whatever while the worldly loan''s every rule points toward taking less; and that in hire, partnership, pre-emption, borrowing and safekeeping the governing category stops being ownership and becomes trust, with the ruling consistently favouring whoever holds the weaker position.
', 'deep_dive', 'sharh-al-masail-ghulam-hussain/audio/ep02.m4a', NULL, 893, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('sharh-al-masail-ghulam-hussain', 3, 'Pledge, Shared Wall, and Marriage', 'The treatise finishes its law of property and turns to obligations between people. Three teachings: that the security in a pledge is the written record and not the goods, so that the pledge held in hand without a document is the form the law condemns while a deed goes on proving the loan after the object is destroyed; that what two neighbours owe each other is decided by harm rather than by title, from a judge compelling a man to build on his own land to a division of ground that must price the well and the pathway along with the field; and that abstaining from marriage is an injury a person does to himself — with the home relocated from the building to the couple, the license for more than one wife read as a permission its own second clause withdraws, and the choosing governed by character before beauty.
', 'deep_dive', 'sharh-al-masail-ghulam-hussain/audio/ep03.m4a', NULL, 1088, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('sharh-al-masail-ghulam-hussain', 4, 'The Marriage Contract and Its Bonds', 'The treatise stops urging the reader to marry and starts explaining how a marriage is actually made. Three teachings: the choosing and the look, where the decision belongs to the discerning people of the household rather than to the couple, the ages are matched at around eighteen, the pool is narrowed to the community, and the glance a man is permitted is rationed to one; the contract and its terms, where a marriage concluded through the wrong person is void outright, a stipulation contrary to the Book is a nullity rather than a hard bargain, the husband''s four powers are each qualified by fairness in the same breath, and the marriage payment is kept small, kept the wife''s, and set by a judge rather than by the man paying it; and the forbidden degrees, which cannot be complied with but only discovered — kinship by blood, kinship manufactured by marriage, and kinship created by a single swallow of milk inside a child''s first two years.
', 'deep_dive', 'sharh-al-masail-ghulam-hussain/audio/ep04.m4a', NULL, 1953, NULL);
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('sharh-al-masail-ghulam-hussain', 5, 'Maintenance, Dissolution, and Inheritance', 'The treatise stops explaining how a marriage is made and starts explaining what it costs. Three teachings: what a household is owed, where the obligation survives a husband''s disappearance, runs at a median standard that is neither wasteful nor miserly, covers instruction as well as food, holds for a woman who does not pray, and follows a divorced woman through the nursing of her child; dissolution and the waiting period, where a judge investigates the complaint and may issue the divorce over an unwilling husband''s head, where the pronouncement must be spoken and not merely written, where a wife may buy her own release, and where the third divorce is closed against every staged workaround; and wealth that leaves a person''s hands — the gift that can be reclaimed, the endowment that cannot, the testament of the Father of Imams as the working model, the will that reaches only a third of an estate, and the fixed fractions that take the rest.
', 'deep_dive', 'sharh-al-masail-ghulam-hussain/audio/ep05.m4a', NULL, 1430, NULL);
