INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('sharh-al-masail-ghulam-hussain', 'the dignity of earning your bread', 'pp. 7-10', '["A Reminder on the Virtues of Earning One''s Living"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('sharh-al-masail-ghulam-hussain', 'at the table: eating, feeding, and being fed', 'pp. 10-19', '["Etiquette of Food", "What are the courtesies of wholesome food and the conduct of the people of this age?", "On the Merit of Feeding Others", "On the Manners of a Guest", "On the Manners of the Host", "On the Departure of Guests", "He mentioned that in its proper place, and there is no prohibition on eating."]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('sharh-al-masail-ghulam-hussain', 'clean and unclean: meat, the knife, and the hunt', 'pp. 19-28', '["On What is Forbidden", "He mentioned how to make it lawfully.", "On Ritual Slaughter", "On Hunting and What is Permitted and Forbidden", "On the Vessel and the Most High", "By the grace of your Lord it is made lawful for you.", "A hadith concerning each vessel according to its capacity"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('sharh-al-masail-ghulam-hussain', 'the anatomy of a sale', 'pp. 28-33', '["On the Rules of Sale"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('sharh-al-masail-ghulam-hussain', 'lending without riba', 'pp. 33-42', '["On Loans and Their Restructuring", "The issue is not one of Sa''d al-Qadi and the ruler al-Muhsin al-Mughlis."]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('sharh-al-masail-ghulam-hussain', 'trusts, pledges, and shared walls', 'pp. 42-57', '["Pre-emption", "Al-''Ariya — The Loan for Use", "He does not believe, and he guarantees — even if he is a Persian — taking this standard from the mortgagee.", "The issue is if it is like paying to ''Umar and the deposit of Shawmana.", "Mention of al-Rahhāl.", "The pledge is called the received pledge, so the mortgage is accepted, and it is not otherwise.", "And do not repeat that God does not love the aggressors."]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('sharh-al-masail-ghulam-hussain', 'why marry at all', 'pp. 57-69', '["Male Nahm al-Raghā''ib.", "Surah al-Nisa''"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('sharh-al-masail-ghulam-hussain', 'choosing well, looking rightly', 'pp. 70-84', '[]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('sharh-al-masail-ghulam-hussain', 'the contract: forbidden degrees, guardians, and the bride-price', 'pp. 84-93', '["On Lawful and Unlawful Women in Marriage", "On Conditions Stipulated in the Marriage Contract", "On the Verse of Mutual Rights"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('sharh-al-masail-ghulam-hussain', 'milk, maintenance, and the untying of a marriage', 'pp. 93-107', '["On Breastfeeding", "The relevant rulings are as follows", "On the subject of khul''a", "On khul''a", "On the waiting period (''iddah) and its rulings"]');
INSERT INTO source_reference (slug, anchor_key, page_range, headings) VALUES ('sharh-al-masail-ghulam-hussain', 'what outlives you: charity, endowment, and inheritance', 'pp. 107-124', '["On charity and spending in the way of God", "A guarantor for what is lost of wealth, and a guardian for the orphan.", "Table of Prohibitions on Marriage and Combination", "The categories of women forbidden in marriage, whether permanently or under certain conditions, are as follows", "And these rulings — if the wife and the combination is involved — lead to success and correct ordering."]');
