INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 0, NULL, 'Praise belongs to God for the blessings of earlier and later times.', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'praise belongs to god for the blessings of earlier and later times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 1, NULL, 'The treatise opens with the words of its own beginning:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'the treatise opens with the words of its own beginning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 2, NULL, 'Al-Fatihah: 1بِسْمِ ٱللَّهِ ٱلرَّحْمَنِ ٱلرَّحِيمِIn the name of God, the Most Merciful, the Most Compassionate.', '', NULL, 'Al-Fatihah: 1', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'al fatihah 1بسم الله الرحمن الرحيمin the name of god the most merciful the most compassionate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 3, NULL, 'Sayingالْحَمْدُ لِلَّهِ وَحْدَهُ وَالصَّلَاةُ عَلَى مَنْ لَا نَبِيَّ بَعْدَهُAll praise is due to God alone, and misguidance falls upon whoever strays after guidance has come to him.', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingالحمد لله وحده والصلاه علي من لا نبي بعدهall praise is due to god alone and misguidance falls upon whoever strays after guidance has come to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 4, NULL, 'The work that follows is an explanatory treatise. It sets out the standing of Fallah Husayn and his brother, and records the care taken over its printing by Muhammad Ibrahim, may God pardon him.', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'the work that follows is an explanatory treatise it sets out the standing of fallah husayn and his brother and records the care taken over its printing by muhammad ibrahim may god pardon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 5, NULL, 'Its foundations lie in Hind — that is, India — composed in answer to the need there for its rulings. Drawing on the sources available to him, the author summarized the issues translated in al-Muhannadi, setting aside matters that earlier times had already laid to rest: questions relating to enslaved persons, certain technical difficulties, and topics of that kind. He likewise omitted issues such as those of usury, mortgages, and the like.', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'its foundations lie in hind that is india composed in answer to the need there for its rulings drawing on the sources available to him the author summarized the issues translated in al muhannadi setting aside matters that earlier times had already laid to rest questions relating to enslaved persons certain technical difficulties and topics of that kind he likewise omitted issues such as those of usury mortgages and the like', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 6, NULL, 'This was accomplished in the presence of the supporter Sa''d Ali ibn Hasan, may God preserve him, in the thirty-seventh year, when the review was undertaken alongside the judge and the scholar until the first of the month.', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'this was accomplished in the presence of the supporter sad ali ibn hasan may god preserve him in the thirty seventh year when the review was undertaken alongside the judge and the scholar until the first of the month', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 7, NULL, 'Tahsin ibn carried the work with him on his journey to the Indian subcontinent — concerning the conditions of the mission and the brotherhood — in the thirty-eighth year. He was pleased to present it and engage with it. The book was set out and rendered into Arabic, then brought forward, and God''s provision was permitted for it. He was instructed to take it to the Arabs, so that whoever among them wished might benefit from it. God is their sufficiency for success.', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'tahsin ibn carried the work with him on his journey to the indian subcontinent concerning the conditions of the mission and the brotherhood in the thirty eighth year he was pleased to present it and engage with it the book was set out and rendered into arabic then brought forward and gods provision was permitted for it he was instructed to take it to the arabs so that whoever among them wished might benefit from it god is their sufficiency for success', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 8, NULL, 'God Most High says:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'god most high says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 9, NULL, 'Al-Jumu''ah: 10فَٱنتَشِرُوا۟ فِى ٱلْأَرْضِ وَٱبْتَغُوا۟ مِن فَضْلِ ٱللَّهِ"Travel the earth and seek of God''s bounty."', '', NULL, 'Al-Jumu''ah: 10', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'al jumuah 10فانتشروا في الارض وابتغوا من فضل الله travel the earth and seek of gods bounty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 10, NULL, 'The Messenger of God said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'the messenger of god said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 11, NULL, 'Sayingاَلتَّاجِرُ الصَّدُوقُ يحشر يوم القيمة مع الصِّدِّيقِينَ والشهداء"The truthful merchant is raised on the Day of Resurrection with the truthful and the martyrs."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingالتاجر الصدوق يحشر يوم القيمه مع الصديقين والشهداء the truthful merchant is raised on the day of resurrection with the truthful and the martyrs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 12, NULL, 'And he said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 13, NULL, 'The Master said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'the master said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 14, NULL, 'Sayingمَنْ طَلَبَ الرِّزْقَ حَلَالًا وَتَعَفُّفًا عَنِ الْمَسْئَلَةِ وَسَعْيًا عَلَى عِيَالِهِ وَتَعَطُّفًا عَلَى جَارِهِ لَقِىَ اللَّهَ وَوَجْهُهُ كَالْبَدْرِ"Whoever seeks his provision lawfully, keeping himself from begging, striving for his dependents, and showing kindness to his neighbor, will meet God with a face like the full moon."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingمن طلب الرزق حلالا وتعففا عن المسيله وسعيا علي عياله وتعطفا علي جاره لقي الله ووجهه كالبدر whoever seeks his provision lawfully keeping himself from begging striving for his dependents and showing kindness to his neighbor will meet god with a face like the full moon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 15, NULL, 'The Master said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'the master said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 16, NULL, 'Sayingاِتَّقُوا اللَّهَ وَاَجْمِلُوا فِى الطَّلَبِ"Fear God, and be measured in seeking."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingاتقوا الله واجملوا في الطلب fear god and be measured in seeking', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 17, NULL, 'Sayingلَإَنْ يَأْخُذَ اَحَدُكُمْ حَبْلَهُ فَيَحْطِبَ عَلَى ظَهْرِهِ خَيْرٌ مِنْ اَنْ يَأْتِىَ رَجُلًا اَعْطَاهُ اللَّهُ مِنْ فَضْلِهِ فَيَسْأَلَهُ اَعْطَاهُ اَوْ مَنَعَهُ"That one of you takes his rope and carries firewood upon his back is better for him than that he come to a man whom God has given of His bounty and beg from him, whether that man gives him or refuses him."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingلان ياخذ احدكم حبله فيحطب علي ظهره خير من ان ياتي رجلا اعطاه الله من فضله فيساله اعطاه او منعه that one of you takes his rope and carries firewood upon his back is better for him than that he come to a man whom god has given of his bounty and beg from him whether that man gives him or refuses him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 18, NULL, 'It is related of him that during the expedition of Tabuk, he passed by a strong young man driving his beasts and laboring hard. Those present said: "O Messenger of God, if only this man''s strength, vigor, and soundness were spent in the way of God — that would be better." The Messenger of God heard them and asked: "What is this work of yours, and for what do you toil at it?" The young man said: "I have a wife and dependants. I earn by this labor, I spend upon my dependants, I keep them from having to beg, and I discharge a debt that lies upon me." He said: "Perhaps it is for other than that." The young man said: "No." When the young man had turned away, the Messenger of God said: "If he is truthful, then he has a reward like the reward of the fighter, and the reward of the pilgrim, and the reward of the one who performs the lesser pilgrimage."', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'it is related of him that during the expedition of tabuk he passed by a strong young man driving his beasts and laboring hard those present said o messenger of god if only this mans strength vigor and soundness were spent in the way of god that would be better the messenger of god heard them and asked what is this work of yours and for what do you toil at it the young man said i have a wife and dependants i earn by this labor i spend upon my dependants i keep them from having to beg and i discharge a debt that lies upon me he said perhaps it is for other than that the young man said no when the young man had turned away the messenger of god said if he is truthful then he has a reward like the reward of the fighter and the reward of the pilgrim and the reward of the one who performs the lesser pilgrimage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 19, NULL, 'He said: When a man''s circumstances become straitened,', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'he said when a mans circumstances become straitened', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 20, NULL, 'Sayingفَلْيَخْرُجْ مِنْ بَلَدِهِ وَيَضْرِبْ فِى الْاَرْضِ يَبْتَغِى مِنْ فَضْلِ اللَّهِ وَلَا يَغُمَّ نَفْسَهُ وَاَهْلَهُ"let him go out from his town and strike out into the earth seeking of God''s bounty, and let him not bring grief upon himself and his household."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingفليخرج من بلده ويضرب في الارض يبتغي من فضل الله ولا يغم نفسه واهله let him go out from his town and strike out into the earth seeking of gods bounty and let him not bring grief upon himself and his household', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 21, NULL, 'It is also related of him that he spoke of those whom God shelters in His shade on the day when no shade exists but His:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'it is also related of him that he spoke of those whom god shelters in his shade on the day when no shade exists but his', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 22, NULL, 'Sayingرَجُلٌ خَرَجَ ضَارِبًا فِى الْاَرْضِ يَطْلُبُ مِنْ فَضْلِ اللَّهِ مَا يَكُفُّ بِهِ نَفْسَهُ وَيَعُودُ بِهِ عَلَى عِيَالِهِ"a man who went out striking into the earth, seeking of God''s bounty what would suffice him and what he might bring back for his dependants."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingرجل خرج ضاربا في الارض يطلب من فضل الله ما يكف به نفسه ويعود به علي عياله a man who went out striking into the earth seeking of gods bounty what would suffice him and what he might bring back for his dependants', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 23, NULL, 'And he said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 24, NULL, 'Sayingاِنَّ اللَّهَ يُحِبُّ الْعَبْدَ اَنْ يَكُونَ سَهْلَ الْبَيْعِ وَسَهْلَ الشِّرَاءِ وَسَهْلَ الْقَضَاءِ وَسَهْلَ الِاقْتِضَاءِ"God loves the servant who is easy in selling, easy in buying, easy in settling what he owes, and easy in claiming what is owed to him."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingان الله يحب العبد ان يكون سهل البيع وسهل الشراء وسهل القضاء وسهل الاقتضاء god loves the servant who is easy in selling easy in buying easy in settling what he owes and easy in claiming what is owed to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 25, NULL, 'That is how he described trade — he loved it and urged people toward it, for in it lie much good and much blessing. The Messenger of God once passed by the traders, those whom people of that time called brokers, and said to them:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'that is how he described trade he loved it and urged people toward it for in it lie much good and much blessing the messenger of god once passed by the traders those whom people of that time called brokers and said to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 26, NULL, 'Sayingاَلَا اِنِّى لَا اُسَمِّيكُمُ السَّمَاسِرَةَ وَلَكِنِّى اُسَمِّيكُمُ التُّجَّارَ وَالتَّاجِرُ الْفَاجِرُ فِى النَّارِ"I do not name you brokers; rather I name you merchants. And the merchant who deals falsely is in the Fire."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingالا اني لا اسميكم السماسره ولكني اسميكم التجار والتاجر الفاجر في النار i do not name you brokers rather i name you merchants and the merchant who deals falsely is in the fire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 27, NULL, 'At that, they shut their doors and withdrew from trading. The Messenger of God came out and asked: "What is the matter with the people?" He was told: "O Messenger of God, they heard what you said yesterday, and they have held back." He said: "And I say it again today: unless a man takes what is rightfully his and gives what is rightfully due."', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'at that they shut their doors and withdrew from trading the messenger of god came out and asked what is the matter with the people he was told o messenger of god they heard what you said yesterday and they have held back he said and i say it again today unless a man takes what is rightfully his and gives what is rightfully due', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 28, NULL, 'A report has also come down of a man who said to the Commander of the Believers: "O Commander of the Believers, I wish to enter into trade." He said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'a report has also come down of a man who said to the commander of the believers o commander of the believers i wish to enter into trade he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 29, NULL, 'Sayingاُفْقِهْتَ فِى دِينِ اللهِ', '', 'اُفْقِهْتَ فِى دِينِ اللهِ', 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingافقهت في دين الله', 'افقهت في دين الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 30, NULL, '"Have you gained understanding in the religion of God?" The man said: "Something of that." He said: "Understanding first, then trade."', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'have you gained understanding in the religion of god the man said something of that he said understanding first then trade', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 31, NULL, 'And he used to say:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'and he used to say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 32, NULL, 'Sayingاِنِّى لَاَبْغَضُ الرَّجُلَ يَكُونُ كَسُولًا فِى اَمْرِ دُنْيَاهُ لِاَنَّهُ اِذَا كَانَ كَسِلًا فِى اَمْرِ دُنْيَاهُ فَهُوَ عَنْ اَمْرِ آخِرَتِهِ اَكْسَلُ"I dislike the man who is slothful in the affair of his world, for if he is slack in the affair of his world, he is slacker still in the affair of his Hereafter."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingاني لابغض الرجل يكون كسولا في امر دنياه لانه اذا كان كسلا في امر دنياه فهو عن امر اخرته اكسل i dislike the man who is slothful in the affair of his world for if he is slack in the affair of his world he is slacker still in the affair of his hereafter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 33, NULL, 'Among his sayings also was:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'among his sayings also was', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 34, NULL, 'Sayingمَا مِنْ غَدْوَةِ اَحَدِكُمْ فِى سَبِيلِ اللَّهِ بِاَعْظَمَ مِنْ غَدْوَتِهِ يَطْلُبُ فِيهِ لِوَلَدِهِ وَعِيَالِهِ مَا يُصْلِحُ هُمْ"No morning setting-out of one of you in the way of God is greater than his setting-out to seek for his child and his dependants what will set them right."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingما من غدوه احدكم في سبيل الله باعظم من غدوته يطلب فيه لولده وعياله ما يصلح هم no morning setting out of one of you in the way of god is greater than his setting out to seek for his child and his dependants what will set them right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 35, NULL, 'A man once asked Imam Jafar ibn Muhammad (عليه السلام) to call upon God to grant him provision and to give him a supplication. He said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'a man once asked imam jafar ibn muhammad عليه السلام to call upon god to grant him provision and to give him a supplication he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 36, NULL, 'Sayingلَا اَدْعُو لَكَ اَطْلُبُ كَمَا أُمِرْتُ', '', 'لَا اَدْعُو لَكَ اَطْلُبُ كَمَا أُمِرْتُ', 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingلا ادعو لك اطلب كما امرت', 'لا ادعو لك اطلب كما امرت');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 37, NULL, '"I will not supplicate for you. Seek, as you have been commanded." Then he said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'i will not supplicate for you seek as you have been commanded then he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 38, NULL, 'Sayingيَنْبَغِى لِلْمُسْلِمِ اَنْ يَلْتَمِسَ الرِّزْقَ حَتَّى يُصِيبَهُ حَرُّ الشَّمْسِ', '', 'يَنْبَغِى لِلْمُسْلِمِ اَنْ يَلْتَمِسَ الرِّزْقَ حَتَّى يُصِيبَهُ حَرُّ الشَّمْسِ', 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingينبغي للمسلم ان يلتمس الرزق حتي يصيبه حر الشمس', 'ينبغي للمسلم ان يلتمس الرزق حتي يصيبه حر الشمس');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 39, NULL, '"It befits the Muslim to seek his provision until the heat of the sun reaches him."', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'it befits the muslim to seek his provision until the heat of the sun reaches him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 40, NULL, 'He then counseled one of his companions, saying:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'he then counseled one of his companions saying', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 41, NULL, 'Sayingلَا تَكُنْ دَوَّارًا فِى الْاَسْوَاقِ وَلَا تَكُنْ شَرَّاءً دَقَايِقَ الْاَشْيَاءِ بِنَفْسِكَ فَاِنَّهُ لَا يَنْبَغِى لَكَ وَلَا لِلْمَرْءِ الْمُسْلِمِ اَهْلِ الدِّينِ وَالْحَسَبِ اَنْ يَشْتَرِىَ دَقَايِقَ الْاَشْيَاءِ بِنَفْسِهِ"Do not be one who circles about in the markets, and do not be one who buys trifling things himself; for it does not befit you, nor does it befit the Muslim man of religion and standing, that he purchase trifling things himself."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingلا تكن دوارا في الاسواق ولا تكن شراء دقايق الاشياء بنفسك فانه لا ينبغي لك ولا للمرء المسلم اهل الدين والحسب ان يشتري دقايق الاشياء بنفسه do not be one who circles about in the markets and do not be one who buys trifling things himself for it does not befit you nor does it befit the muslim man of religion and standing that he purchase trifling things himself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 42, NULL, 'One day the Master noticed a man among his companions carrying a bundle of greens, and said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'one day the master noticed a man among his companions carrying a bundle of greens and said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the dignity of earning your bread', '1. The Dignity of Earning Your Bread', 43, NULL, 'Sayingانه يكره للرجل السرى ان يحمل الشئ الدنى لئلا يجترىء عليه احد"It is disliked for a man of honor to carry a lowly thing, lest anyone become emboldened against him."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 1 the dignity of earning your bread', 'sayingانه يكره للرجل السري ان يحمل الشي الدني ليلا يجتريء عليه احد it is disliked for a man of honor to carry a lowly thing lest anyone become emboldened against him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 0, NULL, 'Food is a matter of religion before it is a matter of appetite, and the Prophet''s conduct at his meals was itself a teaching. He ate as a servant eats, and he said of himself:', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'food is a matter of religion before it is a matter of appetite and the prophets conduct at his meals was itself a teaching he ate as a servant eats and he said of himself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 1, NULL, 'Sayingأَنَا عَبْدٌ آكُلُ كَمَا يَأْكُلُ الْعَبْدُ وَأَجْلِسُ كَمَا يَجْلِسُ الْعَبْدُ"I am a servant: I eat as the servant eats, and I sit as the servant sits."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'sayingانا عبد اكل كما ياكل العبد واجلس كما يجلس العبد i am a servant i eat as the servant eats and i sit as the servant sits', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 2, NULL, 'He disliked eating while reclining, and he disliked the posture of tyrants — stretched out or leaning back at ease. He would sit upon the ground, drawing one leg up and settling upon the other, and take his food in that posture.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'he disliked eating while reclining and he disliked the posture of tyrants stretched out or leaning back at ease he would sit upon the ground drawing one leg up and settling upon the other and take his food in that posture', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 3, NULL, 'At the table his practice was consistent:', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'at the table his practice was consistent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 4, NULL, 'He ate with his right hand and began with water. He did not eat from the crown of the dish or from the middle of the food, but from what lay nearest him. He kept each morsel small and chewed it well, and did not reach for the next until the first was swallowed. He never faulted a food: if it pleased him he ate it, and if it did not, he left it. He forbade haste and gulping, and remained patient until each mouthful was fully swallowed. He did not drink water in the course of a meal unless a morsel had caught in his throat or he had sneezed.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'he ate with his right hand and began with water he did not eat from the crown of the dish or from the middle of the food but from what lay nearest him he kept each morsel small and chewed it well and did not reach for the next until the first was swallowed he never faulted a food if it pleased him he ate it and if it did not he left it he forbade haste and gulping and remained patient until each mouthful was fully swallowed he did not drink water in the course of a meal unless a morsel had caught in his throat or he had sneezed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 5, NULL, 'When the food was finished he cleaned his fingers and washed his hand. This was the way of the Messenger of God in eating and drinking: humility before God and honor shown to His provision. The people of religion ought therefore to follow the Messenger''s acts and courtesies in their own living, free from any display of greatness or vanity.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'when the food was finished he cleaned his fingers and washed his hand this was the way of the messenger of god in eating and drinking humility before god and honor shown to his provision the people of religion ought therefore to follow the messengers acts and courtesies in their own living free from any display of greatness or vanity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 6, NULL, 'As for how the food is set out: if a man is seated on the ground, he may place his food upon a cloth if he is able. If he is upon a bed, he may set it apart from where he sits. If his custom is to sit upon a chair, he may spread the table upon something raised above him, so that his honoring of the sustenance is made plain.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'as for how the food is set out if a man is seated on the ground he may place his food upon a cloth if he is able if he is upon a bed he may set it apart from where he sits if his custom is to sit upon a chair he may spread the table upon something raised above him so that his honoring of the sustenance is made plain', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 7, NULL, 'It is narrated from Jafar ibn Muhammad (ع) that he said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'it is narrated from jafar ibn muhammad ع that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 8, NULL, 'Sayingلَا يَأْكُلُ الرَّجُلُ بِشِمَالِهِ وَلَا يَشْرَبُ بِهَا وَلَا يُنَاوِلُ بِهَا"A man should not eat with his left hand, nor drink with it, nor hand anything with it."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'sayingلا ياكل الرجل بشماله ولا يشرب بها ولا يناول بها a man should not eat with his left hand nor drink with it nor hand anything with it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 9, NULL, 'When drinking water he should say بسم الله, and when he sets the vessel down, اَلْحَمْدُ لِلَّهِ. He should look into the vessel first and drink water that is pure and clean, pausing over it in three breaths. If no vessel is at hand, he may drink from his cupped hands, sipping the water; milk, however, may be taken in a draught. The food itself must be lawful and clean, and the intention behind eating it must not be mere pleasure and indulgence, but strength for righteous deeds.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'when drinking water he should say بسم الله and when he sets the vessel down الحمد لله he should look into the vessel first and drink water that is pure and clean pausing over it in three breaths if no vessel is at hand he may drink from his cupped hands sipping the water milk however may be taken in a draught the food itself must be lawful and clean and the intention behind eating it must not be mere pleasure and indulgence but strength for righteous deeds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 10, NULL, 'The chapter turns next to the merit of feeding others. God Most High says:', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'the chapter turns next to the merit of feeding others god most high says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 11, NULL, 'Sayingوَيُطْعِمُونَ الطَّعَامَ عَلَى حُبِّهِ مِسْكِينًا وَيَتِيمًا وَأَسِيرًا إِنَّمَا نُطْعِمُكُمْ لِوَجْهِ اللَّهِ لَا نُرِيدُ مِنْكُمْ جَزَاءً وَلَا شُكُورًا"And they give food, in spite of their love for it, to the poor, the orphan, and the captive, saying: We feed you only for the sake of God; we desire from you neither reward nor thanks."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'sayingويطعمون الطعام علي حبه مسكينا ويتيما واسيرا انما نطعمكم لوجه الله لا نريد منكم جزاء ولا شكورا and they give food in spite of their love for it to the poor the orphan and the captive saying we feed you only for the sake of god we desire from you neither reward nor thanks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 12, NULL, 'And in the hadith:', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'and in the hadith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 13, NULL, 'Sayingإِنَّ فِي الْجَنَّةِ غُرَفًا يُرَى ظَاهِرُهَا مِنْ بَاطِنِهَا وَبَاطِنُهَا مِنْ ظَاهِرِهَا لِمَنْ أَلَانَ الْكَلَامَ وَأَطْعَمَ الطَّعَامَ وَصَلَّى بِاللَّيْلِ وَالنَّاسُ نِيَامٌ"In Paradise there are chambers whose outside is seen from within and whose inside is seen from without, prepared for whoever speaks gently, feeds others, and prays by night while the people sleep."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'sayingان في الجنه غرفا يري ظاهرها من باطنها وباطنها من ظاهرها لمن الان الكلام واطعم الطعام وصلي بالليل والناس نيام in paradise there are chambers whose outside is seen from within and whose inside is seen from without prepared for whoever speaks gently feeds others and prays by night while the people sleep', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 14, NULL, 'It is also said that the best of people are those who provide food. Whoever feeds a hungry man until he is satisfied and gives him drink until he is quenched, God removes him far from the Fire.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'it is also said that the best of people are those who provide food whoever feeds a hungry man until he is satisfied and gives him drink until he is quenched god removes him far from the fire', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 15, NULL, 'It is narrated from the Commander of the Believers (ع) that the Messenger of God was brought seven captives. He said: "O Ali, rise and strike their necks." Then Jibril descended and said: "O Muhammad, strike the necks of six of these and release this one." The Messenger of God said: "O Jibril, what is his state?" He said: "He is open-handed, generous with food." He said: "Is this from you or from your Lord?" He said: "Rather from your Lord, O Muhammad."', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'it is narrated from the commander of the believers ع that the messenger of god was brought seven captives he said o ali rise and strike their necks then jibril descended and said o muhammad strike the necks of six of these and release this one the messenger of god said o jibril what is his state he said he is open handed generous with food he said is this from you or from your lord he said rather from your lord o muhammad', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 16, NULL, 'Also from Ali (ع), that he said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'also from ali ع that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 17, NULL, 'Sayingإِذَا دَخَلَ أَخُوكَ الْمُؤْمِنُ فَأَطْعِمْهُ مِنْ أَطْيَبِ مَا فِي بَيْتِكَ وَإِنْ كَانَ صَائِمًا فَادْهُنْهُ"When your believing brother comes in, feed him from the best of what is in your house; and if he is fasting, anoint him."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'sayingاذا دخل اخوك المومن فاطعمه من اطيب ما في بيتك وان كان صايما فادهنه when your believing brother comes in feed him from the best of what is in your house and if he is fasting anoint him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 18, NULL, 'It is also narrated from Imam Muhammad al-Baqir (ع) that feeding a believer is equal to freeing a slave, and that the most beloved of deeds to God is bringing gladness to a believer — whether by satisfying his hunger or by settling his debt.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'it is also narrated from imam muhammad al baqir ع that feeding a believer is equal to freeing a slave and that the most beloved of deeds to god is bringing gladness to a believer whether by satisfying his hunger or by settling his debt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 19, NULL, 'Hospitality belongs to the character of the believer and to the noble virtues. Honoring the guest is among them, and the limit of hospitality is three days; what is given beyond that is charity. Among the noblest manners of the prophets is generosity with food. It falls upon the one visited to offer his brother whatever is easy for him, even if it is only a draught of water. Whoever disdains to offer his brother what is easy for him remains in God''s displeasure by day and by night; and whoever belittles what his brother offers him remains so likewise.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'hospitality belongs to the character of the believer and to the noble virtues honoring the guest is among them and the limit of hospitality is three days what is given beyond that is charity among the noblest manners of the prophets is generosity with food it falls upon the one visited to offer his brother whatever is easy for him even if it is only a draught of water whoever disdains to offer his brother what is easy for him remains in gods displeasure by day and by night and whoever belittles what his brother offers him remains so likewise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 20, NULL, 'Ali would attend invitations and say: "It is a right upon whoever is invited that he answer it. But whoever comes uninvited has come to what does not befit him."', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'ali would attend invitations and say it is a right upon whoever is invited that he answer it but whoever comes uninvited has come to what does not befit him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 21, NULL, 'And the Messenger of God said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'and the messenger of god said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 22, NULL, 'Sayingمَنْ أَكَلَ الطَّعَامَ لَمْ يُدْعَ إِلَيْهِ فَإِنَّمَا يَأْكُلُ فِي جَوْفِهِ شُعْلَةَ نَارٍ"Whoever eats food to which he was not invited eats only a flame of fire in his belly."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'sayingمن اكل الطعام لم يدع اليه فانما ياكل في جوفه شعله نار whoever eats food to which he was not invited eats only a flame of fire in his belly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 23, NULL, 'He also forbade a man to feed another from food (اَلطَّعَام) to which he himself had been invited, unless given leave to do so.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'he also forbade a man to feed another from food الطعام to which he himself had been invited unless given leave to do so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 24, NULL, 'It is related of al-Husayn ibn Ali that he saw a man who had been invited to a meal say to the one inviting him: "Excuse me." Al-Husayn (ع) said: "Rise and answer the invitation. If you are not fasting, then eat; and if you are fasting, then bless them."', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'it is related of al husayn ibn ali that he saw a man who had been invited to a meal say to the one inviting him excuse me al husayn ع said rise and answer the invitation if you are not fasting then eat and if you are fasting then bless them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 25, NULL, 'Jafar ibn Muhammad said: when one of you enters upon his brother while fasting, and his brother asks him to break the fast, let him break it — unless the fast is a make-up fast or a vow, or unless the sun has already passed its meridian. And he said: when your brother says to you "eat," then eat, and do not oblige him to swear upon you, for he desires only to honor you. And he said: when your brother comes to you, offer him what is easy for you; and if you invite him, take trouble for him as far as you are able.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'jafar ibn muhammad said when one of you enters upon his brother while fasting and his brother asks him to break the fast let him break it unless the fast is a make up fast or a vow or unless the sun has already passed its meridian and he said when your brother says to you eat then eat and do not oblige him to swear upon you for he desires only to honor you and he said when your brother comes to you offer him what is easy for you and if you invite him take trouble for him as far as you are able', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 26, NULL, 'He said to one of his companions who was eating with him: a man''s affection for his brother is known by the goodness of his eating (أَكْل) from his food. It pleases me that a man should eat of my food and eat well — that gladdens me. And he used to say: when you gather over food with family and children, do not sit in silence, but speak of what is good and relate the stories of the righteous.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'he said to one of his companions who was eating with him a mans affection for his brother is known by the goodness of his eating اكل from his food it pleases me that a man should eat of my food and eat well that gladdens me and he used to say when you gather over food with family and children do not sit in silence but speak of what is good and relate the stories of the righteous', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 27, NULL, 'On the manners of the guest.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'on the manners of the guest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 28, NULL, 'It is not of the Sunnah to enter a house uninvited at the time of eating, for that is an intrusion. It is reported that whoever walks toward food to which he was not invited walks as a transgressor and eats what is unlawful. Yet if a man enters and finds those inside at their food (اَلطَّعَام), he should hold back until they finish. If they call him to share with them, he should consider: if he knows they call him sincerely, wishing his company, let him share with them; but if he perceives that the call was directed only toward إليه — a gesture of politeness and embarrassment on their part — he should decline.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'it is not of the sunnah to enter a house uninvited at the time of eating for that is an intrusion it is reported that whoever walks toward food to which he was not invited walks as a transgressor and eats what is unlawful yet if a man enters and finds those inside at their food الطعام he should hold back until they finish if they call him to share with them he should consider if he knows they call him sincerely wishing his company let him share with them but if he perceives that the call was directed only toward اليه a gesture of politeness and embarrassment on their part he should decline', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 29, NULL, 'As for entering the houses of those whose closeness is established, God Most High has said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'as for entering the houses of those whose closeness is established god most high has said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 30, NULL, 'Sayingوَلَا عَلَى أَنفُسِكُمْ أَن تَأْكُلُوا مِن بُيُوتِكُمْ أَوْ بُيُوتِ آبَائِكُمْ أَوْ بُيُوتِ أُمَّهَاتِكُمْ أَوْ بُيُوتِ إِخْوَانِكُمْ أَوْ بُيُوتِ أَخَوَاتِكُمْ أَوْ بُيُوتِ أَعْمَامِكُمْ أَوْ بُيُوتِ عَمَّاتِكُمْ أَوْ بُيُوتِ أَخْوَالِكُمْ أَوْ بُيُوتِ خَالَاتِكُمْ أَوْ مَا مَلَكْتُم مَّفَاتِحَهُ أَوْ صَدِيقِكُمْ لَيْسَ عَلَيْكُمْ جُنَاحٌ أَن تَأْكُلُوا جَمِيعًا أَوْ أَشْتَاتًا "...nor on yourselves, that you eat from your own houses, or the houses of your fathers, or the houses of your mothers, or the houses of your brothers, or the houses of your sisters, or the houses of your paternal uncles, or the houses of your paternal aunts, or the houses of your maternal uncles, or the houses of your maternal aunts, or from those whose keys you possess, or from your friend. There is no blame upon you whether you eat together or separately."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'sayingولا علي انفسكم ان تاكلوا من بيوتكم او بيوت ابايكم او بيوت امهاتكم او بيوت اخوانكم او بيوت اخواتكم او بيوت اعمامكم او بيوت عماتكم او بيوت اخوالكم او بيوت خالاتكم او ما ملكتم مفاتحه او صديقكم ليس عليكم جناح ان تاكلوا جميعا او اشتاتا nor on yourselves that you eat from your own houses or the houses of your fathers or the houses of your mothers or the houses of your brothers or the houses of your sisters or the houses of your paternal uncles or the houses of your paternal aunts or the houses of your maternal uncles or the houses of your maternal aunts or from those whose keys you possess or from your friend there is no blame upon you whether you eat together or separately', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 31, NULL, 'The Messenger of God entered the house of Barira in her absence and found food there — food that had come to her as charity. When she returned and was asked about it, she said that the charity had reached where it belonged; he had eaten knowing this, and she was glad of it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'the messenger of god entered the house of barira in her absence and found food there food that had come to her as charity when she returned and was asked about it she said that the charity had reached where it belonged he had eaten knowing this and she was glad of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 32, NULL, 'The companions of al-Hasan (ع) used to eat whatever they found in his house without asking leave. Al-Hasan (ع) would come in, see this, and be gladdened by it, saying: "Thus we used to do with our friends."', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'the companions of al hasan ع used to eat whatever they found in his house without asking leave al hasan ع would come in see this and be gladdened by it saying thus we used to do with our friends', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 33, NULL, 'It is narrated that one day al-Hasan passed through the market, taking now from this basket and now from that, and eating as he went. Hisham said to him: "What has come over you, O Abu Said, in your scrupulousness — eating a man''s goods without his leave?" Al-Hasan said: "Recite to me the verse of eating." Hisham recited until he reached the words of God Most High, أَوْ صَدِيقُكُمْ. The verse struck him, and he asked: "And who is the friend?" Al-Hasan said: "The one in whom the soul finds rest and in whom the heart is at ease." Many narrations and the practice of the righteous run in this way.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'it is narrated that one day al hasan passed through the market taking now from this basket and now from that and eating as he went hisham said to him what has come over you o abu said in your scrupulousness eating a mans goods without his leave al hasan said recite to me the verse of eating hisham recited until he reached the words of god most high او صديقكم the verse struck him and he asked and who is the friend al hasan said the one in whom the soul finds rest and in whom the heart is at ease many narrations and the practice of the righteous run in this way', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 34, NULL, 'The guest, if offered a choice among the foods, should choose freely and not count it a breach of the bond between them. Among the marks of noble character: when a man is pressed by invitations from two quarters, he does not prefer one over the other on grounds of wealth or poverty, or of distance and proximity — he answers the first invitation. He should give precedence to the invitation of the poor and the stranger, since such a person may not be able to extend hospitality a second time. He declines when the one inviting is a tyrant, a transgressor, or a man of evil.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'the guest if offered a choice among the foods should choose freely and not count it a breach of the bond between them among the marks of noble character when a man is pressed by invitations from two quarters he does not prefer one over the other on grounds of wealth or poverty or of distance and proximity he answers the first invitation he should give precedence to the invitation of the poor and the stranger since such a person may not be able to extend hospitality a second time he declines when the one inviting is a tyrant a transgressor or a man of evil', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 35, NULL, 'Beyond this, of the guest''s conduct:', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'beyond this of the guests conduct', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 36, NULL, 'He should not intend, by his acceptance, the satisfying of his own appetite, but the gladdening of the heart of the one who invited him. He should not enter the house without permission. He should not crowd those gathered there, but sit wherever tranquility and dignity are possible for him. He should not fix his gaze on the place from which the food is brought out. When seated among people, he should give particular attention to those nearest him, in courtesy and well-being.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'he should not intend by his acceptance the satisfying of his own appetite but the gladdening of the heart of the one who invited him he should not enter the house without permission he should not crowd those gathered there but sit wherever tranquility and dignity are possible for him he should not fix his gaze on the place from which the food is brought out when seated among people he should give particular attention to those nearest him in courtesy and well being', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 37, NULL, 'On the manners of the host.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'on the manners of the host', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 38, NULL, 'The Messenger of God said: "لَا خَيْرَ فِيمَنْ لَا يُضِيفُ" — "There is no good in one who does not offer hospitality." And he said: "Take trouble for the guest."', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'the messenger of god said لا خير فيمن لا يضيف there is no good in one who does not offer hospitality and he said take trouble for the guest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 39, NULL, 'The Messenger of God passed by a woman who had abundant flocks and herds and did not extend hospitality to him; then he passed by a woman who had only a few small ewes, and she slaughtered for him. He said: "Look at her. These characters are in the hand of God: whoever He wishes to grant a good character, He grants it."', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'the messenger of god passed by a woman who had abundant flocks and herds and did not extend hospitality to him then he passed by a woman who had only a few small ewes and she slaughtered for him he said look at her these characters are in the hand of god whoever he wishes to grant a good character he grants it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 40, NULL, 'The host should not intend by his invitation display and boasting; he should intend by it the gladdening of the hearts of the brethren, and the following of the Sunnah of the Messenger of God in feeding food and bringing joy to the hearts of the believers. He should give particular regard, in his invitation, to people of merit and knowledge and to the chosen among hearts, even if they be of modest means rather than wealthy. He should clean the house in which he receives his guests and attend to whatever belongs to the honoring of guests. He should observe the appointed times of those he has invited, so as not to weary them with waiting. If some of those invited are late beyond the appointed hour, it is the right of those present that the food be set before them without awaiting the rest; if only a short while passes in waiting for the remainder, there is no harm in it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'the host should not intend by his invitation display and boasting he should intend by it the gladdening of the hearts of the brethren and the following of the sunnah of the messenger of god in feeding food and bringing joy to the hearts of the believers he should give particular regard in his invitation to people of merit and knowledge and to the chosen among hearts even if they be of modest means rather than wealthy he should clean the house in which he receives his guests and attend to whatever belongs to the honoring of guests he should observe the appointed times of those he has invited so as not to weary them with waiting if some of those invited are late beyond the appointed hour it is the right of those present that the food be set before them without awaiting the rest if only a short while passes in waiting for the remainder there is no harm in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 41, NULL, 'And of the completeness of honoring:', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'and of the completeness of honoring', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 42, NULL, 'Sayingوَطِيبُ الْحَدِيثِ وَإِظْهَارُ التَّقْصِيرِ فِي الْخِدْمَةِ وَالْوَدَاعُ إِلَى بَابِ الدَّارِ حِينَ الْانْصِرَافِ', '', 'وَطِيبُ الْحَدِيثِ وَإِظْهَارُ التَّقْصِيرِ فِي الْخِدْمَةِ وَالْوَدَاعُ إِلَى بَابِ الدَّارِ حِينَ الْانْصِرَافِ', 'Saying', NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'sayingوطيب الحديث واظهار التقصير في الخدمه والوداع الي باب الدار حين الانصراف', 'وطيب الحديث واظهار التقصير في الخدمه والوداع الي باب الدار حين الانصراف');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'at the table: eating, feeding, and being fed', '2. At the Table: Eating, Feeding, and Being Fed', 43, NULL, 'a cheerful face, pleasant speech, the acknowledgment of one''s own shortcoming in service, and the farewell taken at the door of the house at the time of departure.', '', NULL, NULL, NULL, NULL, 'sharh al masail 2 at the table eating feeding and being fed', 'a cheerful face pleasant speech the acknowledgment of ones own shortcoming in service and the farewell taken at the door of the house at the time of departure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 1, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'verse', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 2, NULL, 'Al-Ma''idah: 3حُرِّمَتْ عَلَيْكُمُ ٱلْمَيْتَةُ وَٱلدَّمُ وَلَحْمُ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ وَٱلْمُنْخَنِقَةُ وَٱلْمَوْقُوذَةُ وَٱلْمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ', '', 'حُرِّمَتْ عَلَيْكُمُ ٱلْمَيْتَةُ وَٱلدَّمُ وَلَحْمُ ٱلْخِنزِيرِ وَمَآ أُهِلَّ لِغَيْرِ ٱللَّهِ بِهِۦ وَٱلْمُنْخَنِقَةُ وَٱلْمَوْقُوذَةُ وَٱلْمُتَرَدِّيَةُ وَٱلنَّطِيحَةُ وَمَآ أَكَلَ ٱلسَّبُعُ إِلَّا مَا ذَكَّيْتُمْ وَمَا ذُبِحَ عَلَى ٱلنُّصُبِ', 'Al-Ma''idah: 3', 5, 3, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'al maidah 3حرمت عليكم الميته والدم ولحم الخنزير وما اهل لغير الله به والمنخنقه والموقوذه والمترديه والنطيحه وما اكل السبع الا ما ذكيتم وما ذبح علي النصب', 'حرمت عليكم الميته والدم ولحم الخنزير وما اهل لغير الله به والمنخنقه والموقوذه والمترديه والنطيحه وما اكل السبع الا ما ذكيتم وما ذبح علي النصب');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 3, NULL, 'It is related from Mawla Jafar ibn Muhammad (ع) that he set out what is lawful and what is forbidden in a concise summary. The lawful foods from the earth''s produce fall into three classes:', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'it is related from mawla jafar ibn muhammad ع that he set out what is lawful and what is forbidden in a concise summary the lawful foods from the earths produce fall into three classes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 4, NULL, 'Grains in all their varieties — wheat, barley, and the rest; Fruits, of every kind; Vegetables and growing plants.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'grains in all their varieties wheat barley and the rest fruits of every kind vegetables and growing plants', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 5, NULL, 'Whatever among these nourishes, benefits, and strengthens a person is lawful; whatever causes harm is forbidden, except when taken as medicine for treatment.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'whatever among these nourishes benefits and strengthens a person is lawful whatever causes harm is forbidden except when taken as medicine for treatment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 6, NULL, 'Of animal flesh, what is lawful includes the cow, the camel, and the sheep, together with what comes from them. Among wild animals, everything that has neither fang nor claw is lawful — the gazelle and the hare, for instance, both of which are cloven-hoofed. Among birds, everything that has a crop. Among the game of the sea, everything that has scales. Whatever falls outside these classes is forbidden. As for eggs: an egg whose two ends differ in shape is lawful; an egg whose two ends are alike belongs to a creature whose flesh is not eaten. The creeping things of the earth — the snake, the scorpion, and their like — are forbidden as food.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'of animal flesh what is lawful includes the cow the camel and the sheep together with what comes from them among wild animals everything that has neither fang nor claw is lawful the gazelle and the hare for instance both of which are cloven hoofed among birds everything that has a crop among the game of the sea everything that has scales whatever falls outside these classes is forbidden as for eggs an egg whose two ends differ in shape is lawful an egg whose two ends are alike belongs to a creature whose flesh is not eaten the creeping things of the earth the snake the scorpion and their like are forbidden as food', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 7, NULL, 'A dispensation exists concerning the food of the People of the Book and other sects, provided the food contains nothing slaughtered by an idolater. The slaughter of Jews, Christians, and Magians is lawful to eat when it has been carried out according to the conditions of proper slaughter.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'a dispensation exists concerning the food of the people of the book and other sects provided the food contains nothing slaughtered by an idolater the slaughter of jews christians and magians is lawful to eat when it has been carried out according to the conditions of proper slaughter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 8, NULL, 'The Imams (عَلَيْهِمُ السَّلَامُ) considered it disagreeable to eat the glands, the marrow of the spine, the spleen, and the gall bladder, and likewise the tortoise, the crab, and creatures that come out of shells. The horse, the mule, and the donkey are animals for riding and for carrying loads; yet the horse, if slaughtered out of necessity, is lawful to eat. The donkey and the mule, however, are forbidden.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'the imams عليهم السلام considered it disagreeable to eat the glands the marrow of the spine the spleen and the gall bladder and likewise the tortoise the crab and creatures that come out of shells the horse the mule and the donkey are animals for riding and for carrying loads yet the horse if slaughtered out of necessity is lawful to eat the donkey and the mule however are forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 9, NULL, 'A person in genuine need, fearing for his life, who is compelled to eat carrion or some other forbidden thing, may eat until he is satisfied. One compelled by thirst, finding only wine available, may drink until his thirst is quenched — but he may not return to it unless compelled a second time.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'a person in genuine need fearing for his life who is compelled to eat carrion or some other forbidden thing may eat until he is satisfied one compelled by thirst finding only wine available may drink until his thirst is quenched but he may not return to it unless compelled a second time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 10, NULL, 'If a creeping thing without flowing blood — a fly, for instance — falls into a condiment or into oil, removing it leaves no harm, and the food may be eaten. If a creature that has blood dies in it, such as a mouse, the ruling divides: if the substance is liquid, it is wholly spoiled; if it is solid, what surrounds the dead creature is spoiled and the remainder may be eaten. That is the ruling of the Sharia. If someone finds this distasteful, the choice is his — he may eat, or he may refrain, or he may give it to another Muslim who will use it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'if a creeping thing without flowing blood a fly for instance falls into a condiment or into oil removing it leaves no harm and the food may be eaten if a creature that has blood dies in it such as a mouse the ruling divides if the substance is liquid it is wholly spoiled if it is solid what surrounds the dead creature is spoiled and the remainder may be eaten that is the ruling of the sharia if someone finds this distasteful the choice is his he may eat or he may refrain or he may give it to another muslim who will use it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 11, NULL, 'Concerning drink, God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'concerning drink god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 12, NULL, 'Al-Furqan: 48وَأَنزَلْنَا مِنَ ٱلسَّمَآءِ مَآءًۭ طَهُورًۭا"And We sent down from the sky pure water."', '', NULL, 'Al-Furqan: 48', NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'al furqan 48وانزلنا من السماء ماء طهورا and we sent down from the sky pure water', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 13, NULL, 'This covers the water of the sky, of rivers, of springs, and of wells. Likewise lawful are the milk of any animal whose flesh is permitted, and the juice of fruits — whether boiled or unboiled — so long as neither has altered in nature or become intoxicating. If a drink intoxicates, it has become wine, and drinking it is forbidden in the Sharia.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'this covers the water of the sky of rivers of springs and of wells likewise lawful are the milk of any animal whose flesh is permitted and the juice of fruits whether boiled or unboiled so long as neither has altered in nature or become intoxicating if a drink intoxicates it has become wine and drinking it is forbidden in the sharia', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 15, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 16, NULL, 'Al-An''am: 118فَكُلُوا۟ مِمَّا ذُكِرَ ٱسْمُ ٱللَّهِ عَلَيْهِ إِن كُنتُم بِـَٔايَتِهِۦ مُؤْمِنِينَ"So eat of that over which the name of God has been mentioned, if you are believers in His signs."', '', NULL, 'Al-An''am: 118', NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'al anam 118فكلوا مما ذكر اسم الله عليه ان كنتم بايته مومنين so eat of that over which the name of god has been mentioned if you are believers in his signs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 17, NULL, 'It is related in hadith that the Prophet forbade cruelty to animals and forbade the maiming of beasts. If a limb remains hanging after being cut through and the slaughter then follows, the animal is wholly lawful. If, however, a limb is broken off and severed before the slaughter, eating that limb is forbidden.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'it is related in hadith that the prophet forbade cruelty to animals and forbade the maiming of beasts if a limb remains hanging after being cut through and the slaughter then follows the animal is wholly lawful if however a limb is broken off and severed before the slaughter eating that limb is forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 18, NULL, 'Ali (ع) said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'ali ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 19, NULL, 'Sayingإِذَا ذَبَحَ أَحَدُكُمُ الْبَهِيْمَةَ فَعَلَيْهِ أَنْ يَسْتَقْبِلَ بِهَا الْقِبْلَةَ وَيَضَعَهَا عَلَى الْأَرْضِ ثُمَّ يَقُوْلُ بِسْمِ اللَّهِ وَاللَّهُ أَكْبَرُ"When one of you slaughters a beast, let him turn it toward the qibla and lay it upon the ground, then say: In the name of God, and God is the Greatest."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'sayingاذا ذبح احدكم البهيمه فعليه ان يستقبل بها القبله ويضعها علي الارض ثم يقول بسم الله والله اكبر when one of you slaughters a beast let him turn it toward the qibla and lay it upon the ground then say in the name of god and god is the greatest', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 20, NULL, 'The slaughterer cuts through the windpipe with a sharp blade, taking care not to sever the spinal cord, then waits until the animal has died. He lets the blood flow until death is certain, waits for the animal to grow still, and only then removes the head and strips away the hide.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'the slaughterer cuts through the windpipe with a sharp blade taking care not to sever the spinal cord then waits until the animal has died he lets the blood flow until death is certain waits for the animal to grow still and only then removes the head and strips away the hide', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 21, NULL, 'If a man does any of the following through ignorance or forgetfulness, there is no harm in eating the animal:', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'if a man does any of the following through ignorance or forgetfulness there is no harm in eating the animal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 22, NULL, 'He forgets to mention the name of God. He mentions God with glorification and declaration of His unity rather than the prescribed formula. He forgets even that. He slaughters without facing the qibla. The knife runs ahead and severs the head. He cuts below the proper place of slaughter.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'he forgets to mention the name of god he mentions god with glorification and declaration of his unity rather than the prescribed formula he forgets even that he slaughters without facing the qibla the knife runs ahead and severs the head he cuts below the proper place of slaughter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 23, NULL, 'If, however, he deliberately abandons any of these requirements — in defiance of God''s rulings — his slaughter may not be eaten.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'if however he deliberately abandons any of these requirements in defiance of gods rulings his slaughter may not be eaten', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 24, NULL, 'When cattle, buffalo, or other animals bolt at the time of slaughter and resist so that the slaughterer cannot reach the throat — or when an animal falls into a well, cannot be retrieved, and its throat cannot be reached — he may strike or stab it with a spear or sword wherever he is able. If the animal dies from that blow, eating it is permitted.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'when cattle buffalo or other animals bolt at the time of slaughter and resist so that the slaughterer cannot reach the throat or when an animal falls into a well cannot be retrieved and its throat cannot be reached he may strike or stab it with a spear or sword wherever he is able if the animal dies from that blow eating it is permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 25, NULL, 'The Prophet considered it disagreeable to slaughter a milk-giving animal or one bearing young, provided another animal is at hand.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'the prophet considered it disagreeable to slaughter a milk giving animal or one bearing young provided another animal is at hand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 26, NULL, 'The slaughter of a Jew, a Christian, or a Magian is permitted when they mention the name of God over the animal. Whoever among them — or among the Muslims — deliberately abandons that mention and is under suspicion of having done so, his slaughter may not be eaten. Whoever apostatizes from Islam, whether by becoming a Jew, a Christian, or by joining one of the sects, his slaughter is likewise forbidden.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'the slaughter of a jew a christian or a magian is permitted when they mention the name of god over the animal whoever among them or among the muslims deliberately abandons that mention and is under suspicion of having done so his slaughter may not be eaten whoever apostatizes from islam whether by becoming a jew a christian or by joining one of the sects his slaughter is likewise forbidden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 27, NULL, 'A dispensation covers the slaughter performed by a blind person, a woman, or a boy who has not yet reached maturity, provided it is done correctly. It also covers the slaughter of a mute person who understands, holds the mention of the name in his mind, and gestures toward it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'a dispensation covers the slaughter performed by a blind person a woman or a boy who has not yet reached maturity provided it is done correctly it also covers the slaughter of a mute person who understands holds the mention of the name in his mind and gestures toward it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 28, NULL, 'There is no harm in buying and eating meat, eggs, milk, or clarified butter sold in Muslim markets without investigating the one who slaughtered. Whatever is taken from the sea — fish and locusts — is lawful to eat regardless of whether the one who caught it was a Muslim, a Jew, a Christian, or a Magian. What idolaters hunt and bring alive is also lawful to eat.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'there is no harm in buying and eating meat eggs milk or clarified butter sold in muslim markets without investigating the one who slaughtered whatever is taken from the sea fish and locusts is lawful to eat regardless of whether the one who caught it was a muslim a jew a christian or a magian what idolaters hunt and bring alive is also lawful to eat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 30, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 31, NULL, 'Sayingأُحِلَّ لَكُمْ صَيْدُ الْبَحْرِ وَطَعَامُهُ مَتَاعًا لَكُمْ وَلِلسَّيَّارَةِ وَحُرِّمَ عَلَيْكُمْ صَيْدُ الْبَحْرِ مَا دُمْتُمْ حُرُمًا وَإِذَا حَلَلْتُمْ فَاصْطَادُوا"Lawful to you is the game of the sea and its food, a provision for you and for travelers; and the game of the sea is forbidden to you so long as you remain in the state of ihram; and when you have left that state, then hunt."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'sayingاحل لكم صيد البحر وطعامه متاعا لكم وللسياره وحرم عليكم صيد البحر ما دمتم حرما واذا حللتم فاصطادوا lawful to you is the game of the sea and its food a provision for you and for travelers and the game of the sea is forbidden to you so long as you remain in the state of ihram and when you have left that state then hunt', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 32, NULL, 'Game taken within God''s sanctuary is held to be undesirable. Yet should such game take flight and leave the sanctuary, it may lawfully be taken. The Prophet said that a bird caught and then released, and afterward taken again, is lawful for whoever takes it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'game taken within gods sanctuary is held to be undesirable yet should such game take flight and leave the sanctuary it may lawfully be taken the prophet said that a bird caught and then released and afterward taken again is lawful for whoever takes it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 33, NULL, 'There is no harm in eating what trained hunting animals seize — dogs, hunting leopards, falcons, hawks, and other trained beasts and birds — provided:', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'there is no harm in eating what trained hunting animals seize dogs hunting leopards falcons hawks and other trained beasts and birds provided', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 34, NULL, 'the name of God Almighty was spoken at the moment of releasing them, and it is established that the quarry died from the hunting animal''s blow.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'the name of god almighty was spoken at the moment of releasing them and it is established that the quarry died from the hunting animals blow', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 35, NULL, 'If the quarry is found while still alive, it must be slaughtered before it is eaten. If the name of God was omitted at the moment of release, there is still no harm in eating what the dogs or other trained animals have killed. As for a Magian''s dog: when a Muslim, a Jew, or a Christian trains it, takes possession of it, and releases it, eating whatever game it seizes is permitted.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'if the quarry is found while still alive it must be slaughtered before it is eaten if the name of god was omitted at the moment of release there is still no harm in eating what the dogs or other trained animals have killed as for a magians dog when a muslim a jew or a christian trains it takes possession of it and releases it eating whatever game it seizes is permitted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 36, NULL, 'When a hunter cannot reach the quarry in time to slaughter it, and kills it instead with a sword, an arrow, or a spear — wounding it in any part of the body — there is no harm in eating it. The flesh of the wild ass is lawful, and its slaughter differs from that of the domestic donkey.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'when a hunter cannot reach the quarry in time to slaughter it and kills it instead with a sword an arrow or a spear wounding it in any part of the body there is no harm in eating it the flesh of the wild ass is lawful and its slaughter differs from that of the domestic donkey', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 37, NULL, 'If a man shoots at game, strikes it, and the animal then disappears and falls from a height and dies, its flesh may be eaten only if it is known that it died from the shot. If this is not known, it may not be eaten. What is struck with a stone or a pellet may not be eaten unless something with an iron edge reaches it for slaughter before it dies.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'if a man shoots at game strikes it and the animal then disappears and falls from a height and dies its flesh may be eaten only if it is known that it died from the shot if this is not known it may not be eaten what is struck with a stone or a pellet may not be eaten unless something with an iron edge reaches it for slaughter before it dies', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 38, NULL, 'There is no harm in eating the fish and locusts that an idolater or a Magian has caught, when he brings them alive to a Muslim, a Jew, or a Christian and they die in the hands of those persons.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'there is no harm in eating the fish and locusts that an idolater or a magian has caught when he brings them alive to a muslim a jew or a christian and they die in the hands of those persons', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 40, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 41, NULL, 'Sayingوَأَمَّا بِنِعْمَةِ رَبِّكَ تُحِلُّ"And as for the favor of your Lord, by it is the lawful made lawful for you."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'sayingواما بنعمه ربك تحل and as for the favor of your lord by it is the lawful made lawful for you', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 42, NULL, 'And in the hadith:', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'and in the hadith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 43, NULL, 'Sayingلِيُنْفِقْ كُلُّ ذِي سَعَةٍ مِنْ سَعَتِهِ"Let every man of means spend out of his means."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'sayingلينفق كل ذي سعه من سعته let every man of means spend out of his means', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 44, NULL, 'Whoever keeps hair, let him tend it well. Whoever takes a wife, let him honor her. Whoever takes a sandal, let him keep it in good repair. Whoever takes a riding beast, let him give it سعته — its full measure. Whoever takes a garment, let him keep it clean.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'whoever keeps hair let him tend it well whoever takes a wife let him honor her whoever takes a sandal let him keep it in good repair whoever takes a riding beast let him give it سعته its full measure whoever takes a garment let him keep it clean', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 45, NULL, 'The honor due to a garment is its cleanliness; the honor due to a house is its sweeping.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'the honor due to a garment is its cleanliness the honor due to a house is its sweeping', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 46, NULL, 'Mawlana Jafar ibn Muhammad was asked about a man, and the questioner said: "O son of the Messenger of God, is it counted as extravagance that a man should keep many garments — adorning himself with them, and preserving some by means of others?" He replied: "No, that is not extravagance. God loves to see the mark of His favor upon His servant. The blameworthy thing is that a man of سعة should constrict himself, for God Almighty said concerning the man ذي سعة: he ought to spend from what God has given him."', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'mawlana jafar ibn muhammad was asked about a man and the questioner said o son of the messenger of god is it counted as extravagance that a man should keep many garments adorning himself with them and preserving some by means of others he replied no that is not extravagance god loves to see the mark of his favor upon his servant the blameworthy thing is that a man of سعه should constrict himself for god almighty said concerning the man ذي سعه he ought to spend from what god has given him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 47, NULL, 'A man then said to him that the person he held most dear was one who wore coarse cloth, ate food without seasoning, and made himself humble, so that the mark of humility showed plainly upon him. He said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'a man then said to him that the person he held most dear was one who wore coarse cloth ate food without seasoning and made himself humble so that the mark of humility showed plainly upon him he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 48, NULL, 'Sayingوَيْحَكَ إِنَّمَا الْخُشُوعُ فِي الْقَلْبِ لَا فِي اللِّبَاسِ، وَمَا عَلِمْتَ اَنَّ نَبِيَّنَا يُوسُفَ نَبِىَّ ابْنَ النَّبِىِّ كَانَ يَلْبَسُ أَقْبِيَةَ الدِّيبَاجِ مُزَرَّرَةً بِالذَّهَبِ وَيَجْلِسُ مَجْلِسَ فِرْعَوْنَ يَحْكُمُ بَيْنَ النَّاسِ وَإِنَّمَا كَانَ النَّاسُ يَحْتَاجُونَ إِلَى عَدْلِهِ وَقِسْطِهِ"Woe to you!', '', 'وَيْحَكَ إِنَّمَا الْخُشُوعُ فِي الْقَلْبِ لَا فِي اللِّبَاسِ، وَمَا عَلِمْتَ اَنَّ نَبِيَّنَا يُوسُفَ نَبِىَّ ابْنَ النَّبِىِّ كَانَ يَلْبَسُ أَقْبِيَةَ الدِّيبَاجِ مُزَرَّرَةً بِالذَّهَبِ وَيَجْلِسُ مَجْلِسَ فِرْعَوْنَ يَحْكُمُ بَيْنَ النَّاسِ وَإِنَّمَا كَانَ النَّاسُ يَحْتَاجُونَ إِلَى عَدْلِهِ وَقِسْطِهِ', 'Saying', NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'sayingويحك انما الخشوع في القلب لا في اللباس وما علمت ان نبينا يوسف نبي ابن النبي كان يلبس اقبيه الديباج مزرره بالذهب ويجلس مجلس فرعون يحكم بين الناس وانما كان الناس يحتاجون الي عدله وقسطه woe to you', 'ويحك انما الخشوع في القلب لا في اللباس وما علمت ان نبينا يوسف نبي ابن النبي كان يلبس اقبيه الديباج مزرره بالذهب ويجلس مجلس فرعون يحكم بين الناس وانما كان الناس يحتاجون الي عدله وقسطه');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 49, NULL, 'Sufyan al-Thawri entered upon Imam Jafar al-Sadiq (ع) and saw fine garments upon him. He said: "O son of the Messenger of God, you relate to us that Ali used to wear coarse garments, and you wear better than that." The Imam said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'sufyan al thawri entered upon imam jafar al sadiq ع and saw fine garments upon him he said o son of the messenger of god you relate to us that ali used to wear coarse garments and you wear better than that the imam said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 50, NULL, 'Sayingوَيْحَكَ يَا سُفْيَانُ إِنَّ عَلِيًّا كَانَ فِي زَمَانٍ ضَيِّقٍ وَإِنَّ اللَّهَ قَدْ وَسَّعَ عَلَيْنَا وَيُسْتَحَبُّ لِمَنْ وَسَّعَ اللَّهُ عَلَيْهِ أَنْ يُرَى أَثَرُ ذَلِكَ عَلَيْهِ"Woe to you, Sufyan. Ali lived in a time of straitness, and God has widened His provision upon us; and it is fitting for one upon whom God has widened His provision that the mark of it be seen upon him."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'sayingويحك يا سفيان ان عليا كان في زمان ضيق وان الله قد وسع علينا ويستحب لمن وسع الله عليه ان يري اثر ذلك عليه woe to you sufyan ali lived in a time of straitness and god has widened his provision upon us and it is fitting for one upon whom god has widened his provision that the mark of it be seen upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 51, NULL, 'Imam Jafar ibn Muhammad laid down the governing principle on lawful dress in a single statement. Everything the earth produces may be worn without harm, and prayer may be performed in it. From any animal whose flesh is lawful to eat, the hide, wool, hair, and fur are all permissible to wear, provided the animal was slaughtered according to the rite. If it was not, wearing it outside of prayer carries no harm, but prayer may not be performed in it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'imam jafar ibn muhammad laid down the governing principle on lawful dress in a single statement everything the earth produces may be worn without harm and prayer may be performed in it from any animal whose flesh is lawful to eat the hide wool hair and fur are all permissible to wear provided the animal was slaughtered according to the rite if it was not wearing it outside of prayer carries no harm but prayer may not be performed in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 52, NULL, 'The Messenger of God loved white cotton garments, and he used to say:', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'the messenger of god loved white cotton garments and he used to say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 53, NULL, 'Sayingاِلْبَسُوا الْبَيَاضَ وَكَفِّنُوا فِيهِ مَوْتَاكُمْ"Wear white, and shroud your dead in it."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'sayingالبسوا البياض وكفنوا فيه موتاكم wear white and shroud your dead in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 54, NULL, 'If a man wears silk and prays in it — not intending thereby any display or boasting before his companions — there is no harm in it. It is related of Jafar ibn Muhammad that he was seen seated upon a carpet bearing figures; when this was put to him, he said that the Sunnah is that such things be trodden upon.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'if a man wears silk and prays in it not intending thereby any display or boasting before his companions there is no harm in it it is related of jafar ibn muhammad that he was seen seated upon a carpet bearing figures when this was put to him he said that the sunnah is that such things be trodden upon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 55, NULL, 'For a woman, the following rules govern adornment:', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'for a woman the following rules govern adornment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 56, NULL, 'The neck, the hand, and the foot are the places of adornment. It is not fitting for her to go without ornament, whether of gold or of silver. She is forbidden to strike the ground with her foot so that the sound of her anklet is heard.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'the neck the hand and the foot are the places of adornment it is not fitting for her to go without ornament whether of gold or of silver she is forbidden to strike the ground with her foot so that the sound of her anklet is heard', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'clean and unclean: meat, the knife, and the hunt', '3. Clean and Unclean: Meat, the Knife, and the Hunt', 57, NULL, 'For men, adorning oneself with gold is forbidden, though for young girls and for women there is no harm in it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 3 clean and unclean meat the knife and the hunt', 'for men adorning oneself with gold is forbidden though for young girls and for women there is no harm in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 0, NULL, 'God Most High said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'god most high said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 1, NULL, 'An-Nisa: 29وَلَا تَأْكُلُوا أَمْوَالَكُم بَيْنَكُم بِالْبَاطِلِ إِلَّا أَن تَكُونَ تِجَارَةً عَن تَرَاضٍ"Do not consume one another''s wealth wrongfully, unless it be through trade conducted with mutual consent."', '', NULL, 'An-Nisa: 29', NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'an nisa 29ولا تاكلوا اموالكم بينكم بالباطل الا ان تكون تجاره عن تراض do not consume one anothers wealth wrongfully unless it be through trade conducted with mutual consent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 2, NULL, 'There is likewise a hadith in which the Prophet (صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ) forbade the sale of pebbles, and forbade deception (الْخَدِيعَة), fraud (اَلْغِشّْ), and sales involving uncertainty (اَلْغَرَر).', '', NULL, NULL, NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'there is likewise a hadith in which the prophet صلي الله عليه وسلم forbade the sale of pebbles and forbade deception الخديعه fraud الغش and sales involving uncertainty الغرر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 3, NULL, 'A valid sale rests upon three pillars: the contracting parties, the object contracted over, and the wording or act by which the contract of sale is established.', '', NULL, NULL, NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'a valid sale rests upon three pillars the contracting parties the object contracted over and the wording or act by which the contract of sale is established', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 4, NULL, 'The first pillar is the contracting party. The buyer must not be a minor, insane, or blind, for none of these is regarded as a competent transactor.', '', NULL, NULL, NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'the first pillar is the contracting party the buyer must not be a minor insane or blind for none of these is regarded as a competent transactor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 5, NULL, 'The second pillar is the object of the contract — the thing sold — which must be capable of being transferred from the possession of the one who releases it to the other. Five conditions govern it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'the second pillar is the object of the contract the thing sold which must be capable of being transferred from the possession of the one who releases it to the other five conditions govern it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 6, NULL, 'The thing sold must not be something whose consumption is forbidden. If it can be put to a use other than consumption, buying and selling it is permissible:', '', NULL, NULL, NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'the thing sold must not be something whose consumption is forbidden if it can be put to a use other than consumption buying and selling it is permissible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 7, NULL, '- a dog or cheetah kept for guarding, hunting, or tracking; - the dung of animals whose meat is not eaten, for use as fuel or for treating wounds; - elephants, for riding and bearing heavy loads; - snakes and scorpions, for medical use; - livestock and birds whose meat is consumed, whether they have come to their owner or been acquired.', '', NULL, NULL, NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'a dog or cheetah kept for guarding hunting or tracking the dung of animals whose meat is not eaten for use as fuel or for treating wounds elephants for riding and bearing heavy loads snakes and scorpions for medical use livestock and birds whose meat is consumed whether they have come to their owner or been acquired', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 8, NULL, 'Creatures such as parrots, peacocks, and the like may also be sold. The exception is a dog kept for no purpose whatsoever — its sale is not permissible. Idols may be sold if they are reshaped into something of sound use or kept as relics. Impurities and refuse may be sold for use in agriculture.', '', NULL, NULL, NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'creatures such as parrots peacocks and the like may also be sold the exception is a dog kept for no purpose whatsoever its sale is not permissible idols may be sold if they are reshaped into something of sound use or kept as relics impurities and refuse may be sold for use in agriculture', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 9, NULL, 'Both the object sold and the one who disposes of it must belong to their rightful owners, or the owner must have granted permission. The object must be in possession, and possession takes two forms, since property falls into two categories — movable and immovable. Movable property, such as a horse or a book, can be transferred from place to place; possession passes to the buyer when the seller''s right and discretion transfer through inspection, testing, and receipt. Immovable property, such as land, cannot be moved from its location; possession passes when the buyer vacates it of whatever remained there at the time of sale. Accordingly, anything bought or sold before possession is taken constitutes an invalid sale. The object must be capable of actual delivery, both in law and in fact. What cannot plainly be delivered may not be sold: air, fish still in the water, a fetus still in the womb, the stud of a male animal, something depicted on an animal''s back, milk still in the udder, and things of that kind. All of these are indeterminate because they cannot be clearly separated from what is not being sold. An exception is made where the impure or excluded portion is set aside and the remainder is sold — as when milk in an udder is sold together with milk already drawn out. Delivery may also be impossible in law, as with mortgaged or suspended property: the period of the mortgage keeps the property in the creditor''s hands, and an arrested asset remains in the hands of its holder, leaving the seller unable to deliver it. The object must be specified in its essence, its quantity, and its description. If it is not identified — as when the seller says to the buyer, "I sold you one animal from this herd," or "ten cubits from this land," or "a garment from among these garments, take whichever you like" — the transaction is corrupt. The seller must instead mark out and describe the object with sufficient detail. A sale is valid when its object is clearly specified by description, the seller characterizing and informing the buyer about the thing if it is not immediately present, so that the buyer''s mind is put at ease regarding the described item. When the object of sale is plainly present at the time of the contract, the sale is valid and permissible.', '', NULL, NULL, NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'both the object sold and the one who disposes of it must belong to their rightful owners or the owner must have granted permission the object must be in possession and possession takes two forms since property falls into two categories movable and immovable movable property such as a horse or a book can be transferred from place to place possession passes to the buyer when the sellers right and discretion transfer through inspection testing and receipt immovable property such as land cannot be moved from its location possession passes when the buyer vacates it of whatever remained there at the time of sale accordingly anything bought or sold before possession is taken constitutes an invalid sale the object must be capable of actual delivery both in law and in fact what cannot plainly be delivered may not be sold air fish still in the water a fetus still in the womb the stud of a male animal something depicted on an animals back milk still in the udder and things of that kind all of these are indeterminate because they cannot be clearly separated from what is not being sold an exception is made where the impure or excluded portion is set aside and the remainder is sold as when milk in an udder is sold together with milk already drawn out delivery may also be impossible in law as with mortgaged or suspended property the period of the mortgage keeps the property in the creditors hands and an arrested asset remains in the hands of its holder leaving the seller unable to deliver it the object must be specified in its essence its quantity and its description if it is not identified as when the seller says to the buyer i sold you one animal from this herd or ten cubits from this land or a garment from among these garments take whichever you like the transaction is corrupt the seller must instead mark out and describe the object with sufficient detail a sale is valid when its object is clearly specified by description the seller characterizing and informing the buyer about the thing if it is not immediately present so that the buyers mind is put at ease regarding the described item when the object of sale is plainly present at the time of the contract the sale is valid and permissible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 10, NULL, 'The third pillar is the wording and the act by which the contract of sale is established and the object transferred from one party to the other. Such transfer may take many forms: mortgage, exchange, loan for use, and others. What must exist between the two persons is offer and acceptance, whether explicit or figurative. The seller says, "I sell you this," and the buyer says, "I have taken it" — whether in explicit terms indicating sale, or in accepted figurative expressions and customary usages that convey the meaning of a contract of sale. Where the terms convey nothing intelligible, the sale is not valid. If the seller wishes to exercise the right of option in the sale and to add to the base price, that option is his.', '', NULL, NULL, NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'the third pillar is the wording and the act by which the contract of sale is established and the object transferred from one party to the other such transfer may take many forms mortgage exchange loan for use and others what must exist between the two persons is offer and acceptance whether explicit or figurative the seller says i sell you this and the buyer says i have taken it whether in explicit terms indicating sale or in accepted figurative expressions and customary usages that convey the meaning of a contract of sale where the terms convey nothing intelligible the sale is not valid if the seller wishes to exercise the right of option in the sale and to add to the base price that option is his', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 11, NULL, 'There is no harm in selling dates, raisins, grapes, and other fruits while they are still on the vine or tree, until they wither. There is no harm in buying something from a thief, an oppressor, or a betrayer, provided one knows with certainty that the item in question did not come from betrayal, theft, or oppression.', '', NULL, NULL, NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'there is no harm in selling dates raisins grapes and other fruits while they are still on the vine or tree until they wither there is no harm in buying something from a thief an oppressor or a betrayer provided one knows with certainty that the item in question did not come from betrayal theft or oppression', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 12, NULL, 'The Messenger of God (صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ) forbade النجش, which is the artificial inflating of the price of a commodity by one who has no genuine intention to buy, but who hears of another''s interest and drives him on to purchase. No one should outbid the offer of his brother.', '', NULL, NULL, NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'the messenger of god صلي الله عليه وسلم forbade النجش which is the artificial inflating of the price of a commodity by one who has no genuine intention to buy but who hears of anothers interest and drives him on to purchase no one should outbid the offer of his brother', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 13, NULL, 'If a man sells his house or other property on the condition that, should the buyer bring the price within a known period, the property be returned to him, then during that period any increase and any decrease belong to the buyer. It is incumbent upon the seller, if there is a defect in the sold item, to disclose it to the buyer; otherwise the buyer may return the item, if he wishes, once he becomes aware of the defect.', '', NULL, NULL, NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'if a man sells his house or other property on the condition that should the buyer bring the price within a known period the property be returned to him then during that period any increase and any decrease belong to the buyer it is incumbent upon the seller if there is a defect in the sold item to disclose it to the buyer otherwise the buyer may return the item if he wishes once he becomes aware of the defect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the anatomy of a sale', '4. The Anatomy of a Sale', 14, NULL, 'If a dispute arises between seller and buyer — the buyer claiming to have paid the price and the seller denying it — and the dispute concerns property of a kind over which people do not ordinarily draw up documents, then the ruling is this: if the item is in the buyer''s possession, the buyer''s word is taken; if it has not left the seller''s hands, the seller''s word is taken, along with an oath that he did not receive the price. Neither party need take an oath if the sale is plain. If the sale concerns property of the kind that people ordinarily document — such as a horse, a house, or land — and the two differ over payment of the price, then the burden of proof falls upon the buyer to show that he paid what was due; otherwise the seller swears that he was not paid, as he denies it, and the price is handed over to him.', '', NULL, NULL, NULL, NULL, 'sharh al masail 4 the anatomy of a sale', 'if a dispute arises between seller and buyer the buyer claiming to have paid the price and the seller denying it and the dispute concerns property of a kind over which people do not ordinarily draw up documents then the ruling is this if the item is in the buyers possession the buyers word is taken if it has not left the sellers hands the sellers word is taken along with an oath that he did not receive the price neither party need take an oath if the sale is plain if the sale concerns property of the kind that people ordinarily document such as a horse a house or land and the two differ over payment of the price then the burden of proof falls upon the buyer to show that he paid what was due otherwise the seller swears that he was not paid as he denies it and the price is handed over to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 0, NULL, 'God Most High, the Lord of charity, has granted that a loan made with the sincere intention of earning reward in the Hereafter is itself charity. He said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'god most high the lord of charity has granted that a loan made with the sincere intention of earning reward in the hereafter is itself charity he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 1, NULL, 'Saying⟪وَمَا آتَيْتُم مِّن رِّبًا لِّيَرْبُوَ فِي أَمْوَالِ النَّاسِ فَلَا يَرْبُو عِندَ اللَّهِ وَمَا آتَيْتُم مِّن زَكَاةٍ تُرِيدُونَ وَجْهَ اللَّهِ فَأُولَٰئِكَ هُمُ الْمُضْعِفُونَ⟫"Whatever you give as riba so that it may increase through other people''s wealth does not increase with God; but whatever you give in zakah, seeking God''s face, it is they who will receive manifold reward."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 5 lending without riba', 'saying وما اتيتم من ربا ليربو في اموال الناس فلا يربو عند الله وما اتيتم من زكاه تريدون وجه الله فاوليك هم المضعفون whatever you give as riba so that it may increase through other peoples wealth does not increase with god but whatever you give in zakah seeking gods face it is they who will receive manifold reward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 2, NULL, 'The one who gives a loan seeking the benefit of the Hereafter will have it multiplied for him in the next life. It is also said: whoever wishes to cultivate the harvest of the Hereafter, We shall increase it for him; and whoever wishes to cultivate the harvest of this world, We give him of it, though he will have no share in the reward of the Hereafter. It is said as well that whatever God accepts with goodwill is doubled for the giver — multiplied, that is, in the recompense of the next life.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'the one who gives a loan seeking the benefit of the hereafter will have it multiplied for him in the next life it is also said whoever wishes to cultivate the harvest of the hereafter we shall increase it for him and whoever wishes to cultivate the harvest of this world we give him of it though he will have no share in the reward of the hereafter it is said as well that whatever god accepts with goodwill is doubled for the giver multiplied that is in the recompense of the next life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 3, NULL, 'Riba means increase. Not every increase, however, is forbidden; increases arising from sales transactions and similar dealings are not. In the technical sense of Islamic law, riba refers specifically to the increase that accrues on a loan when the lender''s intention is worldly benefit and the principal is returned to him together with that increase. The blessings of God descend only upon the one whose intention in lending is sound.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'riba means increase not every increase however is forbidden increases arising from sales transactions and similar dealings are not in the technical sense of islamic law riba refers specifically to the increase that accrues on a loan when the lenders intention is worldly benefit and the principal is returned to him together with that increase the blessings of god descend only upon the one whose intention in lending is sound', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 4, NULL, 'A loan therefore falls into two categories:', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'a loan therefore falls into two categories', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 5, NULL, 'One in which the lender''s purpose is worldly benefit. One in which the lender''s purpose is the reward of the Hereafter.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'one in which the lenders purpose is worldly benefit one in which the lenders purpose is the reward of the hereafter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 6, NULL, 'Each category depends entirely on the intention of the one who lends, for actions are judged by intentions, and both categories fall within the domain of legally regulated transactions.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'each category depends entirely on the intention of the one who lends for actions are judged by intentions and both categories fall within the domain of legally regulated transactions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 7, NULL, 'A loan intended for worldly benefit, and extended on that basis, means that if the borrower is in a position to repay, the lender has the right to reduce or excuse the repayment, to increase the time allowed while reducing the principal slightly or substantially, or to forgive the debt entirely — and there is reward in each of these.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'a loan intended for worldly benefit and extended on that basis means that if the borrower is in a position to repay the lender has the right to reduce or excuse the repayment to increase the time allowed while reducing the principal slightly or substantially or to forgive the debt entirely and there is reward in each of these', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 8, NULL, 'As for a loan intended for the reward of the Hereafter, that reward is eighteen-fold; twenty-fold for maintaining the bond of brotherhood with a fellow believer; and twenty-four-fold for maintaining the bond of kinship — the latter also extending one''s lifespan, as is related in the chapter on the virtue of charity from the Messenger of God (صلى الله عليه وآله وسلم). The owner of such a loan has no right to benefit from the principal in any way, whether small or great, nor to impose any condition that places a burden on the principal. God Most High has designated every loan made purely for His sake as an act of devotion, and every worldly benefit derived from it is therefore forbidden. Transactions were conducted among the Muslims for God''s sake — that is, as a legitimate loan. Sometimes, even when the time for repayment arrives and the borrower is in hardship, the lender should cancel the arrangement for that period and accept the principal as agreed; and if the borrower is genuinely and visibly in hardship, the lender should grant him additional time and even remit the principal.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'as for a loan intended for the reward of the hereafter that reward is eighteen fold twenty fold for maintaining the bond of brotherhood with a fellow believer and twenty four fold for maintaining the bond of kinship the latter also extending ones lifespan as is related in the chapter on the virtue of charity from the messenger of god صلي الله عليه واله وسلم the owner of such a loan has no right to benefit from the principal in any way whether small or great nor to impose any condition that places a burden on the principal god most high has designated every loan made purely for his sake as an act of devotion and every worldly benefit derived from it is therefore forbidden transactions were conducted among the muslims for gods sake that is as a legitimate loan sometimes even when the time for repayment arrives and the borrower is in hardship the lender should cancel the arrangement for that period and accept the principal as agreed and if the borrower is genuinely and visibly in hardship the lender should grant him additional time and even remit the principal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 9, NULL, 'Such was the case with Abbas ibn Abd al-Muttalib and Uthman ibn Affan, who lent a Muslim man dirhams on the condition of repayment at the coming season. When the agreed time came, the Muslim man said: "If you take your right in full, you bring ruin upon these wretched children. If you take half and leave the other half for my children, I shall give you at the following season twice the remaining half — which would be satisfactory." When the appointed time came and they demanded their right in full, the man had nothing to give them, and the matter reached the Messenger of God (ص). Then this was revealed:', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'such was the case with abbas ibn abd al muttalib and uthman ibn affan who lent a muslim man dirhams on the condition of repayment at the coming season when the agreed time came the muslim man said if you take your right in full you bring ruin upon these wretched children if you take half and leave the other half for my children i shall give you at the following season twice the remaining half which would be satisfactory when the appointed time came and they demanded their right in full the man had nothing to give them and the matter reached the messenger of god ص then this was revealed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 10, NULL, 'Sayingيَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِن كُنتُم مُّؤْمِنِينَ فَإِن لَّمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِّنَ اللَّهِ وَرَسُولِهِ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ وَإِن كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍ وَأَن تَصَدَّقُوا خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', '', 'يَا أَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَذَرُوا مَا بَقِيَ مِنَ الرِّبَا إِن كُنتُم مُّؤْمِنِينَ فَإِن لَّمْ تَفْعَلُوا فَأْذَنُوا بِحَرْبٍ مِّنَ اللَّهِ وَرَسُولِهِ وَإِن تُبْتُمْ فَلَكُمْ رُءُوسُ أَمْوَالِكُمْ لَا تَظْلِمُونَ وَلَا تُظْلَمُونَ وَإِن كَانَ ذُو عُسْرَةٍ فَنَظِرَةٌ إِلَىٰ مَيْسَرَةٍ وَأَن تَصَدَّقُوا خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ', 'Saying', NULL, NULL, 'sharh al masail 5 lending without riba', 'sayingيا ايها الذين امنوا اتقوا الله وذروا ما بقي من الربا ان كنتم مومنين فان لم تفعلوا فاذنوا بحرب من الله ورسوله وان تبتم فلكم رءوس اموالكم لا تظلمون ولا تظلمون وان كان ذو عسره فنظره الي ميسره وان تصدقوا خير لكم ان كنتم تعلمون', 'يا ايها الذين امنوا اتقوا الله وذروا ما بقي من الربا ان كنتم مومنين فان لم تفعلوا فاذنوا بحرب من الله ورسوله وان تبتم فلكم رءوس اموالكم لا تظلمون ولا تظلمون وان كان ذو عسره فنظره الي ميسره وان تصدقوا خير لكم ان كنتم تعلمون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 11, NULL, 'The meaning is this: the believers are called to fear God and to relinquish whatever immediate benefit they have been extracting from a borrower who cannot render it — this, if they are truly people of faith. The goal is that the lender become beloved to God and His Messenger, since the opposite course is nothing less than opposition to God and His Messenger. If the dispute is abandoned and the lender takes only the principal of the loan, he wrongs neither the borrower nor himself by forgoing the increase. A debtor pressed for repayment who cannot render the principal is to be granted respite until ease arrives. And if the entire loan is remitted as charity, that is better — for those who know the secret of brotherhood. Most of the jurists have confused this question. May God grant us and them the strength to grasp its intended meaning.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'the meaning is this the believers are called to fear god and to relinquish whatever immediate benefit they have been extracting from a borrower who cannot render it this if they are truly people of faith the goal is that the lender become beloved to god and his messenger since the opposite course is nothing less than opposition to god and his messenger if the dispute is abandoned and the lender takes only the principal of the loan he wrongs neither the borrower nor himself by forgoing the increase a debtor pressed for repayment who cannot render the principal is to be granted respite until ease arrives and if the entire loan is remitted as charity that is better for those who know the secret of brotherhood most of the jurists have confused this question may god grant us and them the strength to grasp its intended meaning', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 12, NULL, 'Both forms of lending were in use among the Arabs — and among the Christians, the Jews, and their associates — before the appearance of Islam and after it. Before the conquest of Mecca, trade and its prices lay in the grip of the People of the Book, who wronged the Muslims, particularly in transactions involving goods sold on credit or for cash: they gave little money and took much in return, in buying and in selling, until the situation became straitened for the Muslims and they had no stratagem by which to escape it. The Messenger (ص) waited for the appointed time and for the ruling from God. God gave him the conquest of Mecca, which he opened by God''s leave in the eighth year of the Hijra, and with it the strength and standing of the Muslims grew.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'both forms of lending were in use among the arabs and among the christians the jews and their associates before the appearance of islam and after it before the conquest of mecca trade and its prices lay in the grip of the people of the book who wronged the muslims particularly in transactions involving goods sold on credit or for cash they gave little money and took much in return in buying and in selling until the situation became straitened for the muslims and they had no stratagem by which to escape it the messenger ص waited for the appointed time and for the ruling from god god gave him the conquest of mecca which he opened by gods leave in the eighth year of the hijra and with it the strength and standing of the muslims grew', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 13, NULL, 'Then, in the ninth year, this was revealed:', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'then in the ninth year this was revealed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 14, NULL, 'Saying⟪إِنَّمَا الْمُشْرِكُونَ نَجَسٌ فَلَا يَقْرَبُوا الْمَسْجِدَ الْحَرَامَ بَعْدَ عَامِهِمْ هَٰذَا وَإِنْ خِفْتُمْ عَيْلَةً فَسَوْفَ يُغْنِيكُمُ اللَّهُ مِن فَضْلِهِ إِن شَاءَ إِنَّ اللَّهَ عَلِيمٌ حَكِيمٌ⟫"The polytheists are indeed impure, so let them not approach the Sacred Mosque after this year of theirs. If you fear poverty, God will enrich you from His bounty if He wills. God is All-Knowing, All-Wise."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 5 lending without riba', 'saying انما المشركون نجس فلا يقربوا المسجد الحرام بعد عامهم هذا وان خفتم عيله فسوف يغنيكم الله من فضله ان شاء ان الله عليم حكيم the polytheists are indeed impure so let them not approach the sacred mosque after this year of theirs if you fear poverty god will enrich you from his bounty if he wills god is all knowing all wise', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 15, NULL, 'Ali ibn Abi Talib conveyed it to them, as the Messenger (ص) had commanded him regarding the chapter of Baraa, and recited it to the polytheists. The Messenger (ص) then commanded the Muslims to take up trade in grain and other goods themselves and to bring wealth in from outside the community. They continued to bring it through the port of Jidda — the nearest port to Mecca — until trade passed into their hands and their affairs grew strong through it. From that year they were able to pay the zakah on their wealth, and they dealt in both domains: the worldly and the otherworldly. With Muslims in straitened circumstances, they dealt for the benefit of the Hereafter; in buying and selling, they dealt for worldly benefit. When they saw that someone with whom they had a worldly transaction was in hardship, they were lenient regarding any increase owed, or gave the principal of the loan outright as charity, as God Most High had commanded. From such conduct, brotherhood and mutual generosity became firmly established among them, along with a disposition to prefer others over themselves; dealings and bonds of brotherhood multiplied in their hands.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'ali ibn abi talib conveyed it to them as the messenger ص had commanded him regarding the chapter of baraa and recited it to the polytheists the messenger ص then commanded the muslims to take up trade in grain and other goods themselves and to bring wealth in from outside the community they continued to bring it through the port of jidda the nearest port to mecca until trade passed into their hands and their affairs grew strong through it from that year they were able to pay the zakah on their wealth and they dealt in both domains the worldly and the otherworldly with muslims in straitened circumstances they dealt for the benefit of the hereafter in buying and selling they dealt for worldly benefit when they saw that someone with whom they had a worldly transaction was in hardship they were lenient regarding any increase owed or gave the principal of the loan outright as charity as god most high had commanded from such conduct brotherhood and mutual generosity became firmly established among them along with a disposition to prefer others over themselves dealings and bonds of brotherhood multiplied in their hands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 16, NULL, 'They abandoned dealings with non-Muslims out of indignation, remembering how the polytheists had formerly treated them. Their aversion grew to the point that some would not permit dealings with them at all, nor drink water a polytheist had touched, nor eat their food. Yet the Sharia forbids none of that. Even gold received from them is not forbidden in general — only what they slaughter for idols or according to their own creed is what the Sharia forbids, not what polytheists merely handle. Where they are employed outside the governance of Islam, taking a wage from that is permitted, for their creed has no entry into the transaction — as the Shaykh said — and the same applies to what is offered to other than God.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'they abandoned dealings with non muslims out of indignation remembering how the polytheists had formerly treated them their aversion grew to the point that some would not permit dealings with them at all nor drink water a polytheist had touched nor eat their food yet the sharia forbids none of that even gold received from them is not forbidden in general only what they slaughter for idols or according to their own creed is what the sharia forbids not what polytheists merely handle where they are employed outside the governance of islam taking a wage from that is permitted for their creed has no entry into the transaction as the shaykh said and the same applies to what is offered to other than god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 17, NULL, 'The narration transmitted with general application from Mawlana Jafar al-Sadiq (ع) is that he said: it is not fitting for a man among you to enter partnership with a dhimmi, nor to entrust him with goods, nor to leave a deposit with him, nor to give him pure affection. This rests upon the custom that prevailed among the Muslims in earlier times, and is not a declaration that such things are forbidden in the Sharia.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'the narration transmitted with general application from mawlana jafar al sadiq ع is that he said it is not fitting for a man among you to enter partnership with a dhimmi nor to entrust him with goods nor to leave a deposit with him nor to give him pure affection this rests upon the custom that prevailed among the muslims in earlier times and is not a declaration that such things are forbidden in the sharia', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 18, NULL, 'A further category of riba is recorded in the hadith: "الذَّهَبُ بِالذَّهَبِ وَالْفِضَّةُ بِالْفِضَّةِ وَالْبُرُّ بِالْبُرِّ وَالشَّعِيرُ بِالشَّعِيرِ وَالتَّمْرُ بِالتَّمْرِ وَالْمِلْحُ بِالْمِلْحِ مِثْلًا بِمِثْلٍ وَيَدًا بِيَدٍ فَمَنْ زَادَ أَوِ اسْتَزَادَ فَقَدْ أَرْبَى الْآخِذُ وَالْمُعْطِي فِيهِ سَوَاءٌ" — "Gold for gold, silver for silver, wheat for wheat, barley for barley, dates for dates, salt for salt, like for like, hand to hand; whoever gives more or asks for more has dealt in riba, the taker and the giver alike." The reason such commodity-for-commodity exchange existed is that coinage was not yet in general circulation to meet people''s needs — a situation that persisted, and still persists, in parts of Yemen — and so people traded one good directly for another.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'a further category of riba is recorded in the hadith الذهب بالذهب والفضه بالفضه والبر بالبر والشعير بالشعير والتمر بالتمر والملح بالملح مثلا بمثل ويدا بيد فمن زاد او استزاد فقد اربي الاخذ والمعطي فيه سواء gold for gold silver for silver wheat for wheat barley for barley dates for dates salt for salt like for like hand to hand whoever gives more or asks for more has dealt in riba the taker and the giver alike the reason such commodity for commodity exchange existed is that coinage was not yet in general circulation to meet peoples needs a situation that persisted and still persists in parts of yemen and so people traded one good directly for another', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 19, NULL, 'Where coinage is current and people''s needs are met by it — as in India and other lands — barter falls away, and with it this form of riba ceases.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'where coinage is current and peoples needs are met by it as in india and other lands barter falls away and with it this form of riba ceases', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 20, NULL, 'Regarding the property of orphans, God said: "Test the orphans until they reach the age of marriage; and if you find in them sound judgment, hand over their property to them." It is related from Mawlana Jafar (ع) that he said: "The guardian of the orphan, when the orphan reads the Quran, has reached maturity, and sound judgment is discerned in him, hands over his property to him. But if he has reached maturity and has neither sound judgment nor a mind that can be trusted, his property is not handed over to him, and the guardian spends upon him from it with kindness."', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'regarding the property of orphans god said test the orphans until they reach the age of marriage and if you find in them sound judgment hand over their property to them it is related from mawlana jafar ع that he said the guardian of the orphan when the orphan reads the quran has reached maturity and sound judgment is discerned in him hands over his property to him but if he has reached maturity and has neither sound judgment nor a mind that can be trusted his property is not handed over to him and the guardian spends upon him from it with kindness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 21, NULL, 'The ruler withholds the power of disposal from one who squanders his wealth in the wrong place, and transfers it to whoever will administer it properly and meet his necessities. This withholding — whether from an orphan not yet of age or from an adult who squanders — is called الْحَجْر.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'the ruler withholds the power of disposal from one who squanders his wealth in the wrong place and transfers it to whoever will administer it properly and meet his necessities this withholding whether from an orphan not yet of age or from an adult who squanders is called الحجر', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 22, NULL, 'When a merchant''s debts consume or exceed his wealth and his creditors press their claims, the ruler must place him under restraint and take charge of his property. From that property he is given whatever remains due to him: the rent of the house in which he lives, the hire of a mount, or the wage of a hired man. What remains is then divided among the creditors in proportion to their loans. Any outstanding dowry owed to his wife is reckoned alongside the creditors'' claims. If something specifically belonging to a particular claimant is found among the property and that person seeks it, the matter rests with the ruler: if the item is of small value it is given to him; if not, it is kept with the property. The ruler and the lender then make his insolvency publicly known, so that no one may lose money by lending to him. This announcement is called تفليسا, and the one placed under restraint and so declared is called a مُفْلِسَا.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'when a merchants debts consume or exceed his wealth and his creditors press their claims the ruler must place him under restraint and take charge of his property from that property he is given whatever remains due to him the rent of the house in which he lives the hire of a mount or the wage of a hired man what remains is then divided among the creditors in proportion to their loans any outstanding dowry owed to his wife is reckoned alongside the creditors claims if something specifically belonging to a particular claimant is found among the property and that person seeks it the matter rests with the ruler if the item is of small value it is given to him if not it is kept with the property the ruler and the lender then make his insolvency publicly known so that no one may lose money by lending to him this announcement is called تفليسا and the one placed under restraint and so declared is called a مفلسا', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 23, NULL, 'If the borrower continued dealing with people while his debts exceeded his wealth, and no complaint had yet been raised against him — so that he sold his estate or gave it to his children or to others — those dispositions are valid. But if it becomes clear to the judge that he acted with corrupt intent, the judge may annul them.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'if the borrower continued dealing with people while his debts exceeded his wealth and no complaint had yet been raised against him so that he sold his estate or gave it to his children or to others those dispositions are valid but if it becomes clear to the judge that he acted with corrupt intent the judge may annul them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 24, NULL, 'Neither the judge nor the ruler may compel the insolvent debtor at the creditors'' demand; he is instead granted respite until ease comes.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'neither the judge nor the ruler may compel the insolvent debtor at the creditors demand he is instead granted respite until ease comes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 25, NULL, 'A related case: a man incurred debt, was declared insolvent to his creditors, and afterward others lent to him — yet he did not prosper. Those who lent after the declaration of insolvency hold a prior claim over the earlier creditors. The earlier creditors lent while the man was still dealing among people, with some hope of benefit from their wealth, since he was buying and selling. Those who lent afterward, knowing he was destitute, gave only as support and assistance. Whoever lent after the declaration of insolvency therefore has the stronger claim.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'a related case a man incurred debt was declared insolvent to his creditors and afterward others lent to him yet he did not prosper those who lent after the declaration of insolvency hold a prior claim over the earlier creditors the earlier creditors lent while the man was still dealing among people with some hope of benefit from their wealth since he was buying and selling those who lent afterward knowing he was destitute gave only as support and assistance whoever lent after the declaration of insolvency therefore has the stronger claim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'lending without riba', '5. Lending Without Riba', 26, NULL, 'One further matter: the insolvent is not prevented from marrying, nor from other such matters involving dirhams, nor from riding a mount along with his wife. In these the choice remains his, if he wishes.', '', NULL, NULL, NULL, NULL, 'sharh al masail 5 lending without riba', 'one further matter the insolvent is not prevented from marrying nor from other such matters involving dirhams nor from riding a mount along with his wife in these the choice remains his if he wishes', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 0, NULL, 'The rental of a house, a ship, or a riding animal is a permitted contract, whether the animal hired is ridden upon another conveyance or put to some other use. In every case the amount and the term must be specified.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'the rental of a house a ship or a riding animal is a permitted contract whether the animal hired is ridden upon another conveyance or put to some other use in every case the amount and the term must be specified', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 1, NULL, 'If a tenant brings into a rented house something harmful to the property, the choice rests with the owner: he may let the lease stand, or he may put the tenant out. The tenant may do within the house whatever his ordinary occupancy requires, provided it does not harm the building or weaken its structure. Work that damages the house and its fabric is not his to undertake without the owner''s consent. If he carries out such work without permission and damage follows, he bears the liability. If he claims the work was done with the owner''s permission, the burden of proof lies with him: if he establishes it, his word stands; if not, the owner takes the oath and the tenant is held responsible.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'if a tenant brings into a rented house something harmful to the property the choice rests with the owner he may let the lease stand or he may put the tenant out the tenant may do within the house whatever his ordinary occupancy requires provided it does not harm the building or weaken its structure work that damages the house and its fabric is not his to undertake without the owners consent if he carries out such work without permission and damage follows he bears the liability if he claims the work was done with the owners permission the burden of proof lies with him if he establishes it his word stands if not the owner takes the oath and the tenant is held responsible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 2, NULL, 'One who has rented a house that has since fallen into ruin or collapsed has no claim to compel the owner to repair it, but he has a choice: he may remain, or he may depart. There is no objection to a man renting a dwelling, living in part of it, and subletting the rest at a higher rate than he himself pays. Whoever rents a house in which there are trees, and stipulates their fruit, may lawfully eat of it. If the owner stipulates that should the tenant dwell there even a day or two the full month''s rent falls due, that stipulation is valid. Whatever has been agreed must be written down. If nothing is written and a dispute arises between owner and tenant with no supporting proof, the word of the owner prevails. If a man rents a house in which goods belonging to the owner remain, and the owner promises to remove them but fails to do so, rent is owed only for the portion of the house the tenant actually occupied.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'one who has rented a house that has since fallen into ruin or collapsed has no claim to compel the owner to repair it but he has a choice he may remain or he may depart there is no objection to a man renting a dwelling living in part of it and subletting the rest at a higher rate than he himself pays whoever rents a house in which there are trees and stipulates their fruit may lawfully eat of it if the owner stipulates that should the tenant dwell there even a day or two the full months rent falls due that stipulation is valid whatever has been agreed must be written down if nothing is written and a dispute arises between owner and tenant with no supporting proof the word of the owner prevails if a man rents a house in which goods belonging to the owner remain and the owner promises to remove them but fails to do so rent is owed only for the portion of the house the tenant actually occupied', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 3, NULL, 'Whoever hires a particular animal or a particular ship for travel to a known place, and that animal dies or that ship is disabled before the journey begins, the hire is void. If this occurs after he has set out and covered part of the road, he owes according to what he has already traveled. If the hire was contracted for delivery and conveyance without any particular animal or vessel being designated, the contract holds for whatever animal or vessel is provided and the full wage is due. Whoever hires an animal for a fixed period may use it for the purpose for which he hired it, to the degree customary for such use; if he exceeds that degree, he is liable.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'whoever hires a particular animal or a particular ship for travel to a known place and that animal dies or that ship is disabled before the journey begins the hire is void if this occurs after he has set out and covered part of the road he owes according to what he has already traveled if the hire was contracted for delivery and conveyance without any particular animal or vessel being designated the contract holds for whatever animal or vessel is provided and the full wage is due whoever hires an animal for a fixed period may use it for the purpose for which he hired it to the degree customary for such use if he exceeds that degree he is liable', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 4, NULL, 'A further question: when a man hires an animal or a ship on the condition that it bring him to a certain place by a certain day or hour, and stipulates that a later arrival shall reduce the hire, that condition renders the hire contract void. The hirer nonetheless owes the wage originally contracted.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'a further question when a man hires an animal or a ship on the condition that it bring him to a certain place by a certain day or hour and stipulates that a later arrival shall reduce the hire that condition renders the hire contract void the hirer nonetheless owes the wage originally contracted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 5, NULL, 'A further question: whoever hires an animal to reach a known place and then travels beyond it, and the animal perishes, is liable to the owner for its value. If the animal does not perish but the hirer has exceeded the agreed limit, the owner has a choice: he may hold the hirer liable for whatever diminution occurred during the excess period, or he may claim from him the equivalent of the hire for that period.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'a further question whoever hires an animal to reach a known place and then travels beyond it and the animal perishes is liable to the owner for its value if the animal does not perish but the hirer has exceeded the agreed limit the owner has a choice he may hold the hirer liable for whatever diminution occurred during the excess period or he may claim from him the equivalent of the hire for that period', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 6, NULL, 'As for suretyship: when a man stands guarantor for another, or for a person''s safety — undertaking to protect that person and his property and to deliver him unharmed to a known place, or guaranteeing a person''s soundness — such guarantee and suretyship are permitted, and he may take a wage for it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'as for suretyship when a man stands guarantor for another or for a persons safety undertaking to protect that person and his property and to deliver him unharmed to a known place or guaranteeing a persons soundness such guarantee and suretyship are permitted and he may take a wage for it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 7, NULL, 'It is narrated from Mawlana Jafar ibn Muhammad (ع), from his father, and from his forefathers, that the Messenger of Allah ﷺ permitted partnership in profit and in lands. When two men, or three, or more wish to enter into partnership in wealth, each brings out capital equal to that of his partners, or more, or less; they combine it so that it becomes one undivided property, no part distinguishable from another, and then buy and sell in whatever trade they see fit. Profit accrues to each according to his share, and any loss falls upon each according to the measure of his capital.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'it is narrated from mawlana jafar ibn muhammad ع from his father and from his forefathers that the messenger of allah ﷺ permitted partnership in profit and in lands when two men or three or more wish to enter into partnership in wealth each brings out capital equal to that of his partners or more or less they combine it so that it becomes one undivided property no part distinguishable from another and then buy and sell in whatever trade they see fit profit accrues to each according to his share and any loss falls upon each according to the measure of his capital', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 8, NULL, 'The partnership called مضاربة is likewise permitted: the capital comes from one party and the labor from the other, and the profit is divided between them according to the proportion and arrangement they have agreed upon. No portion of any loss falls upon the worker — that is, the مضارب — because the loss returns to the owner of the capital. If, however, the worker departs from his instructions and transgresses them, he is liable for whatever is lost. No valid partnership exists in which a man provides capital on condition that he receive a fixed predetermined portion. Nor should a believer take as a partner one who is not a believer, for that is the field of the believer.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'the partnership called مضاربه is likewise permitted the capital comes from one party and the labor from the other and the profit is divided between them according to the proportion and arrangement they have agreed upon no portion of any loss falls upon the worker that is the مضارب because the loss returns to the owner of the capital if however the worker departs from his instructions and transgresses them he is liable for whatever is lost no valid partnership exists in which a man provides capital on condition that he receive a fixed predetermined portion nor should a believer take as a partner one who is not a believer for that is the field of the believer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 9, NULL, 'Concerning pre-emption — الشفعة: an absent neighbor is waited upon in his right of pre-emption when their road is shared. From Jabir (رضي الله عنه), it is related that he said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'concerning pre emption الشفعه an absent neighbor is waited upon in his right of pre emption when their road is shared from jabir رضي الله عنه it is related that he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 10, NULL, 'Saying«قَضَى النَّبِيُّ بِالشُّفْعَةِ فِي كُلِّ مَا لَمْ يُقْسَمْ، فَإِذَا وَقَعَتِ الْحُدُودُ وَصُرِّفَ الطَّرِيقُ فَلَا شُفْعَةَ حِينَئِذٍ»"The Prophet decreed pre-emption in everything that has not been divided; but when the boundaries have been set and the road turned aside, there is no pre-emption then."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'saying قضي النبي بالشفعه في كل ما لم يقسم فاذا وقعت الحدود وصرف الطريق فلا شفعه حينيذ the prophet decreed pre emption in everything that has not been divided but when the boundaries have been set and the road turned aside there is no pre emption then', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 11, NULL, 'He (ع) said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'he ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 12, NULL, 'Saying«لَيْسَ لِلْجَارِ شُفْعَةٌ»"The neighbor has no right of pre-emption."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'saying ليس للجار شفعه the neighbor has no right of pre emption', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 13, NULL, 'And he said also:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'and he said also', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 14, NULL, 'Saying«شُفْعَةُ الشَّرِيكِ وَاجِبَةٌ إِذَا كَانَ بَيْنَ الْمُسْلِمِينَ، وَلَيْسَ لِلذِّمِّيِّ وَالْكَافِرِ شُفْعَةٌ، لِأَنَّ الشُّفْعَةَ حَقُّ الْمُسْلِمِينَ»"The pre-emption of the partner is binding when it is among Muslims; the protected non-Muslim and the unbeliever have no pre-emption, for pre-emption is a right of the Muslims."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'saying شفعه الشريك واجبه اذا كان بين المسلمين وليس للذمي والكافر شفعه لان الشفعه حق المسلمين the pre emption of the partner is binding when it is among muslims the protected non muslim and the unbeliever have no pre emption for pre emption is a right of the muslims', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 15, NULL, 'Pre-emption is reckoned and apportioned by shares. It does not apply to a ship, to livestock, or to movable goods, but it does apply to things held in common:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'pre emption is reckoned and apportioned by shares it does not apply to a ship to livestock or to movable goods but it does apply to things held in common', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 16, NULL, 'a shared road a shared wall a shared portion of a building a shared door a tree houses within a single quarter', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'a shared road a shared wall a shared portion of a building a shared door a tree houses within a single quarter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 17, NULL, 'When division has fallen between these things, no pre-emption remains. Likewise, after division, no pre-emption exists between the owner of the upper story and the owner of the lower, unless something shared remains between them.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'when division has fallen between these things no pre emption remains likewise after division no pre emption exists between the owner of the upper story and the owner of the lower unless something shared remains between them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 18, NULL, 'The right of pre-emption belongs to the absent and to the minor just as it belongs to the one present and to the adult. A father may therefore exercise pre-emption on behalf of his infant child, a guardian on behalf of the orphan, and the judge on behalf of one who has no guardian. A claimant of pre-emption — whether present or absent, whether or not he knew of the sale — retains his right so long as its time has not passed. In the Sharia, the time of pre-emption is one year for cultivators; for others it follows the custom of the locality in which the claimant resides. Once that time has passed, pre-emption is extinguished.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'the right of pre emption belongs to the absent and to the minor just as it belongs to the one present and to the adult a father may therefore exercise pre emption on behalf of his infant child a guardian on behalf of the orphan and the judge on behalf of one who has no guardian a claimant of pre emption whether present or absent whether or not he knew of the sale retains his right so long as its time has not passed in the sharia the time of pre emption is one year for cultivators for others it follows the custom of the locality in which the claimant resides once that time has passed pre emption is extinguished', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 19, NULL, 'The seller has no standing against a party if he failed to obtain that party''s written testimony and mark at the time of the contract, for without it the one entitled to pre-emption may rise after the sale to press his claim. If the one entitled to pre-emption surrendered his right before the sale and then rose to claim it, he may still do so, because pre-emption is not established until the moment of sale itself. If the claimant comes to the buyer and the buyer says, "I bought it for such and such," and the claimant surrenders his right on that basis, and it then becomes known that the buyer paid less, the claimant may return upon him if he wishes. And if the seller reduced the price for the buyer at the time of the contract in the customary manner between contracting parties, that same reduction is granted to the one entitled to pre-emption.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'the seller has no standing against a party if he failed to obtain that partys written testimony and mark at the time of the contract for without it the one entitled to pre emption may rise after the sale to press his claim if the one entitled to pre emption surrendered his right before the sale and then rose to claim it he may still do so because pre emption is not established until the moment of sale itself if the claimant comes to the buyer and the buyer says i bought it for such and such and the claimant surrenders his right on that basis and it then becomes known that the buyer paid less the claimant may return upon him if he wishes and if the seller reduced the price for the buyer at the time of the contract in the customary manner between contracting parties that same reduction is granted to the one entitled to pre emption', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 20, NULL, 'Concerning العارية, the loan for use. God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'concerning العاريه the loan for use god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 21, NULL, 'Saying«وَلَا تَنسَوُا۟ ٱلْفَضْلَ بَيْنَكُمْ»"And do not forget generosity between yourselves."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'saying ولا تنسوا الفضل بينكم and do not forget generosity between yourselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 22, NULL, 'When a man wishes to do a kindness and a good deed, he should begin with those nearest to him, in this order:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'when a man wishes to do a kindness and a good deed he should begin with those nearest to him in this order', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 23, NULL, 'his children the nearest of the believers those next to them the brethren in religion the needy — and the most needy among them is the most deserving of alms and of kindness', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'his children the nearest of the believers those next to them the brethren in religion the needy and the most needy among them is the most deserving of alms and of kindness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 24, NULL, 'Among the Sunnah of the Messenger of Allah ﷺ was that he would offer a loan, grant the article on loan, and receive the guest hospitably. The loaned article remains the property of the one who lent it, and the borrower may use it only for what the lender permitted him.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'among the sunnah of the messenger of allah ﷺ was that he would offer a loan grant the article on loan and receive the guest hospitably the loaned article remains the property of the one who lent it and the borrower may use it only for what the lender permitted him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 25, NULL, 'A further question. If the borrower stood as guarantor for the loaned article and then destroyed it — or destroyed some part of it, or damaged it — he is liable for what he damaged and destroyed. If he did not stand as guarantor, nothing falls upon him, unless the lender establishes proof that the article was destroyed or damaged through the borrower''s transgression and poor care of it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'a further question if the borrower stood as guarantor for the loaned article and then destroyed it or destroyed some part of it or damaged it he is liable for what he damaged and destroyed if he did not stand as guarantor nothing falls upon him unless the lender establishes proof that the article was destroyed or damaged through the borrowers transgression and poor care of it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 26, NULL, 'A further question. If the borrower claims the loss of the loaned article and has no proof of that, and he is among those suspected of dishonesty and treachery, he is not believed, and he is liable. If the article had been given in pledge, the lender takes it back from the one holding it in pledge.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'a further question if the borrower claims the loss of the loaned article and has no proof of that and he is among those suspected of dishonesty and treachery he is not believed and he is liable if the article had been given in pledge the lender takes it back from the one holding it in pledge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 27, NULL, 'Concerning trusts. God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'concerning trusts god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 28, NULL, 'Saying«إِنَّ ٱللَّهَ يَأْمُرُكُمْ أَن تُؤَدُّوا۟ ٱلْأَمَنَتِ إِلَىٰٓ أَهْلِهَا»"Indeed, God commands you to render back the trusts to those to whom they are due."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'saying ان الله يامركم ان تودوا الامنت الي اهلها indeed god commands you to render back the trusts to those to whom they are due', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 29, NULL, 'And He said also:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'and he said also', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 30, NULL, 'Saying«فَإِنْ أَمِنَ بَعْضُكُم بَعْضًۭا فَلْيُؤَدِّ ٱلَّذِى ٱؤْتُمِنَ أَمَنَتَهُۥ وَلْيَتَّقِ ٱللَّهَ رَبَّهُۥ»"And if one of you entrusts another, let the one entrusted render back his trust, and let him fear God his Lord."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'saying فان امن بعضكم بعضا فليود الذي اوتمن امنته وليتق الله ربه and if one of you entrusts another let the one entrusted render back his trust and let him fear god his lord', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 31, NULL, 'Mawlana Jafar al-Sadiq (ع) said in his counsel to a group of his Shia:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'mawlana jafar al sadiq ع said in his counsel to a group of his shia', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 32, NULL, 'Saying«اللَّهَ اللَّهَ، وَأَدُّوا الْأَمَانَةَ إِلَى الْأَبْيَضِ وَالْأَسْوَدِ، وَإِنْ كَانَ حَرُورِيًّا أَوْ شَامِيًّا، عَدُوًّا كَانَ أَوْ صَدِيقًا»"God, God! Render the trust back to the white and the black, even if he be a Haruri or a Syrian, whether he be an enemy or a friend."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'saying الله الله وادوا الامانه الي الابيض والاسود وان كان حروريا او شاميا عدوا كان او صديقا god god render the trust back to the white and the black even if he be a haruri or a syrian whether he be an enemy or a friend', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 33, NULL, 'A further question. If a man receives a deposit for safekeeping and it is lost or perishes before he has secured it — through no wrongdoing of his own and without his having consumed any of it — then no liability falls upon him and no guarantee is owed by him. The one who holds a deposit and the partner in trade are alike entrusted persons. If the deposit is gone, the one who left it may not accuse the one who held it without establishing proof.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'a further question if a man receives a deposit for safekeeping and it is lost or perishes before he has secured it through no wrongdoing of his own and without his having consumed any of it then no liability falls upon him and no guarantee is owed by him the one who holds a deposit and the partner in trade are alike entrusted persons if the deposit is gone the one who left it may not accuse the one who held it without establishing proof', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 34, NULL, 'A further question. If Zayd handed a deposit to Amr, and Amr later said, "You did indeed deposit it with me, but you instructed me to hand it over to Bakr, and I handed it to him," while Zayd denies having given any such instruction, then the burden of proving that instruction rests upon Amr — it must be shown that Zayd commanded it. If no proof is produced, Zayd takes the oath. If Amr acknowledged that he handed the deposit to Bakr but Bakr denies having received it from him, then the burden of proving the handover rests upon Amr; if no proof is produced, Bakr takes the oath, and the deposit is recovered from Amr.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'a further question if zayd handed a deposit to amr and amr later said you did indeed deposit it with me but you instructed me to hand it over to bakr and i handed it to him while zayd denies having given any such instruction then the burden of proving that instruction rests upon amr it must be shown that zayd commanded it if no proof is produced zayd takes the oath if amr acknowledged that he handed the deposit to bakr but bakr denies having received it from him then the burden of proving the handover rests upon amr if no proof is produced bakr takes the oath and the deposit is recovered from amr', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 35, NULL, 'It is related that during the caliphate of Umar two men came to a wealthy woman of Quraysh and deposited a hundred dinars with her, saying: "Hand it back to us only when we come to you together." They then departed. After a short while, one of them returned alone and told her that his companion had been prevented from returning with him, that he had instructed him to come on his behalf, and he offered her an agreed sign between them. The woman, being of an unsuspecting nature, handed the money to him, and he departed with it. When the second man came and asked her to return his money, she told him that his companion had come with their agreed sign and that she had handed the money over to him. The second man said that he had given no such instruction. They brought the matter before Umar, who did not know how to judge between them, and so he sent them both to Ali (ع). The Master said to the claimant: "If you both instructed her to hand the money back only when you came to her together, then go and bring your companion and take your right."', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'it is related that during the caliphate of umar two men came to a wealthy woman of quraysh and deposited a hundred dinars with her saying hand it back to us only when we come to you together they then departed after a short while one of them returned alone and told her that his companion had been prevented from returning with him that he had instructed him to come on his behalf and he offered her an agreed sign between them the woman being of an unsuspecting nature handed the money to him and he departed with it when the second man came and asked her to return his money she told him that his companion had come with their agreed sign and that she had handed the money over to him the second man said that he had given no such instruction they brought the matter before umar who did not know how to judge between them and so he sent them both to ali ع the master said to the claimant if you both instructed her to hand the money back only when you came to her together then go and bring your companion and take your right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 36, NULL, 'A further question. It is not proper for the one holding a trust to spend anything of what has been deposited with him. A child who has not reached the age of discernment does not bear liability for a deposit.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'a further question it is not proper for the one holding a trust to spend anything of what has been deposited with him a child who has not reached the age of discernment does not bear liability for a deposit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 37, NULL, 'Concerning the pledge, الرهن. God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'concerning the pledge الرهن god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 38, NULL, 'Saying«يا أيها الذين آمنوا إذا تداينتم بدين إلى أجل مسمى فاكتبوه» ... «وَإِن كُنتُمْ عَلَىٰ سَفَرٍۢ وَلَمْ تَجِدُوا۟ كَاتِبًۭا فَرِهَنٌۭ مَّقْبُوضَةٌۭ»"O you who believe, when you contract a debt for a stated term, write it down," to His words, "And if you are upon a journey and find no scribe, then a pledge taken in hand."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'saying يا ايها الذين امنوا اذا تداينتم بدين الي اجل مسمي فاكتبوه وان كنتم علي سفر ولم تجدوا كاتبا فرهن مقبوضه o you who believe when you contract a debt for a stated term write it down to his words and if you are upon a journey and find no scribe then a pledge taken in hand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 39, NULL, 'A hadith runs:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'a hadith runs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 40, NULL, 'Saying«لَأَمِينٌ فِي السَّمَاءِ أَمِينٌ فِي الْأَرْضِ، وَلَوْ أَسْلَفَنِي لَأَدَّيْتُهُ، وَاذْهَبْ بِهِ عَنِّي وَأرْهَنْهُ عِنْدَهُ»"One trusted in heaven is trusted on earth; had he lent to me I would have repaid him. Go on my behalf and pledge it with him."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'saying لامين في السماء امين في الارض ولو اسلفني لاديته واذهب به عني وارهنه عنده one trusted in heaven is trusted on earth had he lent to me i would have repaid him go on my behalf and pledge it with him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 41, NULL, 'The occasion behind this hadith was as follows: guests arrived one day at the Messenger of Allah, and he said to his servant: "Go and borrow flour from such a Jew, to be repaid at a stated term." The Jew said: "I will give nothing until you pledge something with me." The Messenger (ع) then spoke the words of the hadith recorded above.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'the occasion behind this hadith was as follows guests arrived one day at the messenger of allah and he said to his servant go and borrow flour from such a jew to be repaid at a stated term the jew said i will give nothing until you pledge something with me the messenger ع then spoke the words of the hadith recorded above', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 42, NULL, 'The master al-Qadi al-Numan, may God sanctify his soul, said in Kitab al-Daaim:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'the master al qadi al numan may god sanctify his soul said in kitab al daaim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 43, NULL, 'Saying«إِنَّ اللَّهَ سَمَّى الرِّهَانَ مَقْبُوضَةً، فَإِذَا لَمْ يَكُنِ الرَّهْنُ مَقْبُوضًا فَلَيْسَ هُوَ بِرِهَانٍ»"God named pledges as taken in hand; so if the pledge is not taken in hand, it is no pledge at all."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'saying ان الله سمي الرهان مقبوضه فاذا لم يكن الرهن مقبوضا فليس هو برهان god named pledges as taken in hand so if the pledge is not taken in hand it is no pledge at all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 44, NULL, 'The jurists had conflated the rulings of the pledge, failing to distinguish the legal pledge — the particular form — from the customary pledge — the general form. They did not recognize that the legal pledge is a specific category within the broader concept of pledge, nor did they grasp that the pledge questions laid down in the books of jurisprudence concern the legal pledge alone. The result was a failure to tell the two apart, with the mistaken assumption that all pledges are of the legal kind — whereas the legal pledge and the customary pledge are distinct things.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'the jurists had conflated the rulings of the pledge failing to distinguish the legal pledge the particular form from the customary pledge the general form they did not recognize that the legal pledge is a specific category within the broader concept of pledge nor did they grasp that the pledge questions laid down in the books of jurisprudence concern the legal pledge alone the result was a failure to tell the two apart with the mistaken assumption that all pledges are of the legal kind whereas the legal pledge and the customary pledge are distinct things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 45, NULL, 'The legal pledge — from which the Sharia forbids deriving benefit — is that in which the pledger offers something of his own as security when taking a loan from the pledge-holder, with no written document at all. The pledged thing must then pass into the holder''s physical possession; without that, if the debtor denies the debt, the lender has no evidence of his loan except that thing.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'the legal pledge from which the sharia forbids deriving benefit is that in which the pledger offers something of his own as security when taking a loan from the pledge holder with no written document at all the pledged thing must then pass into the holders physical possession without that if the debtor denies the debt the lender has no evidence of his loan except that thing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 46, NULL, 'The customary pledge is that a document is drawn up for the loan the pledge-holder extends to the pledger. If, alongside the writing, property or other goods are pledged — whether handed over into the holder''s possession or not — and their description is recorded in the document, this constitutes additional security only. When a pledge accompanies a written document, the pledge-holder may lawfully derive benefit from the pledged thing if he wishes, because deriving benefit from a pledge that comes with a written document is not what the Sharia forbids.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'the customary pledge is that a document is drawn up for the loan the pledge holder extends to the pledger if alongside the writing property or other goods are pledged whether handed over into the holders possession or not and their description is recorded in the document this constitutes additional security only when a pledge accompanies a written document the pledge holder may lawfully derive benefit from the pledged thing if he wishes because deriving benefit from a pledge that comes with a written document is not what the sharia forbids', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 47, NULL, 'If a pledge is made after the writing, and the document is then lost or destroyed, what remains is only the thing held in the pledge-holder''s possession — as in the legal pledge, where there is no writing and the pledged thing stands as the lender''s proof of his claim against the pledger. Where there is a written document, however, the writing governs the relationship between pledger and pledge-holder. Benefit from the pledged thing after the writing is therefore permitted, whether by way of rent or by dwelling in it. This is the practice current among people in the settled lands: when a man wishes to transact by pledge, the pledger first writes a document for the loan he receives from the pledge-holder, then acknowledges it in clear and unambiguous terms. He may even appoint witnesses and acknowledge before them that he took from such a person such a sum by way of loan, pledging with him such a thing for such a term. The courts record this faithfully in the register of transactions, and if the debtor later denies it, the judge holds him liable and compels repayment. And even if the pledged thing given alongside the document is lost or destroyed, the pledge-holder may still claim his loan from the debtor by that document.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'if a pledge is made after the writing and the document is then lost or destroyed what remains is only the thing held in the pledge holders possession as in the legal pledge where there is no writing and the pledged thing stands as the lenders proof of his claim against the pledger where there is a written document however the writing governs the relationship between pledger and pledge holder benefit from the pledged thing after the writing is therefore permitted whether by way of rent or by dwelling in it this is the practice current among people in the settled lands when a man wishes to transact by pledge the pledger first writes a document for the loan he receives from the pledge holder then acknowledges it in clear and unambiguous terms he may even appoint witnesses and acknowledge before them that he took from such a person such a sum by way of loan pledging with him such a thing for such a term the courts record this faithfully in the register of transactions and if the debtor later denies it the judge holds him liable and compels repayment and even if the pledged thing given alongside the document is lost or destroyed the pledge holder may still claim his loan from the debtor by that document', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 48, NULL, 'Through the spread of writing in the customary pledge, the legal pledge — from which the Sharia forbade benefit — has largely fallen away. This practice brings ease to both pledger and pledge-holder in payment and in profit, widening the avenues of trade and multiplying the means of gain, since the benefit lies on both sides. The pledge-holder holds, in place of the sum advanced, a property or other pledged thing from which benefit accrues until the sum is repaid, just as the pledger gains from what he has received. Set down below are the rulings of the legal pledge as recorded from the earliest times.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'through the spread of writing in the customary pledge the legal pledge from which the sharia forbade benefit has largely fallen away this practice brings ease to both pledger and pledge holder in payment and in profit widening the avenues of trade and multiplying the means of gain since the benefit lies on both sides the pledge holder holds in place of the sum advanced a property or other pledged thing from which benefit accrues until the sum is repaid just as the pledger gains from what he has received set down below are the rulings of the legal pledge as recorded from the earliest times', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 49, NULL, 'It is narrated from Imam Jafar al-Sadiq that he said: "Pledging is permitted in everything — dwellings and lands, whether held purely or in partnership, and ornaments, clothing, animals, grain, and the like — by depositing it in the grip of the one from whom the dirhams are taken, so that it may remain with him as proof against the pledger should he deny the debt. The thing belongs to its owner, so it is not permitted for the holder of the pledge to derive benefit from it in any manner, nor to make away with it. If the pledge perishes, the word is the word of the pledger, and the debt remains upon him for its value. If the holder claims that he returned it, his word is not accepted without proof. If they differ over the amount of the dirhams, the word is the word of the pledger, and upon the holder of the pledge is the proof of the excess he claims. When the pledge reaches its term, it may not be sold except in the presence of the pledger or his agent."', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'it is narrated from imam jafar al sadiq that he said pledging is permitted in everything dwellings and lands whether held purely or in partnership and ornaments clothing animals grain and the like by depositing it in the grip of the one from whom the dirhams are taken so that it may remain with him as proof against the pledger should he deny the debt the thing belongs to its owner so it is not permitted for the holder of the pledge to derive benefit from it in any manner nor to make away with it if the pledge perishes the word is the word of the pledger and the debt remains upon him for its value if the holder claims that he returned it his word is not accepted without proof if they differ over the amount of the dirhams the word is the word of the pledger and upon the holder of the pledge is the proof of the excess he claims when the pledge reaches its term it may not be sold except in the presence of the pledger or his agent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 50, NULL, 'Concerning walls held in common. God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'concerning walls held in common god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 51, NULL, 'Saying«وَلَا تَعْتَدُوٓا۟ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلْمُعْتَدِينَ»"And do not transgress; indeed God does not love the transgressors."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'saying ولا تعتدوا ان الله لا يحب المعتدين and do not transgress indeed god does not love the transgressors', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 52, NULL, 'And the hadith:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'and the hadith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 53, NULL, 'Saying«لَا ضَرَرَ وَلَا ضِرَارَ»"There shall be no harm and no reciprocating harm."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'saying لا ضرر ولا ضرار there shall be no harm and no reciprocating harm', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 54, NULL, 'If the wall between two houses falls, and it stands within the property of one of the two owners, and that owner refuses to rebuild it, the neighbor has no right to compel him. But if it was that owner who demolished it, and the demolition brings harm upon the neighbor, the judge compels him, and rebuilding becomes obligatory upon him. If the wall is held in common, and one of the two calls upon his partner to build it and the other refuses, the one who refuses is compelled to one of three things:', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'if the wall between two houses falls and it stands within the property of one of the two owners and that owner refuses to rebuild it the neighbor has no right to compel him but if it was that owner who demolished it and the demolition brings harm upon the neighbor the judge compels him and rebuilding becomes obligatory upon him if the wall is held in common and one of the two calls upon his partner to build it and the other refuses the one who refuses is compelled to one of three things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 55, NULL, 'That he build it in partnership and pay half its cost. That he permit the other to build it in the place of the wall and consent to that building — in which case he may not place in it any timber, beams, or other things except by mutual consent. That he pay half its cost.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'that he build it in partnership and pay half its cost that he permit the other to build it in the place of the wall and consent to that building in which case he may not place in it any timber beams or other things except by mutual consent that he pay half its cost', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 56, NULL, 'It is not permitted for anyone to open a window in a wall — shared or unshared — through which the interior of a neighbor''s house may be overlooked, except by mutual consent. Nor may a man be prevented from raising his own wall, even if it should come between the sun and his neighbor''s house. There is no objection to a man changing the road to his house or the door of his dwelling if the house opens onto a public thoroughfare; but if it lies within the quarter of a group of people, he may not change it without their permission.', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'it is not permitted for anyone to open a window in a wall shared or unshared through which the interior of a neighbors house may be overlooked except by mutual consent nor may a man be prevented from raising his own wall even if it should come between the sun and his neighbors house there is no objection to a man changing the road to his house or the door of his dwelling if the house opens onto a public thoroughfare but if it lies within the quarter of a group of people he may not change it without their permission', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 57, NULL, 'It is narrated from Mawlana Jafar al-Sadiq that he said: "The division of land and dwellings is of three kinds. The first is the division made by the judge: when the partners are content and competent in the matter, and each of them knows what has been apportioned to him and is satisfied with it, the division is binding among them. The second is the division by trial, which is that what is divided is apportioned by planting when its parts are equal. The third is the division by estimation, which is that it be divided by value when the portions differ and are unequal. Those things which they all require — such as the passageway, the door, the public road among the partners, the well, the courtyard, and the like — remain shared among the partners."', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'it is narrated from mawlana jafar al sadiq that he said the division of land and dwellings is of three kinds the first is the division made by the judge when the partners are content and competent in the matter and each of them knows what has been apportioned to him and is satisfied with it the division is binding among them the second is the division by trial which is that what is divided is apportioned by planting when its parts are equal the third is the division by estimation which is that it be divided by value when the portions differ and are unequal those things which they all require such as the passageway the door the public road among the partners the well the courtyard and the like remain shared among the partners', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'trusts, pledges, and shared walls', '6. Trusts, Pledges, and Shared Walls', 58, NULL, 'Imam al-Sadiq was asked about the division of the upper story and the lower, and upon whom the repair of the roof falls. He said: "Upon the owner of the lower story — for the roof is as ground for the owner of the upper story, who takes benefit from it. If the owner of the upper story causes damage, the repair falls upon him. This ruling holds where the matter has been left unspecified; but where the matter of the roof has been made plain and set down at the time of sale and purchase, then what is written on the document is what governs."', '', NULL, NULL, NULL, NULL, 'sharh al masail 6 trusts pledges and shared walls', 'imam al sadiq was asked about the division of the upper story and the lower and upon whom the repair of the roof falls he said upon the owner of the lower story for the roof is as ground for the owner of the upper story who takes benefit from it if the owner of the upper story causes damage the repair falls upon him this ruling holds where the matter has been left unspecified but where the matter of the roof has been made plain and set down at the time of sale and purchase then what is written on the document is what governs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 0, NULL, 'Marriage itself is among the signs of God. God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'marriage itself is among the signs of god god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 1, NULL, 'Ar-Rum: 21﴿وَمِنْ آيَاتِهِ أَنْ خَلَقَ لَكُمْ مِنْ أَنْفُسِكُمْ أَزْوَاجًا لِتَسْكُنُوا إِلَيْهَا وَجَعَلَ بَيْنَكُمْ مَوَدَّةً وَرَحْمَةً إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يَتَفَكَّرُونَ﴾"And among His signs is that He created for you from yourselves spouses, that you may dwell in tranquility with them, and He placed between you affection and mercy. Indeed in that are signs for a people who give thought."', '', NULL, 'Ar-Rum: 21', NULL, NULL, 'sharh al masail 7 why marry at all', 'ar rum 21 ومن اياته ان خلق لكم من انفسكم ازواجا لتسكنوا اليها وجعل بينكم موده ورحمه ان في ذلك لايات لقوم يتفكرون and among his signs is that he created for you from yourselves spouses that you may dwell in tranquility with them and he placed between you affection and mercy indeed in that are signs for a people who give thought', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 2, NULL, 'And the hadith:', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'and the hadith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 3, NULL, 'Saying«مَنْ أَحَبَّ أَنْ يَلْقَى اللهَ طَاهِرًا مُطَهَّرًا فَلْيَسْتَعْفِفْ بِزَوْجَتِهِ، وَمَنْ أَحَبَّ أَنْ يَكُونَ عَلَى سُنَّتِي فَإِنَّ مِنْ سُنَّتِي النِّكَاحَ»"Whoever loves to meet God pure and purified, let him keep himself chaste through his wife; and whoever loves to be upon my Sunnah, then of my Sunnah is marriage."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 7 why marry at all', 'saying من احب ان يلقي الله طاهرا مطهرا فليستعفف بزوجته ومن احب ان يكون علي سنتي فان من سنتي النكاح whoever loves to meet god pure and purified let him keep himself chaste through his wife and whoever loves to be upon my sunnah then of my sunnah is marriage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 4, NULL, 'It is narrated from Ali (ع) that he said none of the companions of the Messenger of God (صَلَّع) married without the Messenger of God saying to him that he had completed his religion and his faith. Among the manners of the prophets are cleanliness, the trimming of hair, the use of perfume, and frequent recourse to spouses — meaning women — for the more a servant grows in faith, the more his love for his wife grows.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'it is narrated from ali ع that he said none of the companions of the messenger of god صلع married without the messenger of god saying to him that he had completed his religion and his faith among the manners of the prophets are cleanliness the trimming of hair the use of perfume and frequent recourse to spouses meaning women for the more a servant grows in faith the more his love for his wife grows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 5, NULL, 'He (صَلَّع) said that whoever abandons marriage out of fear of the burden of a household has thought ill of his Lord, for God has promised His servants and said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'he صلع said that whoever abandons marriage out of fear of the burden of a household has thought ill of his lord for god has promised his servants and said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 6, NULL, 'An-Nur: 32﴿إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللهُ مِنْ فَضْلِهِ وَاللهُ وَاسِعٌ عَلِيمٌ﴾"If they are poor, God will enrich them from His bounty, and God is Vast and Knowing."', '', NULL, 'An-Nur: 32', NULL, NULL, 'sharh al masail 7 why marry at all', 'an nur 32 ان يكونوا فقراء يغنهم الله من فضله والله واسع عليم if they are poor god will enrich them from his bounty and god is vast and knowing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 7, NULL, 'And he used to say:', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'and he used to say', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 8, NULL, 'Saying«لَا رَهْبَانِيَّةَ فِي الْإِسْلَامِ»"There is no monasticism in Islam."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 7 why marry at all', 'saying لا رهبانيه في الاسلام there is no monasticism in islam', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 9, NULL, 'He forbade celibacy for men and for women alike, and he said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'he forbade celibacy for men and for women alike and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 10, NULL, 'Saying«تَنَاكَحُوا تَكَاثَرُوا فَإِنِّي أُبَاهِي بِكُمُ الْأُمَمَ يَوْمَ الْقِيَامَةِ»"Marry and increase, for I shall boast of you before the nations on the Day of Resurrection."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 7 why marry at all', 'saying تناكحوا تكاثروا فاني اباهي بكم الامم يوم القيامه marry and increase for i shall boast of you before the nations on the day of resurrection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 11, NULL, 'God Almighty, having deposited in the human being manifold interests, faculties, and drives — hunger, thirst, sleep, wakefulness, and others — likewise deposited in him the desire for marriage, which appears at the time of puberty. Just as the Messenger of God (صَلَّع) set down a governing law for each of those drives, so too did he set for this drive its regulating limits, so that a person might be preserved from resembling the beasts and might travel upon the road of the prophets. The human being was created social by nature and cannot manage the whole of his affairs without the help of another. The nearest of those who assist him is his wife. When he goes out to earn his sustenance and to store away a portion of it against a time when illness, weakness, or some other cause prevents him from going out, and when he seeks to guard his children, he must have someone who keeps his house and his furnishings. For that purpose no one is suited except the woman. The mother is the helper in the man''s living, in the ordering of his household, in the sponsorship of his children, their maintenance and their upbringing. As the soundness of the house is not achieved without the woman, so the soundness of the woman is not achieved without the man.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'god almighty having deposited in the human being manifold interests faculties and drives hunger thirst sleep wakefulness and others likewise deposited in him the desire for marriage which appears at the time of puberty just as the messenger of god صلع set down a governing law for each of those drives so too did he set for this drive its regulating limits so that a person might be preserved from resembling the beasts and might travel upon the road of the prophets the human being was created social by nature and cannot manage the whole of his affairs without the help of another the nearest of those who assist him is his wife when he goes out to earn his sustenance and to store away a portion of it against a time when illness weakness or some other cause prevents him from going out and when he seeks to guard his children he must have someone who keeps his house and his furnishings for that purpose no one is suited except the woman the mother is the helper in the mans living in the ordering of his household in the sponsorship of his children their maintenance and their upbringing as the soundness of the house is not achieved without the woman so the soundness of the woman is not achieved without the man', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 12, NULL, 'These two — husband and wife — are the house in truth, whether they dwell beneath a tree in the desert or in some lofty dwelling among the buildings. What is commonly called a house is so named only by figure of speech. The true house is the school of feeling and of upbringing, the place where human character is acquired, where children receive their first nurture, and where the greatest part of their formation comes to them from their mother. In this true house the children obtain the highest foundations of humanity and the lessons of upbringing, and what they attain in the season of childhood accompanies them ever after. It falls upon a man, therefore, to choose from the community the best woman for this school, so that she may be fit for the teaching of children; and none is fit for that except one sound in her body, sound in her soul, and correct in her knowledge. If a woman is without a husband, or a man without a wife, then neither of them has a household in truth, even though they dwell in lofty chambers.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'these two husband and wife are the house in truth whether they dwell beneath a tree in the desert or in some lofty dwelling among the buildings what is commonly called a house is so named only by figure of speech the true house is the school of feeling and of upbringing the place where human character is acquired where children receive their first nurture and where the greatest part of their formation comes to them from their mother in this true house the children obtain the highest foundations of humanity and the lessons of upbringing and what they attain in the season of childhood accompanies them ever after it falls upon a man therefore to choose from the community the best woman for this school so that she may be fit for the teaching of children and none is fit for that except one sound in her body sound in her soul and correct in her knowledge if a woman is without a husband or a man without a wife then neither of them has a household in truth even though they dwell in lofty chambers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 13, NULL, 'What follows from this is that the house is with the woman and the woman is with the house. The aim of the religious Muslim in marriage is nothing other than the obtaining of children and chastity against what is forbidden, as the Quran indicates in His words:', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'what follows from this is that the house is with the woman and the woman is with the house the aim of the religious muslim in marriage is nothing other than the obtaining of children and chastity against what is forbidden as the quran indicates in his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 14, NULL, 'An-Nisa: 24﴿مُحْصِنِينَ غَيْرَ مُسَافِحِينَ﴾"Taking them in chaste wedlock, not in licentiousness."', '', NULL, 'An-Nisa: 24', NULL, NULL, 'sharh al masail 7 why marry at all', 'an nisa 24 محصنين غير مسافحين taking them in chaste wedlock not in licentiousness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 15, NULL, 'The aim of marriage, then, is not the mere discharge of appetite as an animal discharges it, but entry into the fortress of devotion and chastity. The word مُحْصِنِين derives from الإحصان, the verbal noun of الحصن, and الحصن in the language means the fortress. One who marries with a good intention has thereby fortified and protected himself from bodily diseases and from deficiency alike. Even a man who is free in purpose from whisperings and the dangers of appetite is not, while unmarried, free from bodily ailments such as ill temper, coarseness of nature, derangement, constriction, and torpor. Through marriage, moreover, the good qualities of character increase:', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'the aim of marriage then is not the mere discharge of appetite as an animal discharges it but entry into the fortress of devotion and chastity the word محصنين derives from الاحصان the verbal noun of الحصن and الحصن in the language means the fortress one who marries with a good intention has thereby fortified and protected himself from bodily diseases and from deficiency alike even a man who is free in purpose from whisperings and the dangers of appetite is not while unmarried free from bodily ailments such as ill temper coarseness of nature derangement constriction and torpor through marriage moreover the good qualities of character increase', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 16, NULL, 'gravity tranquility forbearance devotion patience gentleness and others besides', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'gravity tranquility forbearance devotion patience gentleness and others besides', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 17, NULL, 'A question arises here. Since the appetite for marriage was placed in human beings by nature — as the other natural drives were placed in them — a person is compelled from within toward its satisfaction. This is evident in the state of the corrupt and dissolute, who find in themselves a compulsion even after committing a vile act, despite its being forbidden. What, then, is the purpose of the encouragement to marry that comes from the Lawgiver, as it is recorded in the Daaim?', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'a question arises here since the appetite for marriage was placed in human beings by nature as the other natural drives were placed in them a person is compelled from within toward its satisfaction this is evident in the state of the corrupt and dissolute who find in themselves a compulsion even after committing a vile act despite its being forbidden what then is the purpose of the encouragement to marry that comes from the lawgiver as it is recorded in the daaim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 18, NULL, 'That encouragement is built upon two causes: one religious, one worldly.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'that encouragement is built upon two causes one religious one worldly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 19, NULL, 'The religious cause concerns those who travel the road of the Hereafter and practice renunciation in this world. When they are absorbed in longing for the Hereafter, they turn away from worldly attachments, and for this reason they are inclined to forgo marriage entirely, since marriage is the first step upon the stairway of worldly attachments. It is narrated from Ali that he said: Uthman ibn Mazun came to the Messenger of God (صَلَّع) and said, "O Messenger of God, the promptings of my soul have overcome me, and I would do nothing until I consult you." The Messenger of God (صَلَّع) said, "With what has your soul prompted you, O Uthman?" He said, "I wished to wander the earth." He said, "Do not wander in it, for the wandering of my community is to the mosques." He said, "Then I resolved to forbid meat to myself." The Messenger of God (صَلَّع) said to him, "Do not do so, for I desire it, and by God, were I to ask God to feed it to me every day He would do so." He said, "And I resolved to castrate myself." He said, "O Uthman, he is not of us who does that to himself. The castration of my community is fasting." He said, "And I resolved to forbid myself Khawla my wife." He said, "Do not do so, O Uthman," and he mentioned the benefits of living with a wife which are set down in the Daaim. Then the Messenger of God (صَلَّع) placed his hand upon his breast and said, "O Uthman, do not turn away from my Sunnah, for whoever turns away from my Sunnah, the angels shall turn away from him on the Day of Resurrection and shall turn his face from my Pool."', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'the religious cause concerns those who travel the road of the hereafter and practice renunciation in this world when they are absorbed in longing for the hereafter they turn away from worldly attachments and for this reason they are inclined to forgo marriage entirely since marriage is the first step upon the stairway of worldly attachments it is narrated from ali that he said uthman ibn mazun came to the messenger of god صلع and said o messenger of god the promptings of my soul have overcome me and i would do nothing until i consult you the messenger of god صلع said with what has your soul prompted you o uthman he said i wished to wander the earth he said do not wander in it for the wandering of my community is to the mosques he said then i resolved to forbid meat to myself the messenger of god صلع said to him do not do so for i desire it and by god were i to ask god to feed it to me every day he would do so he said and i resolved to castrate myself he said o uthman he is not of us who does that to himself the castration of my community is fasting he said and i resolved to forbid myself khawla my wife he said do not do so o uthman and he mentioned the benefits of living with a wife which are set down in the daaim then the messenger of god صلع placed his hand upon his breast and said o uthman do not turn away from my sunnah for whoever turns away from my sunnah the angels shall turn away from him on the day of resurrection and shall turn his face from my pool', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 20, NULL, 'In this same meaning, a narration is recorded from Mawlana Jafar al-Sadiq (ع). He was asked about a man in whom the fear of God had so taken hold that he had abandoned women and wholesome food and would not raise his head to the sky, out of reverence for God Almighty. He said, "As for your words concerning the abandonment of women, you know what the Messenger of God had of them. As for your words concerning the abandonment of wholesome food, the Messenger of God (صَلَّع) loved meat and honey. As for your words that the fear of God so entered him that he cannot raise his head to the sky, humility is in the heart. And who was more fearful of God than the Messenger of God (صَلَّع)? Yet he did not do this." Then he recited the words of God, mighty and majestic:', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'in this same meaning a narration is recorded from mawlana jafar al sadiq ع he was asked about a man in whom the fear of god had so taken hold that he had abandoned women and wholesome food and would not raise his head to the sky out of reverence for god almighty he said as for your words concerning the abandonment of women you know what the messenger of god had of them as for your words concerning the abandonment of wholesome food the messenger of god صلع loved meat and honey as for your words that the fear of god so entered him that he cannot raise his head to the sky humility is in the heart and who was more fearful of god than the messenger of god صلع yet he did not do this then he recited the words of god mighty and majestic', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 21, NULL, 'Al-Ahzab: 21﴿لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللهِ أُسْوَةٌ حَسَنَةٌ لِمَنْ كَانَ يَرْجُو اللهَ وَالْيَوْمَ الْآخِرَ﴾"Indeed there is for you in the Messenger of God a fair example, for whoever hopes in God and the Last Day."', '', NULL, 'Al-Ahzab: 21', NULL, NULL, 'sharh al masail 7 why marry at all', 'al ahzab 21 لقد كان لكم في رسول الله اسوه حسنه لمن كان يرجو الله واليوم الاخر indeed there is for you in the messenger of god a fair example for whoever hopes in god and the last day', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 22, NULL, 'The Lawgiver''s encouragement toward this worldly cause is directed especially at those who are destitute, indigent, or poor — those who forgo marriage because of the narrowness of their provision and livelihood. For this reason it was said that whoever cannot afford a dower should give at least a small portion of one. On this point, narrations from Mawlana Jafar al-Sadiq speak to the smallness of the dower: if a believer finds nothing, then let her dower be a dirham, or a garment, or some small thing; and if he cannot find even these, then let him teach her a sura of the Quran. As for the burden of household and the straitness of livelihood, God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'the lawgivers encouragement toward this worldly cause is directed especially at those who are destitute indigent or poor those who forgo marriage because of the narrowness of their provision and livelihood for this reason it was said that whoever cannot afford a dower should give at least a small portion of one on this point narrations from mawlana jafar al sadiq speak to the smallness of the dower if a believer finds nothing then let her dower be a dirham or a garment or some small thing and if he cannot find even these then let him teach her a sura of the quran as for the burden of household and the straitness of livelihood god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 23, NULL, 'An-Nur: 32﴿وَأَنْكِحُوا الْأَيَامَى مِنْكُمْ وَالصَّالِحِينَ مِنْ عِبَادِكُمْ وَإِمَائِكُمْ إِنْ يَكُونُوا فُقَرَاءَ يُغْنِهِمُ اللهُ مِنْ فَضْلِهِ وَاللهُ وَاسِعٌ عَلِيمٌ﴾"And marry off the single among you and the righteous among your male and female servants. If they are poor, God will enrich them from His bounty, and God is Vast and Knowing."', '', NULL, 'An-Nur: 32', NULL, NULL, 'sharh al masail 7 why marry at all', 'an nur 32 وانكحوا الايامي منكم والصالحين من عبادكم وامايكم ان يكونوا فقراء يغنهم الله من فضله والله واسع عليم and marry off the single among you and the righteous among your male and female servants if they are poor god will enrich them from his bounty and god is vast and knowing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 24, NULL, 'Whoever cannot find a wife, and awaits ease from God in His own time, is to live — man and woman alike — in chastity and devotion until each finds what is hoped for; there is no blame in that.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'whoever cannot find a wife and awaits ease from god in his own time is to live man and woman alike in chastity and devotion until each finds what is hoped for there is no blame in that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 25, NULL, 'There is no doubt that a destitute person standing alone — whether man or woman — cannot drive poverty away without the help of another in earning a living. This is especially so on the Arabian Peninsula, where the only livelihood is agriculture and where years of drought leave houses bare of food and provision. A man there must labor alongside his dependents from the time of sowing to the season of harvest, and the household does not manage with one woman alone; it may require two, or up to four.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'there is no doubt that a destitute person standing alone whether man or woman cannot drive poverty away without the help of another in earning a living this is especially so on the arabian peninsula where the only livelihood is agriculture and where years of drought leave houses bare of food and provision a man there must labor alongside his dependents from the time of sowing to the season of harvest and the household does not manage with one woman alone it may require two or up to four', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 26, NULL, 'This need becomes greater still when hostilities break out among the many tribes, whose enmities run from generation to generation and whose differing creeds deepen the divisions between them. In such conditions a human life is reckoned worth no more than an animal''s, for there is no true government to protect the rights of subjects. When war comes and the men of both sides are killed, widows and orphans are left with no one to guard them from those who overpower and plunder. They are content, then, to enter under a man''s protection and to preserve themselves through marriage, even to one who already has a wife.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'this need becomes greater still when hostilities break out among the many tribes whose enmities run from generation to generation and whose differing creeds deepen the divisions between them in such conditions a human life is reckoned worth no more than an animals for there is no true government to protect the rights of subjects when war comes and the men of both sides are killed widows and orphans are left with no one to guard them from those who overpower and plunder they are content then to enter under a mans protection and to preserve themselves through marriage even to one who already has a wife', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 27, NULL, 'Another reason is particular to that land. Because the Arabian Peninsula lies close to the equator, its heat is intense, and women there lose their beauty and their strength before men do. Moreover, when a woman is with a man, the days of her menstruation, her pregnancy and delivery, and her nursing require that he keep apart from her; or some other cause of separation arises, of the kind to be discussed in what follows. A village man, therefore — whether he seeks chastity or seeks rest amid the toil of earning a living in a state of destitution — cannot easily manage with one wife alone. From the time of the Prophet (صَلَّع) to this day, the necessity that calls for plurality of wives has remained standing among them.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'another reason is particular to that land because the arabian peninsula lies close to the equator its heat is intense and women there lose their beauty and their strength before men do moreover when a woman is with a man the days of her menstruation her pregnancy and delivery and her nursing require that he keep apart from her or some other cause of separation arises of the kind to be discussed in what follows a village man therefore whether he seeks chastity or seeks rest amid the toil of earning a living in a state of destitution cannot easily manage with one wife alone from the time of the prophet صلع to this day the necessity that calls for plurality of wives has remained standing among them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 28, NULL, 'That necessity, however, is not confined to the Arab world, nor to war alone. Many other causes arise among other peoples as well. From the opening of the recent twentieth century alone, several major conflicts may be counted: the war between the English and the Boer people in South Africa, in which great numbers of men and leaders perished; the war involving Japan, in which five hundred thousand men were lost from both sides combined; and many further wars, between small states and great, fought for differing purposes. Each left behind, in its wake, a scarcity of men with no escape.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'that necessity however is not confined to the arab world nor to war alone many other causes arise among other peoples as well from the opening of the recent twentieth century alone several major conflicts may be counted the war between the english and the boer people in south africa in which great numbers of men and leaders perished the war involving japan in which five hundred thousand men were lost from both sides combined and many further wars between small states and great fought for differing purposes each left behind in its wake a scarcity of men with no escape', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 29, NULL, 'The condition of two or three of these states — the English, the French, and the Germans — makes the point plainly, as their own population records show:', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'the condition of two or three of these states the english the french and the germans makes the point plainly as their own population records show', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 30, NULL, 'In France, women outnumbered men by 423,409. In Germany, after the point at which men and women stood equal in count, women exceeded men by 887,648, with no men remaining to marry them, since each man already had a woman his equal in number. In England, women outnumbered men by 182,619.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'in france women outnumbered men by 423 409 in germany after the point at which men and women stood equal in count women exceeded men by 887 648 with no men remaining to marry them since each man already had a woman his equal in number in england women outnumbered men by 182 619', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 31, NULL, 'The total of women in these three states alone, setting aside all others, for whom no marriage partner exists reaches two million four hundred thousand. Those who forbid plurality of wives should be asked what arrangement they have made for these women, and what law they have set down for them — for a law must accord with nature. Either they claim that these women feel none of what other women feel, or they permit them fornication. The children of the bathhouses in those kingdoms run into the thousands every year, and by such vile acts the homes of men afflicted with immorality toward those not their wives have been ruined. Yet for all this want of sight, the opponents censure Islam and say that the Quran gives license to the riding of appetites by permitting plurality of wives.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'the total of women in these three states alone setting aside all others for whom no marriage partner exists reaches two million four hundred thousand those who forbid plurality of wives should be asked what arrangement they have made for these women and what law they have set down for them for a law must accord with nature either they claim that these women feel none of what other women feel or they permit them fornication the children of the bathhouses in those kingdoms run into the thousands every year and by such vile acts the homes of men afflicted with immorality toward those not their wives have been ruined yet for all this want of sight the opponents censure islam and say that the quran gives license to the riding of appetites by permitting plurality of wives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 32, NULL, 'Had they looked at the noble verse with any fairness — the very verse they suppose grants Muslims such license — they would have found the matter entirely otherwise. The verse stands at the highest degree of eloquence precisely because it forbids plurality with the very words of licensing. Had it granted outright license for plurality, it would have stopped at His words:', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'had they looked at the noble verse with any fairness the very verse they suppose grants muslims such license they would have found the matter entirely otherwise the verse stands at the highest degree of eloquence precisely because it forbids plurality with the very words of licensing had it granted outright license for plurality it would have stopped at his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 33, NULL, 'An-Nisa: 3﴿فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ مَثْنَى وَثُلَاثَ وَرُبَاعَ﴾"Marry such women as seem good to you, two, three or four."', '', NULL, 'An-Nisa: 3', NULL, NULL, 'sharh al masail 7 why marry at all', 'an nisa 3 فانكحوا ما طاب لكم من النساء مثني وثلاث ورباع marry such women as seem good to you two three or four', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 34, NULL, 'But it closed the opening after this with His words:', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'but it closed the opening after this with his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 35, NULL, 'An-Nisa: 3﴿فَإِنْ خِفْتُمْ أَلَّا تَعْدِلُوا فَوَاحِدَةً﴾"And if you fear you will not deal justly, then one."', '', NULL, 'An-Nisa: 3', NULL, NULL, 'sharh al masail 7 why marry at all', 'an nisa 3 فان خفتم الا تعدلوا فواحده and if you fear you will not deal justly then one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 36, NULL, 'And after that:', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'and after that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 37, NULL, 'An-Nisa: 129﴿وَلَنْ تَسْتَطِيعُوا أَنْ تَعْدِلُوا بَيْنَ النِّسَاءِ وَلَوْ حَرَصْتُمْ فَلَا تَمِيلُوا كُلَّ الْمَيْلِ فَتَذَرُوهَا كَالْمُعَلَّقَةِ وَإِنْ تُصْلِحُوا وَتَتَّقُوا فَإِنَّ اللهَ كَانَ غَفُورًا رَحِيمًا﴾"And you will never be able to deal justly between women, however much you desire it; so do not incline with total inclination, leaving her as one suspended. And if you make amends and fear God, then God is Ever-Forgiving, Most Merciful."', '', NULL, 'An-Nisa: 129', NULL, NULL, 'sharh al masail 7 why marry at all', 'an nisa 129 ولن تستطيعوا ان تعدلوا بين النساء ولو حرصتم فلا تميلوا كل الميل فتذروها كالمعلقه وان تصلحوا وتتقوا فان الله كان غفورا رحيما and you will never be able to deal justly between women however much you desire it so do not incline with total inclination leaving her as one suspended and if you make amends and fear god then god is ever forgiving most merciful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 38, NULL, 'Surat al-Nisa.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'surat al nisa', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 39, NULL, 'Any fair-minded person who examines the meaning and intent of this verse can see at once that the permission it grants is not an approval or encouragement toward plurality — it is a remedy, a treatment. Medicine is properly used only by those who are ill, so that disease may not worsen but be checked by the cure. The license of treatment does not address the healthy; they are not required to burden themselves with it where there is no necessity. A man who marries beyond one without necessity is therefore like a man who takes medicine in a state of health and only wearies himself by it. This is what our master al-Qadi al-Numan, may God sanctify his soul, explains in the Daaim, where he said: the merit of taking many women belongs to one who is able to undertake their maintenance, who has been given such strength and capacity as will suffice them, and who is able to refrain from inclining toward one over another and leaving any of them as one suspended, as God has forbidden. A man who has several wives must observe the right of each one, satisfy them, and act well toward each one of them. If it is possible to house them in one house, there is no harm in that — though it is difficult — otherwise he should follow the example of the Messenger of God (صَلَّع) and house them separately.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'any fair minded person who examines the meaning and intent of this verse can see at once that the permission it grants is not an approval or encouragement toward plurality it is a remedy a treatment medicine is properly used only by those who are ill so that disease may not worsen but be checked by the cure the license of treatment does not address the healthy they are not required to burden themselves with it where there is no necessity a man who marries beyond one without necessity is therefore like a man who takes medicine in a state of health and only wearies himself by it this is what our master al qadi al numan may god sanctify his soul explains in the daaim where he said the merit of taking many women belongs to one who is able to undertake their maintenance who has been given such strength and capacity as will suffice them and who is able to refrain from inclining toward one over another and leaving any of them as one suspended as god has forbidden a man who has several wives must observe the right of each one satisfy them and act well toward each one of them if it is possible to house them in one house there is no harm in that though it is difficult otherwise he should follow the example of the messenger of god صلع and house them separately', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 40, NULL, 'The counsel: a man whose wife has died should not remain alone without a wife after her death, but should marry again and not hesitate in it, for in this lies the good of the people and the community and the increase of affection among them. If either of the two had children, that should be no reason for hesitation. It falls to a man''s kin and companions to look after the widows among the people and give thought to marrying them off, considering what is suitable for each one; for a woman living without the shelter of a husband is a more shameful and more grievous situation than a man living without a wife.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'the counsel a man whose wife has died should not remain alone without a wife after her death but should marry again and not hesitate in it for in this lies the good of the people and the community and the increase of affection among them if either of the two had children that should be no reason for hesitation it falls to a mans kin and companions to look after the widows among the people and give thought to marrying them off considering what is suitable for each one for a woman living without the shelter of a husband is a more shameful and more grievous situation than a man living without a wife', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 41, NULL, 'The Messenger of God (صَلَّع) already had two wives, Aisha and Sawda, when he proposed to a Muslim woman whose husband had died, so that she might be under his care. She replied that she was old, had dependents, and was prone to jealousy, and asked how she could marry again. He (صَلَّع) told her that he was older than she; that if she had dependents, they would live alongside the dependents of the Messenger of God (صَلَّع); and that as for her jealousy, he would supplicate God Almighty to lift it from her. The second marriage proceeded on those terms. When she entered the chamber in the house of the Messenger of God and conversation resumed, she excused herself and said, "I said what I said, O Messenger of God, before the marriage, and there was nothing in it from me except that my state might be known beforehand."', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'the messenger of god صلع already had two wives aisha and sawda when he proposed to a muslim woman whose husband had died so that she might be under his care she replied that she was old had dependents and was prone to jealousy and asked how she could marry again he صلع told her that he was older than she that if she had dependents they would live alongside the dependents of the messenger of god صلع and that as for her jealousy he would supplicate god almighty to lift it from her the second marriage proceeded on those terms when she entered the chamber in the house of the messenger of god and conversation resumed she excused herself and said i said what i said o messenger of god before the marriage and there was nothing in it from me except that my state might be known beforehand', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'why marry at all', '7. Why Marry at All', 42, NULL, 'What has gone before makes plain that the true house is the man and the woman together, and that a house of stone and timber is a house only in a figurative sense. The management of that figurative house''s affairs is in the woman''s hands, since it is bound to her, just as the bringing in of provision from outside is bound to the man. As the woman has no entry into affairs that fall to the man, so the man has no entry into affairs that fall to the woman. It is for him to provide for her according to his capacity, and for her to act within her charge according to her own judgment.', '', NULL, NULL, NULL, NULL, 'sharh al masail 7 why marry at all', 'what has gone before makes plain that the true house is the man and the woman together and that a house of stone and timber is a house only in a figurative sense the management of that figurative houses affairs is in the womans hands since it is bound to her just as the bringing in of provision from outside is bound to the man as the woman has no entry into affairs that fall to the man so the man has no entry into affairs that fall to the woman it is for him to provide for her according to his capacity and for her to act within her charge according to her own judgment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 0, NULL, 'Within that division of charge stands the truth that the real home is not the building. The rented house and its furnishings are neither the purpose nor the aim. The real home is the man and the woman together — they are the two who answer for it. The affairs of the household are many and are not exhausted by walls and provisions. Bringing resources in from outside belongs to the man, and such matters do not enter the woman''s domain except where they touch her charge; in the same way, there are affairs belonging to the woman that the man must leave to her, and he provides for her according to his means.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'within that division of charge stands the truth that the real home is not the building the rented house and its furnishings are neither the purpose nor the aim the real home is the man and the woman together they are the two who answer for it the affairs of the household are many and are not exhausted by walls and provisions bringing resources in from outside belongs to the man and such matters do not enter the womans domain except where they touch her charge in the same way there are affairs belonging to the woman that the man must leave to her and he provides for her according to his means', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 1, NULL, 'What is needed between them is affection, and where love is strong, the mark of two sensible people is that they consult one another in the matters each holds in charge. The household becomes a garden for them, and they are its dwellers — addressed by the words of God Almighty:', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'what is needed between them is affection and where love is strong the mark of two sensible people is that they consult one another in the matters each holds in charge the household becomes a garden for them and they are its dwellers addressed by the words of god almighty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 2, NULL, 'Al-Baqarah: 35يا آدم اسكن أنت وزوجك الجنة وكلا منها رغدًا حيث شئتما ولا تقربا هذه الشجرة فتكونا من الظالمين"O Adam, dwell you and your wife in the Garden, and eat from it freely wherever you wish, and do not approach this tree, lest you become of the wrongdoers."', '', NULL, 'Al-Baqarah: 35', NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'al baqarah 35يا ادم اسكن انت وزوجك الجنه وكلا منها رغدا حيث شيتما ولا تقربا هذه الشجره فتكونا من الظالمين o adam dwell you and your wife in the garden and eat from it freely wherever you wish and do not approach this tree lest you become of the wrongdoers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 3, NULL, 'The tree stands for the affairs belonging to each: that neither draw near to what belongs to the other, lest each become a wrongdoer against the other.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'the tree stands for the affairs belonging to each that neither draw near to what belongs to the other lest each become a wrongdoer against the other', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 4, NULL, 'Since the true home is the two spouses, whoever marries off his children must look to both of them. If they prove sensible in managing the household''s means, he keeps them with him. If they are sensible in what benefits them and each stands firm in the duty binding upon him, he provides them a dwelling separate from his own, so that they may live by their own soundness. If both are weak and their parents are left to bear the burden, those parents must not withdraw from their children''s affairs. But two sensible parents, experienced in the ways of this world, do not thrust themselves into the affairs of their children — for their children now constitute a real home of their own, and the parents are among those attached to it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'since the true home is the two spouses whoever marries off his children must look to both of them if they prove sensible in managing the households means he keeps them with him if they are sensible in what benefits them and each stands firm in the duty binding upon him he provides them a dwelling separate from his own so that they may live by their own soundness if both are weak and their parents are left to bear the burden those parents must not withdraw from their childrens affairs but two sensible parents experienced in the ways of this world do not thrust themselves into the affairs of their children for their children now constitute a real home of their own and the parents are among those attached to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 5, NULL, 'Concerning the choice itself, God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'concerning the choice itself god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 6, NULL, 'An-Nur: 26ٱلْخَبِيثَتُ لِلْخَبِيثِينَ وَٱلْخَبِيثُونَ لِلْخَبِيثَتِ وَٱلطَّيِّبَتُ لِلطَّيِّبِينَ وَٱلطَّيِّبُونَ لِلطَّيِّبَتِ"Corrupt women are for corrupt men, and corrupt men for corrupt women; and good women are for good men, and good men for good women."', '', NULL, 'An-Nur: 26', NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'an nur 26الخبيثت للخبيثين والخبيثون للخبيثت والطيبت للطيبين والطيبون للطيبت corrupt women are for corrupt men and corrupt men for corrupt women and good women are for good men and good men for good women', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 7, NULL, 'And there are the sayings:', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'and there are the sayings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 8, NULL, '"Marry those who are equal to you, and marry among them, and choose well for your seed." "Beware of a marriage of ruin, for it is a marred creation." "Marry a woman who is dark and fertile rather than one fair and beautiful and barren, for I shall vie with the other nations through your numbers on the Day of Resurrection." "Take hold of the one who has religion." "Do not marry a woman for her wealth and her beauty, for her wealth and her beauty may be her ruin." "Among the happiness of the Muslim man is a righteous wife, a spacious dwelling, an easy mount, and a righteous child." "The best of your women is the chaste one." "Beware of marrying the foolish woman, for love of her is an affliction and her children are a loss." "Marry the fair-eyed, for in them there is blessing." "The virgin woman is sweeter of speech, quicker to learn, and firmer in affection and steadier in hope."', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'marry those who are equal to you and marry among them and choose well for your seed beware of a marriage of ruin for it is a marred creation marry a woman who is dark and fertile rather than one fair and beautiful and barren for i shall vie with the other nations through your numbers on the day of resurrection take hold of the one who has religion do not marry a woman for her wealth and her beauty for her wealth and her beauty may be her ruin among the happiness of the muslim man is a righteous wife a spacious dwelling an easy mount and a righteous child the best of your women is the chaste one beware of marrying the foolish woman for love of her is an affliction and her children are a loss marry the fair eyed for in them there is blessing the virgin woman is sweeter of speech quicker to learn and firmer in affection and steadier in hope', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 9, NULL, 'Our master the Judge al-Numan, may God cover him with mercy, said that the saying of the Messenger of God — "choose well for your seed" — is a comprehensive word. Its meaning is that a believing man should marry only into a house of purity, should marry one born of lawful lineage, and should keep away from people of debauchery and doubt. The wife is a necklace upon her husband, and it is fitting that he choose that necklace well. Women, though they resemble one another in body and limb, differ greatly when their inward natures are examined and their characters compared. The distance between them in morals, temperament, good compliance, pride, refractoriness, and other qualities besides is far. As the poet said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'our master the judge al numan may god cover him with mercy said that the saying of the messenger of god choose well for your seed is a comprehensive word its meaning is that a believing man should marry only into a house of purity should marry one born of lawful lineage and should keep away from people of debauchery and doubt the wife is a necklace upon her husband and it is fitting that he choose that necklace well women though they resemble one another in body and limb differ greatly when their inward natures are examined and their characters compared the distance between them in morals temperament good compliance pride refractoriness and other qualities besides is far as the poet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 10, NULL, 'Sayingلَيْسَ النِّسَاءُ سَوَاءً إِنَّ الْأَصَابِعَ لَيْسَتْ بِمُسْتَوِيَاتٍ"Women are not all alike, for even the fingers are not of one measure."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'sayingليس النساء سواء ان الاصابع ليست بمستويات women are not all alike for even the fingers are not of one measure', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 11, NULL, 'The point singled out and prized in the saying "choose well for your seed" is that the woman be fit to bear children and well mannered, shaped by the finest upbringing. If that is joined to purity and beauty, so much the better. For this reason the Prophet loved for a man the woman who is fertile and affectionate, and said: "Five things are of happiness: a righteous wife, righteous children, choice companions, a man''s provision in his own land, and the rope of Muhammad."', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'the point singled out and prized in the saying choose well for your seed is that the woman be fit to bear children and well mannered shaped by the finest upbringing if that is joined to purity and beauty so much the better for this reason the prophet loved for a man the woman who is fertile and affectionate and said five things are of happiness a righteous wife righteous children choice companions a mans provision in his own land and the rope of muhammad', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 12, NULL, 'Marriage is not merely a legal contract between a man and a woman. Its intent is the continuance of lineage together with affection and good character, each party fulfilling what is owed to the other. With that intent in view, the saying was transmitted: "When one of you wishes to marry a woman, let him ask about her hair as he asks about her face, for the hair is one of the two beauties." Where it is possible to see the woman, a glance should be taken — not with evil intent, but as honest acquaintance. Sight falls first, and hearing follows; and where no such acquaintance exists, no bond and no sincerity arise between the two. Instead, aversion takes the place of sincerity, the house is afflicted with misery in place of happiness, and fire in place of the Garden.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'marriage is not merely a legal contract between a man and a woman its intent is the continuance of lineage together with affection and good character each party fulfilling what is owed to the other with that intent in view the saying was transmitted when one of you wishes to marry a woman let him ask about her hair as he asks about her face for the hair is one of the two beauties where it is possible to see the woman a glance should be taken not with evil intent but as honest acquaintance sight falls first and hearing follows and where no such acquaintance exists no bond and no sincerity arise between the two instead aversion takes the place of sincerity the house is afflicted with misery in place of happiness and fire in place of the garden', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 13, NULL, 'From the same saying — "choose well for your seed" — it follows that a man and a woman should not marry until they have reached the age of discernment, right guidance, and understanding, so that each may choose for himself a partner with whom he can live. That point is reached at roughly eighteen years of age. Marriage at that age brings joy and sincerity between the two, and soundness to their children. Marriage is not good where the one marrying is young. As for the narrations cited among the scholars concerning the marriage of a woman while still young in years, these are particular to the places and times in which such a thing was a necessity — where the order of authority was not firm and people were not secure from one group overpowering another, as happened in the age of ignorance and as is still found in the outlying regions of the Arab lands. There, the wicked, upon hearing of a girl approaching womanhood in a certain household, raid that household and carry her off from her family — as is recorded in the books of those people and in their verses. In such places, marrying off a daughter while she is still young becomes obligatory, and it requires the multiplication of those bound by ties of marriage. Marriage under those conditions is more fitting and more suitable.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'from the same saying choose well for your seed it follows that a man and a woman should not marry until they have reached the age of discernment right guidance and understanding so that each may choose for himself a partner with whom he can live that point is reached at roughly eighteen years of age marriage at that age brings joy and sincerity between the two and soundness to their children marriage is not good where the one marrying is young as for the narrations cited among the scholars concerning the marriage of a woman while still young in years these are particular to the places and times in which such a thing was a necessity where the order of authority was not firm and people were not secure from one group overpowering another as happened in the age of ignorance and as is still found in the outlying regions of the arab lands there the wicked upon hearing of a girl approaching womanhood in a certain household raid that household and carry her off from her family as is recorded in the books of those people and in their verses in such places marrying off a daughter while she is still young becomes obligatory and it requires the multiplication of those bound by ties of marriage marriage under those conditions is more fitting and more suitable', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 14, NULL, 'In settled countries, where affairs are ordered and the government holds firm over its people, there is no fear of children being plundered. Children remain under the guardianship of their households, and there is no fear for the corruption of their morals. In such lands, parents are not required to marry their daughters before maturity and discernment — not until judgment is settled and the young have striven in earning a livelihood, so that they may maintain their spouses without need of others. Early marriage brings no benefit in a land such as India, where by the praise of God the community lives secure, with security for its children.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'in settled countries where affairs are ordered and the government holds firm over its people there is no fear of children being plundered children remain under the guardianship of their households and there is no fear for the corruption of their morals in such lands parents are not required to marry their daughters before maturity and discernment not until judgment is settled and the young have striven in earning a livelihood so that they may maintain their spouses without need of others early marriage brings no benefit in a land such as india where by the praise of god the community lives secure with security for its children', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 15, NULL, 'With that security, the benefits of the community are beyond counting. Wherever joy or grief falls, and wherever the need for mutual help arises, its people rise to aid one another, standing as the limbs of a single body — in the affairs of religion and the affairs of the world alike. Among those benefits is this: when a man wishes to marry one of the women of the community, whether young or grown, her upbringing, her habits, and her rearing are not hidden from him as he chooses, as they would be hidden in a woman brought in from outside. The selection for marriage thus becomes easy. The righteous among the young do not act presumptuously before their parents and the guardians of their religion; rather, they hold one another in regard. By the praise of God, whoever seeks a spouse finds among the daughters of the community women whose upbringing and companions have been among righteous women, so that they are of purity and soundness.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'with that security the benefits of the community are beyond counting wherever joy or grief falls and wherever the need for mutual help arises its people rise to aid one another standing as the limbs of a single body in the affairs of religion and the affairs of the world alike among those benefits is this when a man wishes to marry one of the women of the community whether young or grown her upbringing her habits and her rearing are not hidden from him as he chooses as they would be hidden in a woman brought in from outside the selection for marriage thus becomes easy the righteous among the young do not act presumptuously before their parents and the guardians of their religion rather they hold one another in regard by the praise of god whoever seeks a spouse finds among the daughters of the community women whose upbringing and companions have been among righteous women so that they are of purity and soundness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 16, NULL, 'Necessary teaching should be broadened among them, so that they are versed in the management of the household and fulfill what is owed from them — the rights of husbands and of sisters, and the rights of children in good rearing, in fixing sound beliefs, and in planting correct knowledge in their hearts. This need is greatest for girls before they enter into household charge. Were such teaching common among them all, each one would be fit to order the house, would be the best companion to her husband and a support to him in the affairs of his livelihood, and would be, by her religion, the first school for the children and their first training ground, before the schools outside.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'necessary teaching should be broadened among them so that they are versed in the management of the household and fulfill what is owed from them the rights of husbands and of sisters and the rights of children in good rearing in fixing sound beliefs and in planting correct knowledge in their hearts this need is greatest for girls before they enter into household charge were such teaching common among them all each one would be fit to order the house would be the best companion to her husband and a support to him in the affairs of his livelihood and would be by her religion the first school for the children and their first training ground before the schools outside', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 17, NULL, 'Whoever among the men and women of the community seeks, for himself or for his children, a marriage from outside the community will find — by reason of the great mixing and the keeping of company in the passing affairs of this world — that no long stretch of time passes before the matter turns to discord and mutual hatred. Beyond that, such a person''s standing within the community is lowered as well. This holds especially when a woman of the community marries a common man, and more so when a man marries from among common people. When such couples have children, no rest remains for them. The events of these past twenty years, apart from what occurred before them, stand as sufficient example and lesson for believing men and women. Nor is the saying far from the truth: "Evil does not enter your house of itself unless you open the door to it." The doors have been opened to evil in some of the houses of the brethren. It is the meeting of believing women with strangers from among common people — even strangers of good standing — that has opened the way toward marriage with them.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'whoever among the men and women of the community seeks for himself or for his children a marriage from outside the community will find by reason of the great mixing and the keeping of company in the passing affairs of this world that no long stretch of time passes before the matter turns to discord and mutual hatred beyond that such a persons standing within the community is lowered as well this holds especially when a woman of the community marries a common man and more so when a man marries from among common people when such couples have children no rest remains for them the events of these past twenty years apart from what occurred before them stand as sufficient example and lesson for believing men and women nor is the saying far from the truth evil does not enter your house of itself unless you open the door to it the doors have been opened to evil in some of the houses of the brethren it is the meeting of believing women with strangers from among common people even strangers of good standing that has opened the way toward marriage with them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 18, NULL, 'The keeping of women to the house, and the keeping of the veil, have been among the marks of the believers and among the traits of chastity and modesty — especially while women are unmarried — and stand as a stronger safeguard against what is disliked and shameful. Upon this, the word of God Almighty gives evidence:', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'the keeping of women to the house and the keeping of the veil have been among the marks of the believers and among the traits of chastity and modesty especially while women are unmarried and stand as a stronger safeguard against what is disliked and shameful upon this the word of god almighty gives evidence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 19, NULL, 'Al-Ahzab: 59يا أيها النبي قل لأزواجك وبناتك ونساء المؤمنين يدنين عليهن من جلابيبهن ذلك أدنى أن يعرفن فلا يؤذين"O Prophet, say to your wives and your daughters and the women of the believers that they draw their outer garments close about them. That is more fitting, that they be known and not molested."', '', NULL, 'Al-Ahzab: 59', NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'al ahzab 59يا ايها النبي قل لازواجك وبناتك ونساء المومنين يدنين عليهن من جلابيبهن ذلك ادني ان يعرفن فلا يوذين o prophet say to your wives and your daughters and the women of the believers that they draw their outer garments close about them that is more fitting that they be known and not molested', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 20, NULL, 'Before this verse came, the believing women in the time of the Prophet could not be distinguished from others in the eyes of the common people, and some were harassed with mockery. The command from God was therefore that they draw their outer garments close about them. The believing women of that age, and of every age after it, kept to the veil, and the veil became one of the marks of the people of faith. Through the constancy of its practice, it took its place among the rulings of Islam, recognized as a general ruling established in the Quran.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'before this verse came the believing women in the time of the prophet could not be distinguished from others in the eyes of the common people and some were harassed with mockery the command from god was therefore that they draw their outer garments close about them the believing women of that age and of every age after it kept to the veil and the veil became one of the marks of the people of faith through the constancy of its practice it took its place among the rulings of islam recognized as a general ruling established in the quran', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 21, NULL, 'When the Quran was seen to carry a general ruling for all believing and Muslim women, those who cared nothing for the moral character of the people of faith began searching for grounds to permit the free mixing of women with their friends and associates from among the general people, and leveled objections at the Quran over the veil. Yet the veil is a command of the Law, and one of the things that sets apart Islam and faith and their qualities.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'when the quran was seen to carry a general ruling for all believing and muslim women those who cared nothing for the moral character of the people of faith began searching for grounds to permit the free mixing of women with their friends and associates from among the general people and leveled objections at the quran over the veil yet the veil is a command of the law and one of the things that sets apart islam and faith and their qualities', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 22, NULL, 'It is related of Abu Jafar (ع) that he was asked about a believing woman of sound understanding living in a place where no one shared her religion: may she marry among them? He said: "She may not marry except one whose religion is known." He was also asked about a dissolute woman — whether a man may marry her. He said: "That is not fitting for him. The people of concealment and chastity are his choice."', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'it is related of abu jafar ع that he was asked about a believing woman of sound understanding living in a place where no one shared her religion may she marry among them he said she may not marry except one whose religion is known he was also asked about a dissolute woman whether a man may marry her he said that is not fitting for him the people of concealment and chastity are his choice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 23, NULL, 'It is further related from the Messenger of God that a Muslim should not marry a woman who is not Muslim while a Muslim woman is available to him. If a woman comes to know Islam, and it happens that she was married to a Muslim while she had previously been an associator, the choice belongs to her: if she wishes, she remains with him, and if she wishes, she returns to her family. When the days of her waiting period are complete, she is released from the contract. And if the believer divorces her and wishes to take her back before those days are complete, the right to do so is his.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'it is further related from the messenger of god that a muslim should not marry a woman who is not muslim while a muslim woman is available to him if a woman comes to know islam and it happens that she was married to a muslim while she had previously been an associator the choice belongs to her if she wishes she remains with him and if she wishes she returns to her family when the days of her waiting period are complete she is released from the contract and if the believer divorces her and wishes to take her back before those days are complete the right to do so is his', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 24, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 25, NULL, 'Sayingحُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُمْ وَأَخَوَاتُكُمْ وَعَمَّاتُكُمْ وَخَالَاتُكُمْ وَبَنَاتُ الْأَخِ وَبَنَاتُ الْأُخْتِ وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ وَأُمَّهَاتُ نِسَائِكُمْ وَرَبَائِبُكُمُ اللَّاتِي فِي حُجُورِكُمْ مِنْ نِسَائِكُمُ اللَّاتِي دَخَلْتُمْ بِهِنَّ فَإِنْ لَمْ تَكُونُوا دَخَلْتُمْ بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلَابِكُمْ وَأَنْ تَجْمَعُوا بَيْنَ الْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا وَالْمُحْصَنَاتُ مِنَ النِّسَاءِ إِلَّا مَا مَلَكَتْ أَيْمَانُكُمْ كِتَابَ اللَّهِ عَلَيْكُمْ وَأُحِلَّ لَكُمْ مَا وَرَاءَ ذَلِكُمْ', '', 'حُرِّمَتْ عَلَيْكُمْ أُمَّهَاتُكُمْ وَبَنَاتُكُمْ وَأَخَوَاتُكُمْ وَعَمَّاتُكُمْ وَخَالَاتُكُمْ وَبَنَاتُ الْأَخِ وَبَنَاتُ الْأُخْتِ وَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ وَأُمَّهَاتُ نِسَائِكُمْ وَرَبَائِبُكُمُ اللَّاتِي فِي حُجُورِكُمْ مِنْ نِسَائِكُمُ اللَّاتِي دَخَلْتُمْ بِهِنَّ فَإِنْ لَمْ تَكُونُوا دَخَلْتُمْ بِهِنَّ فَلَا جُنَاحَ عَلَيْكُمْ وَحَلَائِلُ أَبْنَائِكُمُ الَّذِينَ مِنْ أَصْلَابِكُمْ وَأَنْ تَجْمَعُوا بَيْنَ الْأُخْتَيْنِ إِلَّا مَا قَدْ سَلَفَ إِنَّ اللَّهَ كَانَ غَفُورًا رَحِيمًا وَالْمُحْصَنَاتُ مِنَ النِّسَاءِ إِلَّا مَا مَلَكَتْ أَيْمَانُكُمْ كِتَابَ اللَّهِ عَلَيْكُمْ وَأُحِلَّ لَكُمْ مَا وَرَاءَ ذَلِكُمْ', 'Saying', NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'sayingحرمت عليكم امهاتكم وبناتكم واخواتكم وعماتكم وخالاتكم وبنات الاخ وبنات الاخت وامهاتكم اللاتي ارضعنكم واخواتكم من الرضاعه وامهات نسايكم وربايبكم اللاتي في حجوركم من نسايكم اللاتي دخلتم بهن فان لم تكونوا دخلتم بهن فلا جناح عليكم وحلايل ابنايكم الذين من اصلابكم وان تجمعوا بين الاختين الا ما قد سلف ان الله كان غفورا رحيما والمحصنات من النساء الا ما ملكت ايمانكم كتاب الله عليكم واحل لكم ما وراء ذلكم', 'حرمت عليكم امهاتكم وبناتكم واخواتكم وعماتكم وخالاتكم وبنات الاخ وبنات الاخت وامهاتكم اللاتي ارضعنكم واخواتكم من الرضاعه وامهات نسايكم وربايبكم اللاتي في حجوركم من نسايكم اللاتي دخلتم بهن فان لم تكونوا دخلتم بهن فلا جناح عليكم وحلايل ابنايكم الذين من اصلابكم وان تجمعوا بين الاختين الا ما قد سلف ان الله كان غفورا رحيما والمحصنات من النساء الا ما ملكت ايمانكم كتاب الله عليكم واحل لكم ما وراء ذلكم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 26, NULL, 'A question: if a man marries a woman in ignorance of the prohibition against joining two sisters — not knowing that this second woman he has married is the sister of his existing wife — and he then comes to know, separation between them is obligatory without the form of divorce. If he has consummated the marriage, the dowry is owed by him and the waiting period is owed by her; if he has not consummated it, nothing is owed by him. There is no objection to joining a maternal aunt''s daughter with a paternal aunt''s daughter in marriage, nor to joining the wife of a paternal uncle with his daughter by another woman, nor to marrying a daughter born of other than one''s own parents. A man may not marry the sister of his wife when the wife''s divorce is still revocable; but if the divorce was irrevocable, there is no objection to the marriage.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'a question if a man marries a woman in ignorance of the prohibition against joining two sisters not knowing that this second woman he has married is the sister of his existing wife and he then comes to know separation between them is obligatory without the form of divorce if he has consummated the marriage the dowry is owed by him and the waiting period is owed by her if he has not consummated it nothing is owed by him there is no objection to joining a maternal aunts daughter with a paternal aunts daughter in marriage nor to joining the wife of a paternal uncle with his daughter by another woman nor to marrying a daughter born of other than ones own parents a man may not marry the sister of his wife when the wifes divorce is still revocable but if the divorce was irrevocable there is no objection to the marriage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 27, NULL, 'A question: four women are forbidden forever.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'a question four women are forbidden forever', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 28, NULL, 'The woman divorced by a divorce that ends the marriage completely. The woman a man marries after knowing her prohibition. The woman a man marries during her waiting period following the death of her husband. The woman he marries while he is in the state of consecration.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'the woman divorced by a divorce that ends the marriage completely the woman a man marries after knowing her prohibition the woman a man marries during her waiting period following the death of her husband the woman he marries while he is in the state of consecration', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 29, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 30, NULL, 'Al-Baqarah: 235وَلَا جُنَاحَ عَلَيْكُمْ فِيمَا عَرَّضْتُم بِهِۦ مِنْ خِطْبَةِ ٱلنِّسَآءِ أَوْ أَكْنَنتُمْ فِىٓ أَنفُسِكُمْ عَلِمَ ٱللَّهُ أَنَّكُمْ سَتَذْكُرُونَهُنَّ"And there is no blame upon you in what you hint at of a proposal to women, or conceal within yourselves. God knows that you will be mindful of them."', '', NULL, 'Al-Baqarah: 235', NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'al baqarah 235ولا جناح عليكم فيما عرضتم به من خطبه النساء او اكننتم في انفسكم علم الله انكم ستذكرونهن and there is no blame upon you in what you hint at of a proposal to women or conceal within yourselves god knows that you will be mindful of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 31, NULL, 'It is related that the Messenger of God forbade a man from proposing over the proposal of his brother — meaning after mutual agreement between the two parties has been reached.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'it is related that the messenger of god forbade a man from proposing over the proposal of his brother meaning after mutual agreement between the two parties has been reached', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 32, NULL, 'A woman''s standing in relation to men is of two kinds: married and unmarried. If she is married, her situation falls under one of three cases: she is under a husband; she is in the waiting period of a divorce, whether irrevocable or revocable; or she is in the waiting period of a woman whose husband has died. If a woman is under a husband, or in the waiting period of a revocable divorce, no one may propose to her openly or hint at it. But if she is in the waiting period of an irrevocable divorce, or in the waiting period of a woman whose husband has died, there is no objection to speech by which she may come to know the man''s intent, though a proposal in the manner of open declaration remains impermissible. As for the unmarried woman, if she is not among the forbidden, proposing to her is permissible, and one man''s proposal does not bar another''s until she gives her answer. That answer must be an express acceptance; weeping or silence does not constitute evidence of consent.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'a womans standing in relation to men is of two kinds married and unmarried if she is married her situation falls under one of three cases she is under a husband she is in the waiting period of a divorce whether irrevocable or revocable or she is in the waiting period of a woman whose husband has died if a woman is under a husband or in the waiting period of a revocable divorce no one may propose to her openly or hint at it but if she is in the waiting period of an irrevocable divorce or in the waiting period of a woman whose husband has died there is no objection to speech by which she may come to know the mans intent though a proposal in the manner of open declaration remains impermissible as for the unmarried woman if she is not among the forbidden proposing to her is permissible and one mans proposal does not bar anothers until she gives her answer that answer must be an express acceptance weeping or silence does not constitute evidence of consent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 33, NULL, 'Jafar al-Sadiq (ع) said concerning the meaning of hinting: "It is not fitting for a man to propose to a woman in her waiting period; but the hinting that God has permitted is that he speak words by which the woman may come to know his intent."', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'jafar al sadiq ع said concerning the meaning of hinting it is not fitting for a man to propose to a woman in her waiting period but the hinting that god has permitted is that he speak words by which the woman may come to know his intent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 34, NULL, 'Abu Jafar Muhammad ibn Ali (ع) entered upon Sakina bint Hanzala, whose husband — her cousin, who had married her — had died. He greeted her and said: "How are you, daughter of Hanzala?" She said: "Well, may I be made your ransom." He then said: "You have known my kinship to the Messenger of God, and my kinship to Ali (ع), and my standing in Islam, and my house among the Arabs." She said: "May God set you right, Abu Jafar. Do you propose to me in my waiting period?" He said: "I did not do so. I only informed you of my kinship and my station. The Messenger of God entered upon Umm Salama, daughter of Abu Umayya ibn al-Mughira, when she had been widowed of Abu Salama — who was her cousin — and he did not cease to mention to her his station and his place with God until the mark of the mat appeared in his palm from the force of his leaning upon his hand. And that was not a proposal."', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'abu jafar muhammad ibn ali ع entered upon sakina bint hanzala whose husband her cousin who had married her had died he greeted her and said how are you daughter of hanzala she said well may i be made your ransom he then said you have known my kinship to the messenger of god and my kinship to ali ع and my standing in islam and my house among the arabs she said may god set you right abu jafar do you propose to me in my waiting period he said i did not do so i only informed you of my kinship and my station the messenger of god entered upon umm salama daughter of abu umayya ibn al mughira when she had been widowed of abu salama who was her cousin and he did not cease to mention to her his station and his place with god until the mark of the mat appeared in his palm from the force of his leaning upon his hand and that was not a proposal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 35, NULL, 'It is related from the Messenger of God that he said: "When one of you wishes to marry, there is no objection to his stealing a glance at the woman he intends to marry, if he finds the means." God commanded believing men to lower their gaze from believing women, and believing women likewise to lower their gaze from believing men. It is related from Ali that he said the Messenger of God was asked about a man past whom a woman passes and who looks at her, and he said: "The first glance is for you, the second is against you, and the third glance is an arrow from the arrows of Iblis. Whoever leaves it for the sake of God, God will requite him with a faith whose sweetness he finds in his heart." Jafar ibn Muhammad was asked about a man past whom a woman passes and who looks after her, and he said: "Would he love that men should look at his own household? Accept for people what you accept for yourselves."', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'it is related from the messenger of god that he said when one of you wishes to marry there is no objection to his stealing a glance at the woman he intends to marry if he finds the means god commanded believing men to lower their gaze from believing women and believing women likewise to lower their gaze from believing men it is related from ali that he said the messenger of god was asked about a man past whom a woman passes and who looks at her and he said the first glance is for you the second is against you and the third glance is an arrow from the arrows of iblis whoever leaves it for the sake of god god will requite him with a faith whose sweetness he finds in his heart jafar ibn muhammad was asked about a man past whom a woman passes and who looks after her and he said would he love that men should look at his own household accept for people what you accept for yourselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 36, NULL, 'These narrations, in which the permissibility of a woman''s going out to the market is mentioned, belong to places where there is a single people or a single tribe of the people of faith, as is the case now in some of the outlying parts of the Arab lands, where women remain among their own quarters. A woman who has no one to undertake her affairs has no remedy but to go out, and there is no objection to it. But in those places where many kinds of people live together — the noble and the base among them — it is not for the women of noble houses and the people of religion to go out from the house, even veiled, for that is counted a fault among the people of religion.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'these narrations in which the permissibility of a womans going out to the market is mentioned belong to places where there is a single people or a single tribe of the people of faith as is the case now in some of the outlying parts of the arab lands where women remain among their own quarters a woman who has no one to undertake her affairs has no remedy but to go out and there is no objection to it but in those places where many kinds of people live together the noble and the base among them it is not for the women of noble houses and the people of religion to go out from the house even veiled for that is counted a fault among the people of religion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 37, NULL, 'It is related that a man came to the Messenger of God and said: "O Messenger of God, shall I ask permission of my sister when I wish to enter upon her?" He said: "Yes. Would it please you to see her uncovered?" The man said: "No." He said: "And my sister, O Messenger of God, uncovers her hair at times before me." He said: "No." The man said: "And why?" He said: "I fear for you that if something of her beauty appears to you, Satan may take hold of you." And he said: "When one of you kisses a woman of his close kin who has reached the age of menses, let him kiss between her eyes or upon her head, and let him refrain from her cheek and from her mouth."', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'it is related that a man came to the messenger of god and said o messenger of god shall i ask permission of my sister when i wish to enter upon her he said yes would it please you to see her uncovered the man said no he said and my sister o messenger of god uncovers her hair at times before me he said no the man said and why he said i fear for you that if something of her beauty appears to you satan may take hold of you and he said when one of you kisses a woman of his close kin who has reached the age of menses let him kiss between her eyes or upon her head and let him refrain from her cheek and from her mouth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 38, NULL, 'It is related that he forbade a virgin being given in marriage until she is consulted, and that there is no marriage except with a guardian and two witnesses. Ali said: "The giving in marriage by the father and the grandfather is permitted for sons and daughters when they are small, and they have no option after they reach maturity."', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'it is related that he forbade a virgin being given in marriage until she is consulted and that there is no marriage except with a guardian and two witnesses ali said the giving in marriage by the father and the grandfather is permitted for sons and daughters when they are small and they have no option after they reach maturity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'choosing well, looking rightly', '8. Choosing Well, Looking Rightly', 39, NULL, 'Kinship is of two kinds. What comes by way of the father is called kinship of lineage, and the relatives connected through the father are bound to a man by the tie of blood. The one born into this kinship is not there by his own choice; it is necessary and unchosen. What comes by way of marriage is called kinship of affinity, and the relatives connected through this tie are bound to the man and to the woman by the tie of marriage; the two spouses enter this kinship by their own choice, and so they are praised or blamed for it. Kinship by affinity is the kinship that a man and a woman are able to acquire for themselves.', '', NULL, NULL, NULL, NULL, 'sharh al masail 8 choosing well looking rightly', 'kinship is of two kinds what comes by way of the father is called kinship of lineage and the relatives connected through the father are bound to a man by the tie of blood the one born into this kinship is not there by his own choice it is necessary and unchosen what comes by way of marriage is called kinship of affinity and the relatives connected through this tie are bound to the man and to the woman by the tie of marriage the two spouses enter this kinship by their own choice and so they are praised or blamed for it kinship by affinity is the kinship that a man and a woman are able to acquire for themselves', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 0, NULL, 'On Lawful and Unlawful Women in Marriage', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'on lawful and unlawful women in marriage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 1, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 2, NULL, 'Saying"يَا أَيُّهَا النَّبِىُّ اِنَّا اَحْلَلْنَا لَكَ اَزْوَاجَكَ""O Prophet, We have made lawful for you your wives."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'saying يا ايها النبي انا احللنا لك ازواجك o prophet we have made lawful for you your wives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 3, NULL, 'The hadith states that a man was swept away by his passions and married his father''s wife, with two witnesses present. It is transmitted that Salih said: a father and son may lawfully marry slave girls and their daughters if the girls are young; upon reaching puberty, however, the girls have a choice in the matter.', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'the hadith states that a man was swept away by his passions and married his fathers wife with two witnesses present it is transmitted that salih said a father and son may lawfully marry slave girls and their daughters if the girls are young upon reaching puberty however the girls have a choice in the matter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 4, NULL, 'Kinship falls into two categories:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'kinship falls into two categories', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 5, NULL, 'Blood relation (نسبية, nasab (نَسَبِيَّة)): relatives joined by lineage on the father''s side, bound to one another by a shared line of descent. One born into this kinship is bound on both sides by ties of blood. Affinity by marriage (صِهَارِيَّة, musahara (صِهَارِيَّة)): where there is no blood connection, the relationship is formed through the marriage bond. Those in this category are not strangers to marriage.', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'blood relation نسبيه nasab نسبيه relatives joined by lineage on the fathers side bound to one another by a shared line of descent one born into this kinship is bound on both sides by ties of blood affinity by marriage صهاريه musahara صهاريه where there is no blood connection the relationship is formed through the marriage bond those in this category are not strangers to marriage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 6, NULL, 'The relationship of musahara, like blood kinship, carries its own rulings regarding choice and permissibility.', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'the relationship of musahara like blood kinship carries its own rulings regarding choice and permissibility', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 7, NULL, 'When those under guardianship reach adulthood and come into the fullness of their years, the authority of the guardian may appear coercive. Yet both forms of guardianship remain in force until the ward reaches puberty. The furthest point from puberty is the age of musahara, and the age of maturity differs among individuals. Guardianship in marriage belongs to no one other than the father — where one can be found — or his duly appointed agent.', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'when those under guardianship reach adulthood and come into the fullness of their years the authority of the guardian may appear coercive yet both forms of guardianship remain in force until the ward reaches puberty the furthest point from puberty is the age of musahara and the age of maturity differs among individuals guardianship in marriage belongs to no one other than the father where one can be found or his duly appointed agent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 8, NULL, 'Saying"فَاِنْ اَنْكَحَهَا غَيْرُ هَؤُلَاءِ الْاَرْبَعَةِ فَالنِّكَاحُ بَاطِلٌ""If she is given in marriage by other than these four, the marriage is void."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'saying فان انكحها غير هولاء الاربعه فالنكاح باطل if she is given in marriage by other than these four the marriage is void', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 9, NULL, 'It is equally impermissible for these guardians to act on verbal consent alone. If an adult woman wishes to arrange her own marriage, she may appoint as her agent one of these four, or a genuine son, or a reliable relative, or her paternal brother, to act in the matter, with two witnesses present. One of the guardians may also delegate authority to another living guardian, allowing the one chosen to be appointed by the judge to act on her behalf. The matter should not be left unresolved, and no one else should be permitted to interfere. If the guardian refuses without valid cause, the judge steps in and the appointed agent conducts the marriage on her behalf. This is the path narrated from the Imams of guidance (عَلَيْهِمُ السَّلَامُ). The judge, moreover, may serve as a witness to the contract of two men, and there is no objection if those who witnessed the agency also serve as witnesses to the marriage itself.', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'it is equally impermissible for these guardians to act on verbal consent alone if an adult woman wishes to arrange her own marriage she may appoint as her agent one of these four or a genuine son or a reliable relative or her paternal brother to act in the matter with two witnesses present one of the guardians may also delegate authority to another living guardian allowing the one chosen to be appointed by the judge to act on her behalf the matter should not be left unresolved and no one else should be permitted to interfere if the guardian refuses without valid cause the judge steps in and the appointed agent conducts the marriage on her behalf this is the path narrated from the imams of guidance عليهم السلام the judge moreover may serve as a witness to the contract of two men and there is no objection if those who witnessed the agency also serve as witnesses to the marriage itself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 10, NULL, 'On Conditions Stipulated in the Marriage Contract', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'on conditions stipulated in the marriage contract', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 11, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 12, NULL, 'Saying"وَلَا تَقُولُوا لِمَا تَصِفُ اَلْسِنَتُكُمُ الْكَذِبَ هَذَا حَلَالٌ وَهَذَا حَرَامٌ لِتَفْتَرُوا عَلَى اللهِ الْكَذِبَ""Do not say what your tongues describe, that this is lawful and this is forbidden, inventing lies against God."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'saying ولا تقولوا لما تصف السنتكم الكذب هذا حلال وهذا حرام لتفتروا علي الله الكذب do not say what your tongues describe that this is lawful and this is forbidden inventing lies against god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 13, NULL, 'Mawlana Jafar al-Sadiq (ع) said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'mawlana jafar al sadiq ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 14, NULL, 'Saying"شَرْطُ اللهِ قَبْلَ شُرُوطِهِمْ""The condition of God comes before their conditions."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'saying شرط الله قبل شروطهم the condition of god comes before their conditions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 15, NULL, 'That is, any condition the parties stipulate is neither valid nor enforceable if it violates the Book or contradicts the Sunnah.', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'that is any condition the parties stipulate is neither valid nor enforceable if it violates the book or contradicts the sunnah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 16, NULL, 'God has granted the husband authority in certain matters: intercourse, divorce, maintenance given in kindness, and the contracting of further marriages. Where time is to be divided among several wives, each receives her due share. The husband is obliged to fulfill the rights of each wife, whether she accepts the arrangement or not, and all of this must be conducted with fairness and kindness. If either party is wronged, the wife may bring the matter before the judge — though the judge does not have the power to impose divorce through payment (الْخُلْعِ) or to remove the husband from the home. The husband must not strike his wife over anything that is not legally obligatory. God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'god has granted the husband authority in certain matters intercourse divorce maintenance given in kindness and the contracting of further marriages where time is to be divided among several wives each receives her due share the husband is obliged to fulfill the rights of each wife whether she accepts the arrangement or not and all of this must be conducted with fairness and kindness if either party is wronged the wife may bring the matter before the judge though the judge does not have the power to impose divorce through payment الخلع or to remove the husband from the home the husband must not strike his wife over anything that is not legally obligatory god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 17, NULL, 'Sayingوَاللَّاتِى تَخَافُونَ نُشُوزَهُنَّ فَعِظُوهُنَّ وَاهْجُرُوهُنَّ فِى الْمَضَاجِعِ وَاضْرِبُوهُنَّ فَاِنْ اَطَعْنَكُمْ فَلَا تَبْغُوا عَلَيْهِنَّ سَبِيلًا"As for those women from whom you fear nushuz (نُشُوز), admonish them, then forsake them in bed, and then strike them; but if they obey you, seek no further means against them."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'sayingواللاتي تخافون نشوزهن فعظوهن واهجروهن في المضاجع واضربوهن فان اطعنكم فلا تبغوا عليهن سبيلا as for those women from whom you fear nushuz نشوز admonish them then forsake them in bed and then strike them but if they obey you seek no further means against them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 18, NULL, 'Maintenance, necessary provision, and divorce each have their proper place. A Muslim man holds certain prerogatives, except when he acts in a state of intoxication or moral filth. In the case of الْخُلْعِ divorce, the couple must be given a choice. The matter is brought before the arbitrator, or a dispute arises — as has occurred in various cases over the years. Whoever wished to proceed with the marriage would do so, with proper documentation recorded in a designated register. A man must deal equitably with his wife in matters of good treatment, fulfilling the right of rajah, providing maintenance, and observing the waiting period (مُحْسِبُ الزَّمَانِ). If none of these conditions are met and a directive is issued — one that falls on the side of the woman — then the man''s right concerning the couple, should he wish to reconcile them when the number exceeds thirteen, is that her divorce rests in the hand of the one who has assumed authority, so as to bring about reconciliation or to finalize the divorce. Both outcomes are subject to moderation.', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'maintenance necessary provision and divorce each have their proper place a muslim man holds certain prerogatives except when he acts in a state of intoxication or moral filth in the case of الخلع divorce the couple must be given a choice the matter is brought before the arbitrator or a dispute arises as has occurred in various cases over the years whoever wished to proceed with the marriage would do so with proper documentation recorded in a designated register a man must deal equitably with his wife in matters of good treatment fulfilling the right of rajah providing maintenance and observing the waiting period محسب الزمان if none of these conditions are met and a directive is issued one that falls on the side of the woman then the mans right concerning the couple should he wish to reconcile them when the number exceeds thirteen is that her divorce rests in the hand of the one who has assumed authority so as to bring about reconciliation or to finalize the divorce both outcomes are subject to moderation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 19, NULL, 'If the man wishes to divorce his wife but she objects, she may ransom herself by returning her portion of the division to him, or some part of it, and they may agree on a settlement. Reconciliation through mutual agreement is permissible, as God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'if the man wishes to divorce his wife but she objects she may ransom herself by returning her portion of the division to him or some part of it and they may agree on a settlement reconciliation through mutual agreement is permissible as god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 20, NULL, 'Sayingاِنِ امْرَاَةٌ خَافَتْ نُشُوزًا اَوْ اِعْرَاضًا فَلَا جُنَاحَ عَلَيْهِمَا اَنْ يُصْلِحَا بَيْنَهُمَا صُلْحًا وَالصُّلْحُ خَيْرٌ"If a woman fears ill-treatment or desertion from her husband, there is no blame on either of them if they come to a settlement between themselves, and settlement is better."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'sayingان امراه خافت نشوزا او اعراضا فلا جناح عليهما ان يصلحا بينهما صلحا والصلح خير if a woman fears ill treatment or desertion from her husband there is no blame on either of them if they come to a settlement between themselves and settlement is better', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 21, NULL, 'The essential condition is that the two parties reconcile on good terms. Seeking harm through divorce is blameworthy except where separation is necessary to complete the matter. It is likewise established that a man may divorce his wife in order to marry another. As for defects that neither husband nor wife knew of before the marriage but that came to light afterward, each party has the right either to remain in the marriage or to separate. These defects are nine, and they are enumerated in the Daaim.', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'the essential condition is that the two parties reconcile on good terms seeking harm through divorce is blameworthy except where separation is necessary to complete the matter it is likewise established that a man may divorce his wife in order to marry another as for defects that neither husband nor wife knew of before the marriage but that came to light afterward each party has the right either to remain in the marriage or to separate these defects are nine and they are enumerated in the daaim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 22, NULL, 'On the Bride-Price', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'on the bride price', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 23, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 24, NULL, 'An-Nisa: 4وَآتُوا النِّسَاءَ صَدُقَاتِهِنَّ نِحْلَةً"And give the women their bride-gifts as a free gift."', '', NULL, 'An-Nisa: 4', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'an nisa 4واتوا النساء صدقاتهن نحله and give the women their bride gifts as a free gift', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 25, NULL, 'And the hadith:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'and the hadith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 26, NULL, 'Sayingاِنَّ اللهَ غَافِرٌ كُلَّ ذَنْبٍ اِلَّا رَجُلًا اغْتَصَبَ امْرَاَةً مَهْرَهَا اَوْ اَجِيرًا اَجْرَتَهُ اَوْ رَجُلًا بَاعَ حُرًّا"God forgives every sin except that of a man who seizes a woman''s bride-price, or a hired man''s wage, or a man who sells a free person."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'sayingان الله غافر كل ذنب الا رجلا اغتصب امراه مهرها او اجيرا اجرته او رجلا باع حرا god forgives every sin except that of a man who seizes a womans bride price or a hired mans wage or a man who sells a free person', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 27, NULL, 'A man whose bride-price had been provided by his people came forward. The Messenger of God (صَلَّع) said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'a man whose bride price had been provided by his people came forward the messenger of god صلع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 28, NULL, 'Saying"لَا تُغَالُوا فِى مُهُورِ النِّسَاءِ فَتَكُونَ عَدَاوَةٌ""Do not exaggerate in the matter of the bride-prices of women, lest enmity result."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'saying لا تغالوا في مهور النساء فتكون عداوه do not exaggerate in the matter of the bride prices of women lest enmity result', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 29, NULL, 'It is also narrated that a man came to the Messenger of God (صَلَّع) and said: "O Messenger of God, I wish to marry this woman." The Prophet asked what he would give her as her bride-gift. The man said: "I have nothing." The Prophet saw a ring on the man''s hand and asked:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'it is also narrated that a man came to the messenger of god صلع and said o messenger of god i wish to marry this woman the prophet asked what he would give her as her bride gift the man said i have nothing the prophet saw a ring on the mans hand and asked', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 30, NULL, 'Saying"اَهَذَا الْخَاتَمُ لَكَ""Is this ring yours?"', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'saying اهذا الخاتم لك is this ring yours', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 31, NULL, 'The man replied: "Yes." The Prophet said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'the man replied yes the prophet said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 32, NULL, 'Saying"فَتَزَوَّجْهَا عَلَيْهِ""Then marry her upon it."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'saying فتزوجها عليه then marry her upon it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 33, NULL, 'A marriage should not be contracted without a اَلْمَهْر. The Prophet (صَلَّع) did not set for any of his wives more than twelve and a half uqiyyas — the equivalent of roughly forty rupees — and upon that he married Fatima (رض). The Daaim states that there is no fixed limit upon the اَلْمَهْر; this was simply the اَلْمَهْر the Messenger of God (صَلَّع) set for his wives, as though he loved equality among them in the matter. The brotherhood settled upon forty rupees as the اَلْمَهْر, so that equality might obtain between the wealthy among the people and the poor among them. What has come from the Commander of the Faithful is that consummation is not to take place without a اَلْمَهْر — consummation being what is meant by entering upon her — for the اَلْمَهْر is not among the conditions of the contract itself. It is permissible to contract a marriage without naming the اَلْمَهْر and without paying it in advance, though it is fitting that the customary observances of the اَلْمَهْر precede the marriage, named and specified.', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'a marriage should not be contracted without a المهر the prophet صلع did not set for any of his wives more than twelve and a half uqiyyas the equivalent of roughly forty rupees and upon that he married fatima رض the daaim states that there is no fixed limit upon the المهر this was simply the المهر the messenger of god صلع set for his wives as though he loved equality among them in the matter the brotherhood settled upon forty rupees as the المهر so that equality might obtain between the wealthy among the people and the poor among them what has come from the commander of the faithful is that consummation is not to take place without a المهر consummation being what is meant by entering upon her for the المهر is not among the conditions of the contract itself it is permissible to contract a marriage without naming the المهر and without paying it in advance though it is fitting that the customary observances of the المهر precede the marriage named and specified', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 34, NULL, 'Sayingوَمَنْ فَوَّضَ اَمْرَ الْمَهْرِ اِلَى الزَّوْجَةِ قَبْلَ الْعَقْدِ فَكَذَلِكَ بَعْدَ الدُّخُولِ لِاَنَّهُ قَدْ وَجَبَ الْاَدَاءُ عَلَيْهِ بَعْدَ الدُّخُولِ"Whoever delegates the matter of the bride-price to the wife before the contract, it is likewise after consummation, for payment has become obligatory upon him after consummation."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'sayingومن فوض امر المهر الي الزوجه قبل العقد فكذلك بعد الدخول لانه قد وجب الاداء عليه بعد الدخول whoever delegates the matter of the bride price to the wife before the contract it is likewise after consummation for payment has become obligatory upon him after consummation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 35, NULL, 'The husband does not simply determine the amount himself. Rather, the judge considers the woman''s standing among her peers — her circumstances and her wealth — and calculates accordingly. If her station is elevated, a comparable اَلْمَهْر is set for her, equal to the اَلْمَهْر of the wives of the Prophet, which is forty rupees. If her station is lower, he gives her less, in proportion to it. If the setting of the اَلْمَهْر has been assigned to the husband, she may accept whatever he gives. As for a husband of limited means, he should give her something before he enters upon her — a dirham, or whatever he is able. The اَلْمَهْر is the wife''s right alone; neither her parents, nor her guardian, nor her agent, nor anyone else has any share in it, unless she herself chooses to make a gift of it to one of them, which is entirely within her power. Likewise, everything that comes to her as gifts at the time of the marriage — whether from the husband or from the relatives — is hers and belongs to her by right, unless it is made plain that a given item was lent for her use only, in which case she must return that item and nothing more.', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'the husband does not simply determine the amount himself rather the judge considers the womans standing among her peers her circumstances and her wealth and calculates accordingly if her station is elevated a comparable المهر is set for her equal to the المهر of the wives of the prophet which is forty rupees if her station is lower he gives her less in proportion to it if the setting of the المهر has been assigned to the husband she may accept whatever he gives as for a husband of limited means he should give her something before he enters upon her a dirham or whatever he is able the المهر is the wifes right alone neither her parents nor her guardian nor her agent nor anyone else has any share in it unless she herself chooses to make a gift of it to one of them which is entirely within her power likewise everything that comes to her as gifts at the time of the marriage whether from the husband or from the relatives is hers and belongs to her by right unless it is made plain that a given item was lent for her use only in which case she must return that item and nothing more', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 36, NULL, 'On Mutual Rights in Marriage', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'on mutual rights in marriage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 37, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 38, NULL, 'An-Nisa: 19وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ"And live with them in kindness."', '', NULL, 'An-Nisa: 19', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'an nisa 19وعاشروهن بالمعروف and live with them in kindness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 39, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 40, NULL, 'Al-Baqarah: 187هُنَّ لِبَاسٌ لَكُمْ وَاَنْتُمْ لِبَاسٌ لَهُنَّ"They are a garment for you and you are a garment for them."', '', NULL, 'Al-Baqarah: 187', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'al baqarah 187هن لباس لكم وانتم لباس لهن they are a garment for you and you are a garment for them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 41, NULL, 'A hadith has also been transmitted from the Messenger of God (صَلَّع) on a matter he continued to press upon the people until his tongue grew weary and his speech faltered. He said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'a hadith has also been transmitted from the messenger of god صلع on a matter he continued to press upon the people until his tongue grew weary and his speech faltered he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 42, NULL, 'Sayingالصَّلَاةَ الصَّلَاةَ وَمَا مَلَكَتْ اَيْمَانُكُمْ لَا تُكَلِّفُوهُمْ مَا لَا يُطِيقُونَ، اللهَ اللهَ فِى النِّسَاءِ فَاِنَّهُنَّ عَوَانٍ فِى اَيْدِيكُمْ اَخَذْتُمُوهُنَّ بِاَمَانَةِ اللهِ وَاسْتَحْلَلْتُمْ فُرُوجَهُنَّ بِكَلِمَةِ اللهِ', '', 'الصَّلَاةَ الصَّلَاةَ وَمَا مَلَكَتْ اَيْمَانُكُمْ لَا تُكَلِّفُوهُمْ مَا لَا يُطِيقُونَ، اللهَ اللهَ فِى النِّسَاءِ فَاِنَّهُنَّ عَوَانٍ فِى اَيْدِيكُمْ اَخَذْتُمُوهُنَّ بِاَمَانَةِ اللهِ وَاسْتَحْلَلْتُمْ فُرُوجَهُنَّ بِكَلِمَةِ اللهِ', 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'sayingالصلاه الصلاه وما ملكت ايمانكم لا تكلفوهم ما لا يطيقون الله الله في النساء فانهن عوان في ايديكم اخذتموهن بامانه الله واستحللتم فروجهن بكلمه الله', 'الصلاه الصلاه وما ملكت ايمانكم لا تكلفوهم ما لا يطيقون الله الله في النساء فانهن عوان في ايديكم اخذتموهن بامانه الله واستحللتم فروجهن بكلمه الله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 43, NULL, 'The original purpose of marriage is the continuation of offspring and mutual assistance in the welfare of this life and the next. God Almighty made this clear in His words:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'the original purpose of marriage is the continuation of offspring and mutual assistance in the welfare of this life and the next god almighty made this clear in his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 44, NULL, 'Saying"وَخَلَقَ لَكُمْ مِنْ اَنْفُسِكُمْ اَزْوَاجًا لِتَسْكُنُوا اِلَيْهَا وَجَعَلَ بَيْنَكُمْ مَوَدَّةً وَرَحْمَةً""And He created for you from yourselves mates that you may find tranquillity in them, and He placed between you affection and mercy."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'saying وخلق لكم من انفسكم ازواجا لتسكنوا اليها وجعل بينكم موده ورحمه and he created for you from yourselves mates that you may find tranquillity in them and he placed between you affection and mercy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 45, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 46, NULL, 'Saying"وَالَّذِينَ يَقُولُونَ رَبَّنَا هَبْ لَنَا مِنْ اَزْوَاجِنَا وَذُرِّيَّاتِنَا قُرَّةَ اَعْيُنٍ وَاجْعَلْنَا لِلْمُتَّقِينَ اِمَامًا""And those who say: Our Lord, grant us from among our spouses and offspring comfort to our eyes, and make us leaders of the God-fearing."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'saying والذين يقولون ربنا هب لنا من ازواجنا وذرياتنا قره اعين واجعلنا للمتقين اماما and those who say our lord grant us from among our spouses and offspring comfort to our eyes and make us leaders of the god fearing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 47, NULL, 'It falls to believers — and to the righteous among God''s servants — to make their married life like a garden beneath which springs flow, delightful to the eye in its meadows and its greenness, each spouse seeking the good of the other. The Quran makes this plain in God''s words:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'it falls to believers and to the righteous among gods servants to make their married life like a garden beneath which springs flow delightful to the eye in its meadows and its greenness each spouse seeking the good of the other the quran makes this plain in gods words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 48, NULL, 'Saying"وَلَهُنَّ مِثْلُ الَّذِى عَلَيْهِنَّ بِالْمَعْرُوفِ""And they have rights similar to those due from them, in kindness."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'saying ولهن مثل الذي عليهن بالمعروف and they have rights similar to those due from them in kindness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 49, NULL, 'And in His words:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'and in his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 50, NULL, 'Saying"وَعَاشِرُوهُنَّ بِالْمَعْرُوفِ""And live with them in kindness."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'saying وعاشروهن بالمعروف and live with them in kindness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 51, NULL, 'And in His words:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'and in his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 52, NULL, 'Saying"وَلَا تُضَارُّوهُنَّ لِتُضَيِّقُوا عَلَيْهِنَّ""And do not harm them so as to straiten them."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'saying ولا تضاروهن لتضيقوا عليهن and do not harm them so as to straiten them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 53, NULL, 'The Prophet (صَلَّع) said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'the prophet صلع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 54, NULL, 'Saying"خَيْرُكُمْ خَيْرُكُمْ لِاَهْلِهِ""The best of you is the best of you to his family."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'saying خيركم خيركم لاهله the best of you is the best of you to his family', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 55, NULL, 'It is fitting that the one who marries hold a wedding feast on the day of the marriage or the day after it — once or twice, according to his means — so that the matter be made known. The same applies at the time of the عَقِيقَة, at circumcision, and upon a traveler''s return from a journey, so that the benefits of travel become plain to those who have remained at home.', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'it is fitting that the one who marries hold a wedding feast on the day of the marriage or the day after it once or twice according to his means so that the matter be made known the same applies at the time of the عقيقه at circumcision and upon a travelers return from a journey so that the benefits of travel become plain to those who have remained at home', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 56, NULL, 'It is not permissible for a woman to wear the dress of a man, nor for a man to wear the dress of a woman, nor may either be compelled to jewelry or garments beyond what their means allow.', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'it is not permissible for a woman to wear the dress of a man nor for a man to wear the dress of a woman nor may either be compelled to jewelry or garments beyond what their means allow', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 57, NULL, 'A woman asked the Prophet (صَلَّع), saying: "What is the right of the husband over the wife?" He said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'a woman asked the prophet صلع saying what is the right of the husband over the wife he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 58, NULL, 'Saying"لَا تَتَصَدَّقْ مِنْ مَالِهِ اِلَّا بِاِذْنِهِ وَلَا تَمْنَعْهُ نَفْسَهَا وَلَا تَصُومْ تَطَوُّعًا اِلَّا بِاِذْنِهِ وَلَا تَخْرُجْ مِنْ بَيْتِهِ اِلَّا بِاِذْنِهِ""She is not to give in charity from his wealth except by his leave, nor to refuse him herself, nor to fast voluntarily except by his leave, nor to leave his house except by his leave."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'saying لا تتصدق من ماله الا باذنه ولا تمنعه نفسها ولا تصوم تطوعا الا باذنه ولا تخرج من بيته الا باذنه she is not to give in charity from his wealth except by his leave nor to refuse him herself nor to fast voluntarily except by his leave nor to leave his house except by his leave', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'the contract: forbidden degrees, guardians, and the bride-price', '9. The Contract: Forbidden Degrees, Guardians, and the Bride-Price', 59, NULL, 'The woman then said: "Then who among people has the greatest right over a man?" He said: "His mother." She said: "Then who among people has the greatest right over a woman?" He said: "Her husband."', '', NULL, NULL, NULL, NULL, 'sharh al masail 9 the contract forbidden degrees guardians and the bride price', 'the woman then said then who among people has the greatest right over a man he said his mother she said then who among people has the greatest right over a woman he said her husband', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 0, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 1, NULL, 'Sayingوَإِنْ أَرَدْتُمْ أَنْ تَسْتَرْضِعُوا أَوْلَادَكُمْ فَلَا جُنَاحَ عَلَيْكُمْ إِذَا سَلَّمْتُمْ مَا آتَيْتُمْ بِالْمَعْرُوفِ"If you wish to have your children breastfed, there is no blame on you, provided you pay what you have promised in a fair manner."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'sayingوان اردتم ان تسترضعوا اولادكم فلا جناح عليكم اذا سلمتم ما اتيتم بالمعروف if you wish to have your children breastfed there is no blame on you provided you pay what you have promised in a fair manner', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 2, NULL, 'Parents may arrange for their children to be nursed by whoever is willing. A mother may say: "I will nurse him, my brother, for I am satisfied."', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'parents may arrange for their children to be nursed by whoever is willing a mother may say i will nurse him my brother for i am satisfied', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 3, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 4, NULL, 'Al-Baqarah: 233وَالْوَالِدَاتُ يُرْضِعْنَ أَوْلَادَهُنَّ حَوْلَيْنِ كَامِلَيْنِ لِمَنْ أَرَادَ أَنْ يُتِمَّ الرَّضَاعَةَ"And mothers shall nurse their children two complete years, for whoever wishes to complete the nursing."', '', NULL, 'Al-Baqarah: 233', NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'al baqarah 233والوالدات يرضعن اولادهن حولين كاملين لمن اراد ان يتم الرضاعه and mothers shall nurse their children two complete years for whoever wishes to complete the nursing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 5, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 6, NULL, 'Sayingوَأُمَّهَاتُكُمُ اللَّاتِي أَرْضَعْنَكُمْ وَأَخَوَاتُكُمْ مِنَ الرَّضَاعَةِ"And your mothers who have nursed you, and your sisters through nursing."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'sayingوامهاتكم اللاتي ارضعنكم واخواتكم من الرضاعه and your mothers who have nursed you and your sisters through nursing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 7, NULL, 'The hadith establishes that breastfeeding creates the same prohibitions as birth:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'the hadith establishes that breastfeeding creates the same prohibitions as birth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 8, NULL, 'Sayingيَحْرُمُ مِنَ الرَّضَاعَةِ مَا يَحْرُمُ مِنَ النَّسَبِ"What is forbidden through nursing is what is forbidden through lineage."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'sayingيحرم من الرضاعه ما يحرم من النسب what is forbidden through nursing is what is forbidden through lineage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 9, NULL, 'The ruling of breastfeeding applies in a specific way. The verse indicates that when breastfeeding occurs with the consent of the person responsible for the newborn — wealthy or not — it carries full legal consequences.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'the ruling of breastfeeding applies in a specific way the verse indicates that when breastfeeding occurs with the consent of the person responsible for the newborn wealthy or not it carries full legal consequences', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 10, NULL, 'The relevant rulings are as follows:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'the relevant rulings are as follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 11, NULL, 'If a woman breastfeeds a child without the permission of the person responsible for him. If that permission is granted, the ruling falls on the one who pays for it, whether the milk reaches the child through his ears or nose. If the woman''s milk has increased to the point of causing her discomfort, and a milk vessel is lost — or what was placed in the child''s mouth, or given to a cousin, is lost within the two-year period — even a single swallow suffices, since the newborn inevitably swallows the milk.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'if a woman breastfeeds a child without the permission of the person responsible for him if that permission is granted the ruling falls on the one who pays for it whether the milk reaches the child through his ears or nose if the womans milk has increased to the point of causing her discomfort and a milk vessel is lost or what was placed in the childs mouth or given to a cousin is lost within the two year period even a single swallow suffices since the newborn inevitably swallows the milk', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 12, NULL, 'In the first case, breastfeeding does not require the consent of the responsible party. In the second, the breastfeeding is unintentional and therefore does not establish a prohibition. When breastfeeding is conducted through a proper nursing arrangement, such breastfeeding does not establish prohibited degrees of kinship, even if the milk reaches the child by dripping through the nose or ear, by tube in cases of throat injury, or by injection.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'in the first case breastfeeding does not require the consent of the responsible party in the second the breastfeeding is unintentional and therefore does not establish a prohibition when breastfeeding is conducted through a proper nursing arrangement such breastfeeding does not establish prohibited degrees of kinship even if the milk reaches the child by dripping through the nose or ear by tube in cases of throat injury or by injection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 13, NULL, 'The second principle drawn from the verse is that permissible nursing is limited to two full years from the day of birth, calculated as complete months. All who breastfeed the child within this period fall under the relevant prohibition. If the woman has never given birth or is infertile, it sometimes happens that a small amount of milk appears from her nonetheless, but the condition for the prohibition to apply is that the nursing woman must not be born of unlawful relations. If breastfeeding is desired after the child''s bones have developed further — which falls around a specific threshold — such breastfeeding is permitted when undertaken out of necessity. The Imam, after a period of illness, is not considered to be nursing in a lawful manner under these circumstances.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'the second principle drawn from the verse is that permissible nursing is limited to two full years from the day of birth calculated as complete months all who breastfeed the child within this period fall under the relevant prohibition if the woman has never given birth or is infertile it sometimes happens that a small amount of milk appears from her nonetheless but the condition for the prohibition to apply is that the nursing woman must not be born of unlawful relations if breastfeeding is desired after the childs bones have developed further which falls around a specific threshold such breastfeeding is permitted when undertaken out of necessity the imam after a period of illness is not considered to be nursing in a lawful manner under these circumstances', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 14, NULL, 'Concerning the milk of the sire, Ali (ع) said: لَبَنُ الْفَحْلِ يُحَرِّمُ, "the milk of the sire creates prohibition." Milk-kinship prohibits marriage: those who share milk from a single woman become forbidden to one another as foster-siblings. If a man has multiple wives and a boy is nursed by one of them, the boy becomes the milk-son of that wife alone, not of the others. Yet all those co-wives are forbidden to one another''s milk-children by virtue of the shared household bond. Even if the husband did not intend to establish milk-kinship, the suckling alone is sufficient to create the prohibition.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'concerning the milk of the sire ali ع said لبن الفحل يحرم the milk of the sire creates prohibition milk kinship prohibits marriage those who share milk from a single woman become forbidden to one another as foster siblings if a man has multiple wives and a boy is nursed by one of them the boy becomes the milk son of that wife alone not of the others yet all those co wives are forbidden to one anothers milk children by virtue of the shared household bond even if the husband did not intend to establish milk kinship the suckling alone is sufficient to create the prohibition', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 15, NULL, 'If a single woman nurses multiple children — whether brought to her from infancy or not — all of those children become milk-siblings to one another and are forbidden from marrying each other.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'if a single woman nurses multiple children whether brought to her from infancy or not all of those children become milk siblings to one another and are forbidden from marrying each other', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 16, NULL, 'When a woman nurses a man''s child, she becomes forbidden to him, as do her mother, her female ancestors, her daughters, and her granddaughters. His mother may not be given in marriage to her son''s milk-brother, and her daughters are likewise forbidden in this way.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'when a woman nurses a mans child she becomes forbidden to him as do her mother her female ancestors her daughters and her granddaughters his mother may not be given in marriage to her sons milk brother and her daughters are likewise forbidden in this way', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 17, NULL, 'If the nursing woman is a slave, the prohibitions still apply in full: her daughters and the daughters of those above her in lineage are all forbidden, whether they came from the same husband or from another. However milk-kinship arises, the woman who has nursed a man is forbidden to him.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'if the nursing woman is a slave the prohibitions still apply in full her daughters and the daughters of those above her in lineage are all forbidden whether they came from the same husband or from another however milk kinship arises the woman who has nursed a man is forbidden to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 18, NULL, 'A man''s foster-daughters and foster-granddaughters are all forbidden to him through nursing. Nursing does not diminish a daughter''s natural prohibition; she remains forbidden. So too are his foster-sister, his foster-nieces through brother or sister, and his foster-aunts on both sides.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'a mans foster daughters and foster granddaughters are all forbidden to him through nursing nursing does not diminish a daughters natural prohibition she remains forbidden so too are his foster sister his foster nieces through brother or sister and his foster aunts on both sides', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 19, NULL, 'Nursing also prohibits the combining of two foster-sisters in one marriage, and similarly prohibits combining a woman with her foster-aunt on either side, whether through nursing or through direct marriage.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'nursing also prohibits the combining of two foster sisters in one marriage and similarly prohibits combining a woman with her foster aunt on either side whether through nursing or through direct marriage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 20, NULL, 'A man who has a son nursed by a woman may marry a different woman — one who was not nursed by that same woman — without any prohibition applying to her, since she is not a milk-sister and is otherwise unrelated to him. The foster-brother who was nursed bears no restriction regarding a woman outside the prohibited circle, nor is that woman his father''s wife in any sense.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'a man who has a son nursed by a woman may marry a different woman one who was not nursed by that same woman without any prohibition applying to her since she is not a milk sister and is otherwise unrelated to him the foster brother who was nursed bears no restriction regarding a woman outside the prohibited circle nor is that woman his fathers wife in any sense', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 21, NULL, 'They may also marry the woman who nursed their son, under certain conditions, and similarly they may marry the daughter of a nurse or wet-nurse, provided those daughters did not themselves suckle the son or his children and no kinship was thereby established. If no Muslim woman is available, it may be permissible with a lawful non-Muslim woman under conditions, provided no harm results — for nursing does not override natural kinship, and nursing does not create prohibition unless Islam''s conditions are met.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'they may also marry the woman who nursed their son under certain conditions and similarly they may marry the daughter of a nurse or wet nurse provided those daughters did not themselves suckle the son or his children and no kinship was thereby established if no muslim woman is available it may be permissible with a lawful non muslim woman under conditions provided no harm results for nursing does not override natural kinship and nursing does not create prohibition unless islams conditions are met', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 22, NULL, 'On the question of whether milk-kinship is proven when nursing occurs after the marriage contract but before consummation, the judge may confirm the prohibition between them. Complete nursing is defined as three consecutive days or ten separate sucklings. If friendship or intimacy had already been established before this was proven, the dowry remains owed and the retribution stands. After the first and second cases, the husband has no further claim, and they are to be separated. The testimony of a foster-brother is acceptable in this matter, and credible testimony is not to be rejected merely on suspicion.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'on the question of whether milk kinship is proven when nursing occurs after the marriage contract but before consummation the judge may confirm the prohibition between them complete nursing is defined as three consecutive days or ten separate sucklings if friendship or intimacy had already been established before this was proven the dowry remains owed and the retribution stands after the first and second cases the husband has no further claim and they are to be separated the testimony of a foster brother is acceptable in this matter and credible testimony is not to be rejected merely on suspicion', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 23, NULL, 'On the Missing Person', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'on the missing person', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 24, NULL, 'Ali said that if the whereabouts of a missing man are known, he is not treated as missing but as absent. The distinction is this: an absent person is known to be somewhere and has a recognized last place of residence, whereas a missing person''s location is entirely unknown.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'ali said that if the whereabouts of a missing man are known he is not treated as missing but as absent the distinction is this an absent person is known to be somewhere and has a recognized last place of residence whereas a missing persons location is entirely unknown', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 25, NULL, 'If a wife complains of lack of maintenance from a missing husband, the judge should first investigate whether the husband left any property. If property is found, it should be used to provide for her. If a guardian has been appointed to administer it, that guardian may spend from it on her behalf. If the property is exhausted and she remains without support, the judge writes to the place where the husband was last known to be, in order to inquire about him.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'if a wife complains of lack of maintenance from a missing husband the judge should first investigate whether the husband left any property if property is found it should be used to provide for her if a guardian has been appointed to administer it that guardian may spend from it on her behalf if the property is exhausted and she remains without support the judge writes to the place where the husband was last known to be in order to inquire about him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 26, NULL, 'If the husband returns before the waiting period is complete and wishes to reclaim his wife, he may do so, and the time of his absence counts accordingly. If he returns after the period has elapsed, her right in that matter stands. As for the missing man, his obligations toward his wife''s maintenance are reckoned among those of persons present from the day he went missing. The wife of a man merely absent, however, has no automatic entitlement beyond what can be established.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'if the husband returns before the waiting period is complete and wishes to reclaim his wife he may do so and the time of his absence counts accordingly if he returns after the period has elapsed her right in that matter stands as for the missing man his obligations toward his wifes maintenance are reckoned among those of persons present from the day he went missing the wife of a man merely absent however has no automatic entitlement beyond what can be established', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 27, NULL, 'On Maintenance', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'on maintenance', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 28, NULL, 'The husband''s obligation is to provide for his family and to fulfill his duties toward them. God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'the husbands obligation is to provide for his family and to fulfill his duties toward them god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 29, NULL, 'An-Nisa: 5وَارْزُقُوهُمْ فِيهَا وَاكْسُوهُمْ وَقُولُوا لَهُمْ قَوْلًا مَعْرُوفًا"And provide for them from it, and clothe them, and speak to them a kindly word."', '', NULL, 'An-Nisa: 5', NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'an nisa 5وارزقوهم فيها واكسوهم وقولوا لهم قولا معروفا and provide for them from it and clothe them and speak to them a kindly word', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 30, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 31, NULL, 'Al-Baqarah: 236وَعَلَى الْمُوسِعِ قَدَرُهُ وَعَلَى الْمُقْتِرِ قَدَرُهُ"Upon the man of means according to his means, and upon the straitened according to his."', '', NULL, 'Al-Baqarah: 236', NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'al baqarah 236وعلي الموسع قدره وعلي المقتر قدره upon the man of means according to his means and upon the straitened according to his', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 32, NULL, 'The hadith makes plain that neglecting those who depend on one is a grave matter:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'the hadith makes plain that neglecting those who depend on one is a grave matter', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 33, NULL, 'Sayingكَفَى بِالْمَرْءِ إِثْمًا أَنْ يُضَيِّعَ مَنْ يَعُولُ، وَأَنْ لَا يَشْبَعَ الرَّجُلُ وَيُجِيعَ أَهْلَهُ، الرِّفْقُ نِصْفُ الْعَيْشِ، مَنِ اقْتَصَدَ فِي مَعِيشَتِهِ رَزَقَهُ اللَّهُ وَمَنْ بَذَّرَ حَرَمَهُ اللَّهُ، إِذَا أَرَادَ اللَّهُ بِأَهْلِ بَيْتٍ خَيْرًا فَقَّهَهُمْ فِي الدِّينِ وَرَزَقَهُمُ الرِّفْقَ فِي مَعِيشَتِهِمْ وَالْقَصْدَ فِي شَأْنِهِمْ"It is enough sin for a man that he neglect those he supports, and that a man eat his fill while his family goes hungry. Gentleness is half of living. Whoever is moderate in his livelihood, God provides for him, and whoever squanders, God withholds from him. When God intends good for a household, He gives them understanding in religion, gentleness in their livelihood, and moderation in their affairs."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'sayingكفي بالمرء اثما ان يضيع من يعول وان لا يشبع الرجل ويجيع اهله الرفق نصف العيش من اقتصد في معيشته رزقه الله ومن بذر حرمه الله اذا اراد الله باهل بيت خيرا فقههم في الدين ورزقهم الرفق في معيشتهم والقصد في شانهم it is enough sin for a man that he neglect those he supports and that a man eat his fill while his family goes hungry gentleness is half of living whoever is moderate in his livelihood god provides for him and whoever squanders god withholds from him when god intends good for a household he gives them understanding in religion gentleness in their livelihood and moderation in their affairs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 34, NULL, 'A man should be kind to his family, and the appropriate standard of living is one that is neither wasteful nor miserly. Abu Jafar Muhammad ibn Ali (ع) spoke concerning the words of God Almighty — وَلَا تُبَذِّرْ تَبْذِيرًا — "and do not squander wastefully." He said: لَيْسَ فِي طَاعَةِ اللَّهِ تَبْذِيرٌ — "there is no squandering in obedience to God."', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'a man should be kind to his family and the appropriate standard of living is one that is neither wasteful nor miserly abu jafar muhammad ibn ali ع spoke concerning the words of god almighty ولا تبذر تبذيرا and do not squander wastefully he said ليس في طاعه الله تبذير there is no squandering in obedience to god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 35, NULL, 'From this principle it follows that when a man finds he cannot provide for what has already passed and he bears responsibility for someone — whether his wife in Egypt or elsewhere — and he has nothing, the matter rests with the two parties: if she accepts the situation, she remains with him; if she does not, the absence of maintenance entitles her to seek relief.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'from this principle it follows that when a man finds he cannot provide for what has already passed and he bears responsibility for someone whether his wife in egypt or elsewhere and he has nothing the matter rests with the two parties if she accepts the situation she remains with him if she does not the absence of maintenance entitles her to seek relief', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 36, NULL, 'It is also held that a woman of any age, whether young or old, or one who does not observe prayer, is entitled to maintenance from her husband commensurate with her proximity to him. If the husband is a man of means who has left without his wife''s permission and has been living elsewhere at his own expense, then if there is rebellion — نشوز — on her part, she is not entitled to maintenance until she returns.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'it is also held that a woman of any age whether young or old or one who does not observe prayer is entitled to maintenance from her husband commensurate with her proximity to him if the husband is a man of means who has left without his wifes permission and has been living elsewhere at his own expense then if there is rebellion نشوز on her part she is not entitled to maintenance until she returns', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 37, NULL, 'As for the divorced woman, maintenance remains her husband''s responsibility, except in the case of an irrevocable divorce — unless he fails to provide and she keeps silent about it against him until she gives birth. She is entitled to maintenance if she breastfeeds her child, or if she was divorced, as God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'as for the divorced woman maintenance remains her husbands responsibility except in the case of an irrevocable divorce unless he fails to provide and she keeps silent about it against him until she gives birth she is entitled to maintenance if she breastfeeds her child or if she was divorced as god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 38, NULL, 'Al-Baqarah: 233وَلَا تُضَارَّ وَالِدَةٌ بِوَلَدِهَا وَلَا مَوْلُودٌ لَهُ بِوَلَدِهِ"Let no mother be harmed on account of her child, nor a father on account of his child."', '', NULL, 'Al-Baqarah: 233', NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'al baqarah 233ولا تضار والده بولدها ولا مولود له بولده let no mother be harmed on account of her child nor a father on account of his child', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 39, NULL, 'And God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'and god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 40, NULL, 'يَا أَيُّهَا النَّبِيُّ إِذَا طَلَّقْتُمُ النِّسَاءَ فَطَلِّقُوهُنَّ لِعِدَّتِهِنَّ وَأَحْصُوا الْعِدَّةَ ...فَإِذَا بَلَغْنَ أَجَلَهُنَّ فَأَمْسِكُوهُنَّ بِمَعْرُوفٍ أَوْ فَارِقُوهُنَّ بِمَعْرُوفٍ وَأَشْهِدُوا ذَوَيْ عَدْلٍ مِنْكُمْ وَأَقِيمُوا الشَّهَادَةَ لِلَّهِ"O Prophet, when you divorce women, divorce them at the beginning of their waiting periods, and count the waiting period... And when they reach their term, either retain them honorably or part from them honorably, and call to witness two just men among you, and establish the testimony for God."', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'يا ايها النبي اذا طلقتم النساء فطلقوهن لعدتهن واحصوا العده فاذا بلغن اجلهن فامسكوهن بمعروف او فارقوهن بمعروف واشهدوا ذوي عدل منكم واقيموا الشهاده لله o prophet when you divorce women divorce them at the beginning of their waiting periods and count the waiting period and when they reach their term either retain them honorably or part from them honorably and call to witness two just men among you and establish the testimony for god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 41, NULL, 'A letter was written to Rufaah, judge of Egypt, on the matter of divorce: خُذْ حَذَرَكَ فِيهِ — "take care in it." The admonition applies wherever Muslims have not been taught the proper conduct of marriage, for people are bound to follow the established ways of their community.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'a letter was written to rufaah judge of egypt on the matter of divorce خذ حذرك فيه take care in it the admonition applies wherever muslims have not been taught the proper conduct of marriage for people are bound to follow the established ways of their community', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 42, NULL, 'On the Dissolution of a Marriage', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'on the dissolution of a marriage', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 43, NULL, 'Marriage is not merely a contract between two spouses. The husband bears obligations — the dowry, maintenance, and honorable companionship — and the wife bears her own: chastity, affection, and obedience, together with the other terms of the covenant. When that covenant is broken and one party inflicts serious harm by neglecting the duties assigned to the husband, the marriage contract may be dissolved.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'marriage is not merely a contract between two spouses the husband bears obligations the dowry maintenance and honorable companionship and the wife bears her own chastity affection and obedience together with the other terms of the covenant when that covenant is broken and one party inflicts serious harm by neglecting the duties assigned to the husband the marriage contract may be dissolved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 44, NULL, 'Just as a woman does not generally enter marriage without a representative or guardian, the dissolution of a marriage is likewise initiated only by the representative of the aggrieved party — the one who complains on her behalf and seeks her protection from harm. The judge must investigate whether the complaint is true. If it is, he may compel the husband to cease the harm or hold his peace.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'just as a woman does not generally enter marriage without a representative or guardian the dissolution of a marriage is likewise initiated only by the representative of the aggrieved party the one who complains on her behalf and seeks her protection from harm the judge must investigate whether the complaint is true if it is he may compel the husband to cease the harm or hold his peace', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 45, NULL, 'Should the husband fail to respond to the judge''s intervention, the judge may proceed to issue a divorce on his behalf. Yet if news of the husband''s willingness to comply reaches the court, and the wife''s circumstances allow it, he may be restored to her care — on the condition that he treats her and the members of the household with renewed kindness. After that, the husband faces a choice: he may retain her on the terms he has acknowledged, or he may divorce her, and that divorce is revocable. The sacred law in this matter takes careful account of the rights of both parties and the proper ordering of their lives together.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'should the husband fail to respond to the judges intervention the judge may proceed to issue a divorce on his behalf yet if news of the husbands willingness to comply reaches the court and the wifes circumstances allow it he may be restored to her care on the condition that he treats her and the members of the household with renewed kindness after that the husband faces a choice he may retain her on the terms he has acknowledged or he may divorce her and that divorce is revocable the sacred law in this matter takes careful account of the rights of both parties and the proper ordering of their lives together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 46, NULL, 'Divorce was recognized in earlier revealed laws and among the prophets before Islam, and it accords with the law of nature. Marriage governs the living relations of a couple under the purified covenants between them; when one party violates those covenants, the authority of justice may deprive him of that bond. This deprivation, in the language of the Shariah, is called divorce.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'divorce was recognized in earlier revealed laws and among the prophets before islam and it accords with the law of nature marriage governs the living relations of a couple under the purified covenants between them when one party violates those covenants the authority of justice may deprive him of that bond this deprivation in the language of the shariah is called divorce', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 47, NULL, 'Divorce serves both parties by sparing each from further harm. It should not, however, be regarded as a final remedy for every difficulty. Its ruin falls upon the one who wastes it through abuse, or upon the one who pursues remarriage in humiliation. As the wise man said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'divorce serves both parties by sparing each from further harm it should not however be regarded as a final remedy for every difficulty its ruin falls upon the one who wastes it through abuse or upon the one who pursues remarriage in humiliation as the wise man said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 48, NULL, 'Sayingاَتَيْتُ لِلْوَصْلِ لَا لِلْفَصْلِ"Patience in the face of hardship is better than separation."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'sayingاتيت للوصل لا للفصل patience in the face of hardship is better than separation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 49, NULL, 'The bitterness of parting after intimacy is, in Islam, like the image of nakedness after clothing — something the discerning find deeply grievous.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'the bitterness of parting after intimacy is in islam like the image of nakedness after clothing something the discerning find deeply grievous', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 50, NULL, 'The jurists identify five forms of marital dissolution:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'the jurists identify five forms of marital dissolution', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 51, NULL, 'طَلَاقُ الْعِدَّةِ, the divorce of the waiting period الخلع, khula الإيلاء, ila الظهار, zihar اللعان, lian', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'طلاق العده the divorce of the waiting period الخلع khula الايلاء ila الظهار zihar اللعان lian', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 52, NULL, 'Each carries a meaning clarified in its proper place. The divorce of the rebellious wife is also recognized.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'each carries a meaning clarified in its proper place the divorce of the rebellious wife is also recognized', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 53, NULL, 'When a husband wishes to divorce his wife, he must attend to three things:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'when a husband wishes to divorce his wife he must attend to three things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 54, NULL, 'She is in a state of purity from menstruation. He has not had relations with her since that purification. The correct procedure: he records the divorce in writing — to the effect that "my wife, the daughter of so-and-so, is divorced by me today" — calls two men as witnesses, and does all of this in the presence of the proper authority.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'she is in a state of purity from menstruation he has not had relations with her since that purification the correct procedure he records the divorce in writing to the effect that my wife the daughter of so and so is divorced by me today calls two men as witnesses and does all of this in the presence of the proper authority', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 55, NULL, 'If a husband dies during the first or second waiting period while the other party is still alive — even if the husband fell ill during those days and death came before the waiting period was complete — the dissolution is valid and complete.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'if a husband dies during the first or second waiting period while the other party is still alive even if the husband fell ill during those days and death came before the waiting period was complete the dissolution is valid and complete', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 56, NULL, 'Where the marriage was of the kind in which the couple lived together, and the man divorces the woman once and then a second time, and she then marries another man, and the waiting period of that second marriage ends, and she is released from it — whether through its natural completion or through separation — she returns to the first husband, who retains one further divorce with her, this being the second of his remaining. The divorce of a wife who has returned to him from a second husband does not grant him three fresh separations from her, except after consummation and the fulfillment of the three conditions already named.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'where the marriage was of the kind in which the couple lived together and the man divorces the woman once and then a second time and she then marries another man and the waiting period of that second marriage ends and she is released from it whether through its natural completion or through separation she returns to the first husband who retains one further divorce with her this being the second of his remaining the divorce of a wife who has returned to him from a second husband does not grant him three fresh separations from her except after consummation and the fulfillment of the three conditions already named', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 57, NULL, 'Five categories of wives are exempt from these conditions:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'five categories of wives are exempt from these conditions', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 58, NULL, 'the pregnant woman who has not yet reached full term the one who has not been touched by her husband the one who is not an adult the one for whom three months have passed since the divorce, completing the count of her waiting period', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'the pregnant woman who has not yet reached full term the one who has not been touched by her husband the one who is not an adult the one for whom three months have passed since the divorce completing the count of her waiting period', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 59, NULL, 'The written record does not substitute for a spoken pronouncement. A sound and explicit utterance of the word of divorce is required, so that no doubt remains with the woman. Even where there is an intention to cast doubt, a wink, a gesture, or the words of one who is intoxicated do not constitute divorce.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'the written record does not substitute for a spoken pronouncement a sound and explicit utterance of the word of divorce is required so that no doubt remains with the woman even where there is an intention to cast doubt a wink a gesture or the words of one who is intoxicated do not constitute divorce', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 60, NULL, 'On Khula', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'on khula', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 61, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 62, NULL, 'Sayingوَلَا يَحِلُّ لَكُمْ أَنْ تَأْخُذُوا مِمَّا آتَيْتُمُوهُنَّ شَيْئًا إِلَّا أَنْ يَخَافَا أَلَّا يُقِيمَا حُدُودَ اللَّهِ فَإِنْ خِفْتُمْ أَلَّا يُقِيمَا حُدُودَ اللَّهِ فَلَا جُنَاحَ عَلَيْهِمَا فِيمَا افْتَدَتْ بِهِ ..."It is not permissible for you to take back anything of what you have given them, unless both fear that they cannot maintain the limits of God. If you fear that they cannot maintain the limits of God, there is no blame upon either of them for what she gives in ransom."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'sayingولا يحل لكم ان تاخذوا مما اتيتموهن شييا الا ان يخافا الا يقيما حدود الله فان خفتم الا يقيما حدود الله فلا جناح عليهما فيما افتدت به it is not permissible for you to take back anything of what you have given them unless both fear that they cannot maintain the limits of god if you fear that they cannot maintain the limits of god there is no blame upon either of them for what she gives in ransom', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 63, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 64, NULL, 'An-Nisa: 35وَإِنْ خِفْتُمْ شِقَاقَ بَيْنِهِمَا فَابْعَثُوا حَكَمًا مِنْ أَهْلِهِ وَحَكَمًا مِنْ أَهْلِهَا إِنْ يُرِيدَا إِصْلَاحًا يُوَفِّقِ اللَّهُ بَيْنَهُمَا"And if you fear discord between them, appoint an arbitrator from his family and an arbitrator from her family. If they seek reconciliation, God will bring them together."', '', NULL, 'An-Nisa: 35', NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'an nisa 35وان خفتم شقاق بينهما فابعثوا حكما من اهله وحكما من اهلها ان يريدا اصلاحا يوفق الله بينهما and if you fear discord between them appoint an arbitrator from his family and an arbitrator from her family if they seek reconciliation god will bring them together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 65, NULL, 'Ali said: اَلْخَلْعُ طَلَاقٌ, "khula is divorce." Where union and agreement between the couple are no longer possible, and the woman says, "I cannot fulfill your rights as a returning wife — take this amount from me in exchange," she is offering something in return for her release, whether an unspecified amount or a known sum. That offering may be her dowry returned to him, or the use of her mount for a period, or her service for a period of time, or something of a similar kind. If the husband agrees and says, "I accept your satisfaction," and the matter is brought before the authority with witnesses and a written document — recording that on such a date the husband is content and the wife has offered a sum acceptable to both — then, if both parties accept, the khula is valid, and neither will be judged unjustly on account of it. It is fitting for the husband, if he is content with a sum at all, to be content with less than the dowry he originally gave her, or with whatever the two have agreed upon.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'ali said الخلع طلاق khula is divorce where union and agreement between the couple are no longer possible and the woman says i cannot fulfill your rights as a returning wife take this amount from me in exchange she is offering something in return for her release whether an unspecified amount or a known sum that offering may be her dowry returned to him or the use of her mount for a period or her service for a period of time or something of a similar kind if the husband agrees and says i accept your satisfaction and the matter is brought before the authority with witnesses and a written document recording that on such a date the husband is content and the wife has offered a sum acceptable to both then if both parties accept the khula is valid and neither will be judged unjustly on account of it it is fitting for the husband if he is content with a sum at all to be content with less than the dowry he originally gave her or with whatever the two have agreed upon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 66, NULL, 'Each spouse may appoint an arbitrator from his or her own side, or they may agree upon a single person. Whatever the arbitrators decide must rest on the agreement of both spouses, and it is binding upon them. This procedure was recorded by the author in his legal compilation so that neither spouse transgresses the rights of the other. Whoever brings them before a judge to reach agreement, or who declares an explicit divorce, must have the wife observe her waiting period — in her husband''s house or elsewhere — since it is not permissible for her to marry another until the waiting period is complete. Should the two wish to marry each other again, whether during the waiting period or after it, that remains open to them.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'each spouse may appoint an arbitrator from his or her own side or they may agree upon a single person whatever the arbitrators decide must rest on the agreement of both spouses and it is binding upon them this procedure was recorded by the author in his legal compilation so that neither spouse transgresses the rights of the other whoever brings them before a judge to reach agreement or who declares an explicit divorce must have the wife observe her waiting period in her husbands house or elsewhere since it is not permissible for her to marry another until the waiting period is complete should the two wish to marry each other again whether during the waiting period or after it that remains open to them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 67, NULL, 'On the Waiting Period', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'on the waiting period', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 68, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 69, NULL, 'Sayingوَالَّذِينَ يُتَوَفَّوْنَ مِنْكُمْ وَيَذَرُونَ أَزْوَاجًا يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ أَرْبَعَةَ أَشْهُرٍ وَعَشْرًا، وَالْمُطَلَّقَاتُ يَتَرَبَّصْنَ بِأَنْفُسِهِنَّ ثَلَاثَةَ قُرُوءٍ، وَاللَّائِي يَئِسْنَ مِنَ الْمَحِيضِ مِنْ نِسَائِكُمْ إِنِ ارْتَبْتُمْ فَعِدَّتُهُنَّ ثَلَاثَةُ أَشْهُرٍ وَاللَّائِي لَمْ يَحِضْنَ، وَأُولَاتُ الْأَحْمَالِ أَجَلُهُنَّ أَنْ يَضَعْنَ حَمْلَهُنَّ وَلَوْ كَانَ بَعْدَ الطَّلَاقِ بِسَاعَةٍ"Those of you who die and leave behind wives, they shall wait four months and ten days. And divorced women shall wait three menstrual cycles. As for those of your women who have despaired of menstruation, if you are in doubt, their waiting period is three months, and likewise those who have not menstruated. And those who are pregnant, their term is that they deliver, even if it be an hour after the divorce."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'sayingوالذين يتوفون منكم ويذرون ازواجا يتربصن بانفسهن اربعه اشهر وعشرا والمطلقات يتربصن بانفسهن ثلاثه قروء واللايي ييسن من المحيض من نسايكم ان ارتبتم فعدتهن ثلاثه اشهر واللايي لم يحضن واولات الاحمال اجلهن ان يضعن حملهن ولو كان بعد الطلاق بساعه those of you who die and leave behind wives they shall wait four months and ten days and divorced women shall wait three menstrual cycles as for those of your women who have despaired of menstruation if you are in doubt their waiting period is three months and likewise those who have not menstruated and those who are pregnant their term is that they deliver even if it be an hour after the divorce', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 70, NULL, 'The waiting period for a divorced woman is three menstrual cycles; for a woman past menstruation, three months; and for a woman whose husband has died, four months and ten days — whether she is an adult or a minor, whether the marriage was consummated or not.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'the waiting period for a divorced woman is three menstrual cycles for a woman past menstruation three months and for a woman whose husband has died four months and ten days whether she is an adult or a minor whether the marriage was consummated or not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 71, NULL, 'The divorced woman''s intention, where it is possible, is to observe her waiting period in her husband''s house, since he may take her back. In the case of death, maintenance and housing come from the deceased husband''s estate.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'the divorced womans intention where it is possible is to observe her waiting period in her husbands house since he may take her back in the case of death maintenance and housing come from the deceased husbands estate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 72, NULL, 'In a first or second revocable divorce, the husband retains his option: at any point within the waiting period, he may return to her if he wishes and she is content — the return set down in a document before witnesses and in the presence of the proper authority. If he wishes to reunite after the waiting period has expired, that is no longer open to him except by a new marriage contract, after which she remains with him under the count of a first and then a second divorce.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'in a first or second revocable divorce the husband retains his option at any point within the waiting period he may return to her if he wishes and she is content the return set down in a document before witnesses and in the presence of the proper authority if he wishes to reunite after the waiting period has expired that is no longer open to him except by a new marriage contract after which she remains with him under the count of a first and then a second divorce', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 73, NULL, 'In a third divorce, the wife has no claim on her husband for maintenance or housing. He has no right of return, and no reunion between them is possible unless she marries another man who genuinely consummates the marriage with her and is then released from him — by divorce or by death. A marriage arranged merely to enable her return to the first husband does not serve this purpose; the dissolution must be genuine, without manipulation or prior arrangement.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'in a third divorce the wife has no claim on her husband for maintenance or housing he has no right of return and no reunion between them is possible unless she marries another man who genuinely consummates the marriage with her and is then released from him by divorce or by death a marriage arranged merely to enable her return to the first husband does not serve this purpose the dissolution must be genuine without manipulation or prior arrangement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'milk, maintenance, and the untying of a marriage', '10. Milk, Maintenance, and the Untying of a Marriage', 74, NULL, 'A woman whose marriage was never consummated has no waiting period. She may marry immediately — even on the day her first husband divorced her — and in her case there is no right of return. During the waiting period, no man may enter upon a woman except those forbidden to her in marriage, or a servant, or her daughter, or those below the age of puberty and their like. She is permitted the pilgrimage, necessary travel, and attendance with other women for prayer on the virtuous nights and at the noble shrine.', '', NULL, NULL, NULL, NULL, 'sharh al masail 10 milk maintenance and the untying of a marriage', 'a woman whose marriage was never consummated has no waiting period she may marry immediately even on the day her first husband divorced her and in her case there is no right of return during the waiting period no man may enter upon a woman except those forbidden to her in marriage or a servant or her daughter or those below the age of puberty and their like she is permitted the pilgrimage necessary travel and attendance with other women for prayer on the virtuous nights and at the noble shrine', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 0, NULL, 'Wealth passes out of a person''s hands in three ways that reach beyond the span of his life:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'wealth passes out of a persons hands in three ways that reach beyond the span of his life', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 1, NULL, 'what he gives away while he lives what he ties up so that it can never be given away again what he leaves behind for others to divide', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'what he gives away while he lives what he ties up so that it can never be given away again what he leaves behind for others to divide', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 2, NULL, 'Each has its own law, and each is treated in turn.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'each has its own law and each is treated in turn', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 3, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'verse', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 4, NULL, 'Al-Baqarah: 261مَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوَالَهُمْ فِي سَبِيلِ اللَّهِ كَمَثَلِ حَبَّةٍ أَنْبَتَتْ سَبْعَ سَنَابِلَ فِي كُلِّ سُنْبُلَةٍ مِائَةُ حَبَّةٍ وَاللَّهُ يُضَاعِفُ لِمَنْ يَشَاءُ وَاللَّهُ وَاسِعٌ عَلِيمٌ', '', 'مَثَلُ الَّذِينَ يُنْفِقُونَ أَمْوَالَهُمْ فِي سَبِيلِ اللَّهِ كَمَثَلِ حَبَّةٍ أَنْبَتَتْ سَبْعَ سَنَابِلَ فِي كُلِّ سُنْبُلَةٍ مِائَةُ حَبَّةٍ وَاللَّهُ يُضَاعِفُ لِمَنْ يَشَاءُ وَاللَّهُ وَاسِعٌ عَلِيمٌ', 'Al-Baqarah: 261', 2, 261, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'al baqarah 261مثل الذين ينفقون اموالهم في سبيل الله كمثل حبه انبتت سبع سنابل في كل سنبله مايه حبه والله يضاعف لمن يشاء والله واسع عليم', 'مثل الذين ينفقون اموالهم في سبيل الله كمثل حبه انبتت سبع سنابل في كل سنبله مايه حبه والله يضاعف لمن يشاء والله واسع عليم');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 5, NULL, 'The verse reads: "The example of those who spend their wealth in the way of God is like a grain that sprouts seven ears, in every ear a hundred grains. And God multiplies for whom He wills, and God is Vast and Knowing." God Almighty also said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'the verse reads the example of those who spend their wealth in the way of god is like a grain that sprouts seven ears in every ear a hundred grains and god multiplies for whom he wills and god is vast and knowing god almighty also said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'verse', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 6, NULL, 'Al-Baqarah: 262الَّذِينَ يُنْفِقُونَ أَمْوَالَهُمْ فِي سَبِيلِ اللَّهِ ثُمَّ لَا يُتْبِعُونَ مَا أَنْفَقُوا مَنًّا وَلَا أَذًى لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', '', 'الَّذِينَ يُنْفِقُونَ أَمْوَالَهُمْ فِي سَبِيلِ اللَّهِ ثُمَّ لَا يُتْبِعُونَ مَا أَنْفَقُوا مَنًّا وَلَا أَذًى لَهُمْ أَجْرُهُمْ عِنْدَ رَبِّهِمْ وَلَا خَوْفٌ عَلَيْهِمْ وَلَا هُمْ يَحْزَنُونَ', 'Al-Baqarah: 262', 2, 262, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'al baqarah 262الذين ينفقون اموالهم في سبيل الله ثم لا يتبعون ما انفقوا منا ولا اذي لهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون', 'الذين ينفقون اموالهم في سبيل الله ثم لا يتبعون ما انفقوا منا ولا اذي لهم اجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 7, NULL, 'The verse establishes that spending must be purely for God''s sake — free from any reminder of the favor given and free from any harm done to the one who received it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'the verse establishes that spending must be purely for gods sake free from any reminder of the favor given and free from any harm done to the one who received it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 8, NULL, 'On the same matter it is related:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'on the same matter it is related', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 9, NULL, 'Sayingالْخَلْقُ عِيَالُ اللَّهِ، أَحَبُّهُمْ إِلَيْهِ أَنْفَعُهُمْ لِعِيَالِهِ وَأَوْسَعُهُمْ خُلُقًا، مَنْ سَعَى فِي مَعَاوَنَةِ أَخِيهِ كَانَ أَحَبَّ عِنْدَ اللَّهِ مِنْ أَنْ يَعْتَكِفَ شَهْرَيْنِ"Creation is God''s household; the most beloved among them to Him is the one most useful to His household and the most generous in character. Whoever exerts himself in aid of his brother is more beloved to God than one who keeps a retreat of two months."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'sayingالخلق عيال الله احبهم اليه انفعهم لعياله واوسعهم خلقا من سعي في معاونه اخيه كان احب عند الله من ان يعتكف شهرين creation is gods household the most beloved among them to him is the one most useful to his household and the most generous in character whoever exerts himself in aid of his brother is more beloved to god than one who keeps a retreat of two months', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 10, NULL, 'Ali (ع) said that the doer of good acts for another''s benefit asks nothing in return, because he is certain that he acts solely for God''s sake and therefore seeks acknowledgment from no one. He also said that the doer of good begins with his own household, his near kin, and his brothers, then extends his generosity beyond them. If anyone offers him a gift, he receives it graciously and does not refuse it, even if the thing is of no use to him — he places it where others may benefit from it, and compensates the giver with something in return, as God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'ali ع said that the doer of good acts for anothers benefit asks nothing in return because he is certain that he acts solely for gods sake and therefore seeks acknowledgment from no one he also said that the doer of good begins with his own household his near kin and his brothers then extends his generosity beyond them if anyone offers him a gift he receives it graciously and does not refuse it even if the thing is of no use to him he places it where others may benefit from it and compensates the giver with something in return as god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 11, NULL, 'Sayingوَإِذَا حُيِّيتُمْ بِتَحِيَّةٍ فَحَيُّوا بِأَحْسَنَ مِنْهَا أَوْ مِثْلَهَا"And when you are greeted with a greeting, greet with what is better than it, or return it."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'sayingواذا حييتم بتحيه فحيوا باحسن منها او مثلها and when you are greeted with a greeting greet with what is better than it or return it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 12, NULL, 'Jafar al-Sadiq (ع) said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'jafar al sadiq ع said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 13, NULL, 'Sayingلَيْسَ شَيْءٌ أَفْضَلَ مِنَ الْخَيْرِ إِلَّا ثَوَابَهُ"There is nothing more excellent than good, except its reward."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'sayingليس شيء افضل من الخير الا ثوابه there is nothing more excellent than good except its reward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 14, NULL, 'Preferring others over oneself is among the qualities of the people of faith. When God intends good for a servant, He joins to the will the power to act. The doer of good among the people of faith is counted among those who do good; the people of good works in this world are the people of good things in the Hereafter, and they are the foremost to reach the Garden. The doer of good is he who deals openly with his brethren in goodness, aids them in their affairs, and benefits them.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'preferring others over oneself is among the qualities of the people of faith when god intends good for a servant he joins to the will the power to act the doer of good among the people of faith is counted among those who do good the people of good works in this world are the people of good things in the hereafter and they are the foremost to reach the garden the doer of good is he who deals openly with his brethren in goodness aids them in their affairs and benefits them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 15, NULL, 'Al-Qadi al-Numan said that whatever the narrations report concerning the merits of service and its reward pertains to what was done for God and for the face of God — or for the benefit of religion and its people — with no worldly purpose in it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'al qadi al numan said that whatever the narrations report concerning the merits of service and its reward pertains to what was done for god and for the face of god or for the benefit of religion and its people with no worldly purpose in it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 16, NULL, 'Jafar al-Sadiq is reported to have said that nothing continues for a man after his death by way of reward except three things:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'jafar al sadiq is reported to have said that nothing continues for a man after his death by way of reward except three things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 17, NULL, 'A charity he set flowing during his lifetime A righteous child who prays for him A good practice he established — for it works on after his death', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'a charity he set flowing during his lifetime a righteous child who prays for him a good practice he established for it works on after his death', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 18, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'verse', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 19, NULL, 'Al-Baqarah: 264يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُبْطِلُوا صَدَقَاتِكُمْ بِالْمَنِّ وَالْأَذَى كَالَّذِي يُنْفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَمَثَلُهُ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَأَصَابَهُ وَابِلٌ فَتَرَكَهُ صَلْدًا', '', 'يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُبْطِلُوا صَدَقَاتِكُمْ بِالْمَنِّ وَالْأَذَى كَالَّذِي يُنْفِقُ مَالَهُ رِئَاءَ النَّاسِ وَلَا يُؤْمِنُ بِاللَّهِ وَالْيَوْمِ الْآخِرِ فَمَثَلُهُ كَمَثَلِ صَفْوَانٍ عَلَيْهِ تُرَابٌ فَأَصَابَهُ وَابِلٌ فَتَرَكَهُ صَلْدًا', 'Al-Baqarah: 264', 2, 264, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'al baqarah 264يا ايها الذين امنوا لا تبطلوا صدقاتكم بالمن والاذي كالذي ينفق ماله رياء الناس ولا يومن بالله واليوم الاخر فمثله كمثل صفوان عليه تراب فاصابه وابل فتركه صلدا', 'يا ايها الذين امنوا لا تبطلوا صدقاتكم بالمن والاذي كالذي ينفق ماله رياء الناس ولا يومن بالله واليوم الاخر فمثله كمثل صفوان عليه تراب فاصابه وابل فتركه صلدا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 20, NULL, 'The distinction between goodness and charity is this: goodness is general — it may reside in word or deed, in any matter, whether brief or extended. Charity, by contrast, is set for a known term, short or long; it applies to lands, property, livestock, or other things, and all of it is to be written down and made clear.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'the distinction between goodness and charity is this goodness is general it may reside in word or deed in any matter whether brief or extended charity by contrast is set for a known term short or long it applies to lands property livestock or other things and all of it is to be written down and made clear', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 21, NULL, 'Charity falls into two kinds: the gift and the endowment.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'charity falls into two kinds the gift and the endowment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 22, NULL, 'The gift is the transfer of something from one person''s ownership into another''s, either for a known term or in perpetuity; the giver has no right of return before the term is complete. The endowment is the setting aside of an estate — or of something a man customarily gave — so that after his death it is withheld from the heirs.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'the gift is the transfer of something from one persons ownership into anothers either for a known term or in perpetuity the giver has no right of return before the term is complete the endowment is the setting aside of an estate or of something a man customarily gave so that after his death it is withheld from the heirs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 23, NULL, 'The founder may draw benefit from what he has endowed for as long as he lives, since he is the one who established it, provided the endowed thing belongs to the category of real property rather than something liable to loss. In a perishable thing there is the risk of diminution for those to whom it is endowed.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'the founder may draw benefit from what he has endowed for as long as he lives since he is the one who established it provided the endowed thing belongs to the category of real property rather than something liable to loss in a perishable thing there is the risk of diminution for those to whom it is endowed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 24, NULL, 'Imam Jafar al-Sadiq said: "Whoever gives a gift in perpetuity, intending by it the face of God and the abode of the Hereafter and the joining of kinship — recorded, severed, and made plain — has no return to it. Whoever gives a gift for a known term, whether short or long, has the right of return after the term is complete if the thing still stands; but if it has perished, he has no such right."', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'imam jafar al sadiq said whoever gives a gift in perpetuity intending by it the face of god and the abode of the hereafter and the joining of kinship recorded severed and made plain has no return to it whoever gives a gift for a known term whether short or long has the right of return after the term is complete if the thing still stands but if it has perished he has no such right', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 25, NULL, 'He was asked about the lifelong grant, al-umra, and about the right of dwelling, al-sukna, and he said that people are bound by their own stipulations. The dwelling-right, the lifelong grant, and al-ruqba are of one rank; the condition is what distinguishes them:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'he was asked about the lifelong grant al umra and about the right of dwelling al sukna and he said that people are bound by their own stipulations the dwelling right the lifelong grant and al ruqba are of one rank the condition is what distinguishes them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 26, NULL, 'The dwelling-right is that a man settles another person — or several, whether women or men — in his house for a known term, granting that use without compensation. A grant of this kind is also called charity, even though it is not drawn from the estate. The reports record that the Messenger of God gave in charity from his own wealth, making it an endowment, and used to spend from it on his guests. The lifelong grant is that he settles a person there for the whole of that person''s life, or for the lives of his descendants as well. Al-ruqba is that he settles another person there until one of the two dies; when one dies, the ruling of al-ruqba lapses with that death, and the house returns to its rightful people — either to the owner or to whoever inherits from him.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'the dwelling right is that a man settles another person or several whether women or men in his house for a known term granting that use without compensation a grant of this kind is also called charity even though it is not drawn from the estate the reports record that the messenger of god gave in charity from his own wealth making it an endowment and used to spend from it on his guests the lifelong grant is that he settles a person there for the whole of that persons life or for the lives of his descendants as well al ruqba is that he settles another person there until one of the two dies when one dies the ruling of al ruqba lapses with that death and the house returns to its rightful people either to the owner or to whoever inherits from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 27, NULL, 'As for what is related from the Messenger of God:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'as for what is related from the messenger of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 28, NULL, 'Sayingإِنَّ الَّذِي يَتَصَدَّقُ ثُمَّ يَرْجِعُ كَالَّذِي يَقِيءُ ثُمَّ يَرْجِعُ فِي قَيْئِهِ"The one who gives charity and then takes it back is like the one who vomits and then returns to his vomit."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'sayingان الذي يتصدق ثم يرجع كالذي يقيء ثم يرجع في قييه the one who gives charity and then takes it back is like the one who vomits and then returns to his vomit', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 29, NULL, 'That was said at a time when writing was not yet in common use and the giver did not make his intention plain — whether the charity was in perpetuity or for a specified time. Writing is what clarifies the matter, so that nothing is done contrary to his intention.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'that was said at a time when writing was not yet in common use and the giver did not make his intention plain whether the charity was in perpetuity or for a specified time writing is what clarifies the matter so that nothing is done contrary to his intention', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 30, NULL, 'Al-Sadiq (ع) was asked about a man who gave in charity a share held in common, and he said it is valid. He was asked about charity before possession is taken, and he said: if the one given the charity accepted it — or if it was accepted on his behalf because he was a child — it is valid whether possession was taken or not; but if it was not accepted, it counts for nothing until accepted. He was asked about charity of undivided property, and he said it is valid and is received in the way that such property is customarily received.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'al sadiq ع was asked about a man who gave in charity a share held in common and he said it is valid he was asked about charity before possession is taken and he said if the one given the charity accepted it or if it was accepted on his behalf because he was a child it is valid whether possession was taken or not but if it was not accepted it counts for nothing until accepted he was asked about charity of undivided property and he said it is valid and is received in the way that such property is customarily received', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 31, NULL, 'An endowment may be made in anything the founder wishes to dedicate — livestock, land, a house, jewelry, clothing, a sum of money, or a usufruct — so that whoever is endowed to may benefit from it, whether one person or many, whether from among the heirs or from others, and whether the benefit is distributed equally or with distinctions, among men or women or both. Writing distinguishes all of this so that nothing falls into doubt. If the founder stipulates that should he have need of something from the endowment he may take what he requires, that right belongs to him; yet such an endowment remains in force only during his lifetime, and after his death it is divided among the heirs.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'an endowment may be made in anything the founder wishes to dedicate livestock land a house jewelry clothing a sum of money or a usufruct so that whoever is endowed to may benefit from it whether one person or many whether from among the heirs or from others and whether the benefit is distributed equally or with distinctions among men or women or both writing distinguishes all of this so that nothing falls into doubt if the founder stipulates that should he have need of something from the endowment he may take what he requires that right belongs to him yet such an endowment remains in force only during his lifetime and after his death it is divided among the heirs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 32, NULL, 'The founder may administer the endowment himself, or appoint another over it, whether from his relatives or from others. The administrator may take a fee for his service if he has need of it, just as he might pay a fixed allowance to someone else; there is no harm in that. When the administrator sees that an animal has wasted away, a garment worn out, or jewelry or a house fallen into ruin, and there are beneficiaries, he may act with their consent and exchange it for something of easier use, drawing on the value of those things without incurring debt against them. If the beneficiaries themselves wish to contribute to repairs as an act of charity from their own means, the administrator may accept it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'the founder may administer the endowment himself or appoint another over it whether from his relatives or from others the administrator may take a fee for his service if he has need of it just as he might pay a fixed allowance to someone else there is no harm in that when the administrator sees that an animal has wasted away a garment worn out or jewelry or a house fallen into ruin and there are beneficiaries he may act with their consent and exchange it for something of easier use drawing on the value of those things without incurring debt against them if the beneficiaries themselves wish to contribute to repairs as an act of charity from their own means the administrator may accept it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 33, NULL, 'If the founder specified the channels of benefit from the endowed sum — fixing an amount and a time, and stipulating an order — that order is observed. If the benefit is exhausted before all channels are satisfied, there is no harm in it; otherwise the benefit is distributed among those channels equally or with distinctions, out of that benefit, according to the terms of the endowment.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'if the founder specified the channels of benefit from the endowed sum fixing an amount and a time and stipulating an order that order is observed if the benefit is exhausted before all channels are satisfied there is no harm in it otherwise the benefit is distributed among those channels equally or with distinctions out of that benefit according to the terms of the endowment', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 34, NULL, 'Recorded here, for greater clarity in this matter, is the testament of our master Ali ibn Abi Talib, as it is mentioned in the Daaim, in summary. This is what he enjoined and endowed and settled upon his property:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'recorded here for greater clarity in this matter is the testament of our master ali ibn abi talib as it is mentioned in the daaim in summary this is what he enjoined and endowed and settled upon his property', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 35, NULL, 'This is what Ali ibn Abi Talib enjoined, seeking the face of God: what belongs to me at Yanbu of property, and what is known to be mine of it and what lies around it, is charity, except that Riyah and Abu Nayzar and Jubayr are free, no one has any way against them, and they are my freedmen who work in the property for five years, and in it is their maintenance and their sustenance and the sustenance of their families. And with that, what belongs to me in Wadi al-Qura, a third of it, and the property of Fatima and its servants, is charity. And what belongs to me at Daymah and its people is charity, except that Zurayq has for him the like of what I have written for his companions. And what belongs to me at Udhayna and its people is charity. And what I have written of these my properties is a binding, irrevocable charity, so that, whether I live or die, it is spent in every expenditure by which the face of God is sought, in the way of God and for His face, and upon those of kinship from Banu Hashim and Banu Abd al-Muttalib, the near and the far. And in charge of it after that is al-Hasan ibn Ali, eating from it in the proper manner and spending it where God shows him, in what is lawful and made lawful, no blame upon him in it. If he wishes to make property of the charity serve in place of other property, he may do so, no blame upon him in it. If he wishes to sell a portion of the property and discharge a debt with it, he may do so if he wills, no blame upon him in it. And the children of Ali and their property revert to al-Hasan after him. And if al-Hasan ibn Ali has any dwelling other than the house of charity and it seems good to him to sell it, let him sell it if he wills, no blame upon him in it; and if he sells it, then its price is in three parts: a third he places in the way of God, and a third among Banu Hashim, and a third among Banu Abi Talib, placing it among them where God shows him. And if something befalls al-Hasan while al-Husayn is living, then it passes to al-Husayn ibn Ali, and al-Husayn ibn Ali does in it the like of what I commanded al-Hasan, and he has the like of what I have written for al-Hasan and upon him is the like of what is upon al-Hasan. And what belongs to the sons of Fatima of my charity is the like of what belongs to the sons of Ali. And I have appointed what I have appointed to the sons of Fatima seeking the face of God, and honoring the sanctity of Muhammad, and magnifying it and ennobling it and being well pleased with it. And if something befalls al-Hasan and al-Husayn, then the offspring of the survivor of the two shall look into that.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'this is what ali ibn abi talib enjoined seeking the face of god what belongs to me at yanbu of property and what is known to be mine of it and what lies around it is charity except that riyah and abu nayzar and jubayr are free no one has any way against them and they are my freedmen who work in the property for five years and in it is their maintenance and their sustenance and the sustenance of their families and with that what belongs to me in wadi al qura a third of it and the property of fatima and its servants is charity and what belongs to me at daymah and its people is charity except that zurayq has for him the like of what i have written for his companions and what belongs to me at udhayna and its people is charity and what i have written of these my properties is a binding irrevocable charity so that whether i live or die it is spent in every expenditure by which the face of god is sought in the way of god and for his face and upon those of kinship from banu hashim and banu abd al muttalib the near and the far and in charge of it after that is al hasan ibn ali eating from it in the proper manner and spending it where god shows him in what is lawful and made lawful no blame upon him in it if he wishes to make property of the charity serve in place of other property he may do so no blame upon him in it if he wishes to sell a portion of the property and discharge a debt with it he may do so if he wills no blame upon him in it and the children of ali and their property revert to al hasan after him and if al hasan ibn ali has any dwelling other than the house of charity and it seems good to him to sell it let him sell it if he wills no blame upon him in it and if he sells it then its price is in three parts a third he places in the way of god and a third among banu hashim and a third among banu abi talib placing it among them where god shows him and if something befalls al hasan while al husayn is living then it passes to al husayn ibn ali and al husayn ibn ali does in it the like of what i commanded al hasan and he has the like of what i have written for al hasan and upon him is the like of what is upon al hasan and what belongs to the sons of fatima of my charity is the like of what belongs to the sons of ali and i have appointed what i have appointed to the sons of fatima seeking the face of god and honoring the sanctity of muhammad and magnifying it and ennobling it and being well pleased with it and if something befalls al hasan and al husayn then the offspring of the survivor of the two shall look into that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 36, NULL, 'The remainder of the testament is as it is recorded.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'the remainder of the testament is as it is recorded', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 37, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 38, NULL, 'Al-Baqarah: 180كُتِبَ عَلَيْكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ إِنْ تَرَكَ خَيْرًا الْوَصِيَّةُ لِلْوَالِدَيْنِ وَالْأَقْرَبِينَ بِالْمَعْرُوفِ حَقًّا عَلَى الْمُتَّقِينَ"It is prescribed for you, when death approaches one of you and he leaves behind wealth, that he make a bequest for parents and near relatives in the proper manner, a duty upon the God-fearing."', '', NULL, 'Al-Baqarah: 180', NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'al baqarah 180كتب عليكم اذا حضر احدكم الموت ان ترك خيرا الوصيه للوالدين والاقربين بالمعروف حقا علي المتقين it is prescribed for you when death approaches one of you and he leaves behind wealth that he make a bequest for parents and near relatives in the proper manner a duty upon the god fearing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 39, NULL, 'And He said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'and he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 40, NULL, 'Al-Ma''idah: 106يَا أَيُّهَا الَّذِينَ آمَنُوا شَهَادَةُ بَيْنِكُمْ إِذَا حَضَرَ أَحَدَكُمُ الْمَوْتُ حِينَ الْوَصِيَّةِ اثْنَانِ ذَوَا عَدْلٍ مِنْكُمْ أَوْ آخَرَانِ مِنْ غَيْرِكُمْ"O you who believe, testimony among you when death approaches one of you, at the time of bequest, shall be by two just men from among you, or two others from outside."', '', NULL, 'Al-Ma''idah: 106', NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'al maidah 106يا ايها الذين امنوا شهاده بينكم اذا حضر احدكم الموت حين الوصيه اثنان ذوا عدل منكم او اخران من غيركم o you who believe testimony among you when death approaches one of you at the time of bequest shall be by two just men from among you or two others from outside', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 41, NULL, 'And it is related:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'and it is related', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 42, NULL, 'Sayingلَيْسَ يَنْبَغِي لِلْمُسْلِمِ أَنْ يَبِيتَ لَيْلَةً إِلَّا وَوَصِيَّةٌ مَكْتُوبَةٌ عِنْدَ رَأْسِهِ"It is not fitting for a Muslim to pass a night except that a written bequest is at his head."', '', NULL, 'Saying', NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'sayingليس ينبغي للمسلم ان يبيت ليله الا ووصيه مكتوبه عند راسه it is not fitting for a muslim to pass a night except that a written bequest is at his head', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 43, NULL, 'And Abu Jafar (ع) said: الْوَصِيَّةُ حَقٌّ عَلَى كُلِّ مُسْلِمٍ — "The bequest is a duty upon every Muslim."', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'and abu jafar ع said الوصيه حق علي كل مسلم the bequest is a duty upon every muslim', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 44, NULL, 'A bequest records the wishes a person intends to have carried out after his death. During his lifetime, a man or woman of full age owns his or her possessions outright and may give to whomever he wishes, spend freely, or let wealth go. Once death arrives, everything left behind becomes the estate. Of that estate, the deceased retains authority over no more than one third; the remaining two thirds belong to the heirs and lie beyond his power to direct. Should the heirs, being of sound mind, consent to what he gave during his lifetime — to whomever and in whatever manner he wished, or in accordance with the Sharia — that giving stands as permissible. And if the heirs choose to divide those two thirds among themselves by mutual agreement rather than by the division the Sharia prescribes, that choice is theirs to make.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'a bequest records the wishes a person intends to have carried out after his death during his lifetime a man or woman of full age owns his or her possessions outright and may give to whomever he wishes spend freely or let wealth go once death arrives everything left behind becomes the estate of that estate the deceased retains authority over no more than one third the remaining two thirds belong to the heirs and lie beyond his power to direct should the heirs being of sound mind consent to what he gave during his lifetime to whomever and in whatever manner he wished or in accordance with the sharia that giving stands as permissible and if the heirs choose to divide those two thirds among themselves by mutual agreement rather than by the division the sharia prescribes that choice is theirs to make', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 45, NULL, 'Whatever he bequeathed — whether in health or during the illness that preceded his death, whether his faculties were intact or impaired, or the bequest was conveyed by sign — is to be carried out from the estate to the extent possible, even if he distributes the whole of it among his heirs or among others. If, during the illness of his death, he acknowledges a loan owed to someone, that acknowledgment is not acted upon until it is established; the person named is then assessed, and the heirs may choose to permit it.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'whatever he bequeathed whether in health or during the illness that preceded his death whether his faculties were intact or impaired or the bequest was conveyed by sign is to be carried out from the estate to the extent possible even if he distributes the whole of it among his heirs or among others if during the illness of his death he acknowledges a loan owed to someone that acknowledgment is not acted upon until it is established the person named is then assessed and the heirs may choose to permit it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 46, NULL, 'A hadith relates from the Prophet: إِنَّ اللَّهَ عَزَّ وَجَلَّ رَضِيَ بِالْخُمُسِ مِنْ عِبَادِهِ — "God, mighty and majestic, was content with the fifth from His servants." He also said: الْخُمُسُ اقْتِصَادٌ وَالثُّلُثُ حَيْفٌ — "The fifth is moderation and the third is excess" — and that a bequest of a fourth was more beloved to him than a bequest of a third. Master al-Qadi al-Numan held that this reflects a matter of preference as reported from the Prophet, and that a bequest of a third is nonetheless permissible.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'a hadith relates from the prophet ان الله عز وجل رضي بالخمس من عباده god mighty and majestic was content with the fifth from his servants he also said الخمس اقتصاد والثلث حيف the fifth is moderation and the third is excess and that a bequest of a fourth was more beloved to him than a bequest of a third master al qadi al numan held that this reflects a matter of preference as reported from the prophet and that a bequest of a third is nonetheless permissible', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 47, NULL, 'A bequest is voided only by:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'a bequest is voided only by', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 48, NULL, 'Loss of the testator''s reason His apostasy Squandering Breach of trust', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'loss of the testators reason his apostasy squandering breach of trust', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 49, NULL, 'The executor of an executor is himself an executor. If the executor is permitted to trade with the property of a young child, that permission stands and he bears no liability for any loss; and if he stipulated a share of the profit for himself, that stipulation holds. If, however, he traded without having been authorized to do so in the bequest, he is liable for whatever is lost of the property, and the profit belongs to the orphan.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'the executor of an executor is himself an executor if the executor is permitted to trade with the property of a young child that permission stands and he bears no liability for any loss and if he stipulated a share of the profit for himself that stipulation holds if however he traded without having been authorized to do so in the bequest he is liable for whatever is lost of the property and the profit belongs to the orphan', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 50, NULL, 'God Almighty said:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'god almighty said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 51, NULL, 'يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ لِلذَّكَرِ مِثْلُ حَظِّ الْأُنْثَيَيْنِ فَإِنْ كُنَّ نِسَاءً فَوْقَ اثْنَتَيْنِ فَلَهُنَّ ثُلُثَا مَا تَرَكَ وَإِنْ كَانَتْ وَاحِدَةً فَلَهَا النِّصْفُ وَلِأَبَوَيْهِ لِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ مِمَّا تَرَكَ إِنْ كَانَ لَهُ وَلَدٌ فَإِنْ لَمْ يَكُنْ لَهُ وَلَدٌ وَوَرِثَهُ أَبَوَاهُ فَلِأُمِّهِ الثُّلُثُ فَإِنْ كَانَ لَهُ إِخْوَةٌ فَلِأُمِّهِ السُّدُسُ مِنْ بَعْدِ وَصِيَّةٍ يُوصِي بِهَا أَوْ دَيْنٍ آبَاؤُكُمْ وَأَبْنَاؤُكُمْ لَا تَدْرُونَ أَيُّهُمْ أَقْرَبُ لَكُمْ نَفْعًا فَرِيضَةً مِنَ اللَّهِ إِنَّ اللَّهَ كَانَ عَلِيمًا حَكِيمًا.وَلَكُمْ نِصْفُ مَا تَرَكَ أَزْوَاجُكُمْ إِنْ لَمْ يَكُنْ لَهُنَّ وَلَدٌ فَإِنْ كَانَ لَهُنَّ وَلَدٌ فَلَكُمُ الرُّبُعُ مِمَّا تَرَكْنَ مِنْ بَعْدِ وَصِيَّةٍ يُوصِينَ بِهَا أَوْ دَيْنٍ وَلَهُنَّ الرُّبُعُ مِمَّا تَرَكْتُمْ إِنْ لَمْ يَكُنْ لَكُمْ وَلَدٌ فَإِنْ كَانَ لَكُمْ وَلَدٌ فَلَهُنَّ الثُّمُنُ مِمَّا تَرَكْتُمْ مِنْ بَعْدِ وَصِيَّةٍ تُوصُونَ بِهَا أَوْ دَيْنٍ وَإِنْ كَانَ رَجُلٌ يُورَثُ كَلَالَةً أَوِ امْرَأَةٌ وَلَهُ أَخٌ أَوْ أُخْتٌ فَلِكُلِّ وَاحِدٍ مِنْهُمَا السُّدُسُ فَإِنْ كَانُوا أَكْثَرَ مِنْ ذَلِكَ فَهُمْ شُرَكَاءُ فِي الثُّلُثِ مِنْ بَعْدِ وَصِيَّةٍ يُوصَى بِهَا أَوْ دَيْنٍ غَيْرَ مُضَارٍّ وَصِيَّةً مِنَ اللَّهِ وَاللَّهُ عَلِيمٌ حَلِيمٌ"God enjoins you concerning your children: for the male the like of the portion of two females. If they are women, more than two, theirs is two thirds of what he left; and if she is one, hers is the half. And to his parents, to each one of them a sixth of what he left, if he had a child. If he had no child and his parents inherit from him, then to his mother a third; and if he had brothers, then to his mother a sixth, after a bequest he may have made or a debt. Your fathers and your sons, you do not know which of them is nearer to you in benefit. An ordinance from God; indeed God is Knowing, Wise. And yours is half of what your wives leave if they have no child; but if they have a child, then yours is a fourth of what they leave, after a bequest they may have made or a debt. And theirs is a fourth of what you leave if you have no child; but if you have a child, then theirs is an eighth of what you leave, after a bequest you may have made or a debt. And if a man or a woman is inherited from without direct heirs and he has a brother or a sister, then to each one of them a sixth; but if they are more than that, they are partners in the third, after a bequest made or a debt, without injury. A charge from God, and God is Knowing, Forbearing."', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'يوصيكم الله في اولادكم للذكر مثل حظ الانثيين فان كن نساء فوق اثنتين فلهن ثلثا ما ترك وان كانت واحده فلها النصف ولابويه لكل واحد منهما السدس مما ترك ان كان له ولد فان لم يكن له ولد وورثه ابواه فلامه الثلث فان كان له اخوه فلامه السدس من بعد وصيه يوصي بها او دين اباوكم وابناوكم لا تدرون ايهم اقرب لكم نفعا فريضه من الله ان الله كان عليما حكيما ولكم نصف ما ترك ازواجكم ان لم يكن لهن ولد فان كان لهن ولد فلكم الربع مما تركن من بعد وصيه يوصين بها او دين ولهن الربع مما تركتم ان لم يكن لكم ولد فان كان لكم ولد فلهن الثمن مما تركتم من بعد وصيه توصون بها او دين وان كان رجل يورث كلاله او امراه وله اخ او اخت فلكل واحد منهما السدس فان كانوا اكثر من ذلك فهم شركاء في الثلث من بعد وصيه يوصي بها او دين غير مضار وصيه من الله والله عليم حليم god enjoins you concerning your children for the male the like of the portion of two females if they are women more than two theirs is two thirds of what he left and if she is one hers is the half and to his parents to each one of them a sixth of what he left if he had a child if he had no child and his parents inherit from him then to his mother a third and if he had brothers then to his mother a sixth after a bequest he may have made or a debt your fathers and your sons you do not know which of them is nearer to you in benefit an ordinance from god indeed god is knowing wise and yours is half of what your wives leave if they have no child but if they have a child then yours is a fourth of what they leave after a bequest they may have made or a debt and theirs is a fourth of what you leave if you have no child but if you have a child then theirs is an eighth of what you leave after a bequest you may have made or a debt and if a man or a woman is inherited from without direct heirs and he has a brother or a sister then to each one of them a sixth but if they are more than that they are partners in the third after a bequest made or a debt without injury a charge from god and god is knowing forbearing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 52, NULL, 'The order of settlement from the deceased''s estate is therefore as follows:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'the order of settlement from the deceaseds estate is therefore as follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 53, NULL, 'The cost of the shroud and burial is taken out first. Any debt the deceased owed to others is then discharged. From what remains, the third — the deceased''s own share — is examined: from it, the ransom of any outstanding fast or pilgrimage is paid. The bequest, if any was made — whether for good works or otherwise — is then carried out from that third, provided the third is sufficient; if it is not, what the third covers is paid, and nothing beyond it is owed. If the ransom and the obligation had already been discharged and no bequest was made, the third is not set aside at all, and the whole estate is divided among the heirs.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'the cost of the shroud and burial is taken out first any debt the deceased owed to others is then discharged from what remains the third the deceaseds own share is examined from it the ransom of any outstanding fast or pilgrimage is paid the bequest if any was made whether for good works or otherwise is then carried out from that third provided the third is sufficient if it is not what the third covers is paid and nothing beyond it is owed if the ransom and the obligation had already been discharged and no bequest was made the third is not set aside at all and the whole estate is divided among the heirs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 54, NULL, 'Whoever stands nearest to the deceased in the reckoning of the Sharia is his heir; the inheritance passes to that heir outright, with no levy deducted from it. The heirs are arranged in five classes according to their nearness or distance from the deceased. When relatives of the first class are present, no class beyond it need be consulted; when the second class is present, the third is passed over; and so on in order.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'whoever stands nearest to the deceased in the reckoning of the sharia is his heir the inheritance passes to that heir outright with no levy deducted from it the heirs are arranged in five classes according to their nearness or distance from the deceased when relatives of the first class are present no class beyond it need be consulted when the second class is present the third is passed over and so on in order', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 55, NULL, 'The classes are set out in the tables:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'the classes are set out in the tables', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 56, NULL, 'The first class comprises the children and the children of children, the father, the mother, and one of the two spouses. The son''s son stands in the place of the son; the son''s daughter and the daughter''s children stand in the place of the daughter; and where the mother is absent, her mother stands in her place. The second class comprises the father, the mother, and the brothers and sisters, with the spouse''s share deducted first. The third class comprises the brothers and sisters and their children — whether of both parents, of the father alone, or of the mother alone — the male taking the portion of two females, this division being made after the share of the husband or wife is deducted. The fourth class comprises the grandfather and grandmother together with the brothers, sisters, and their children; the share of the husband or wife is likewise deducted first. The fifth class comprises the paternal uncle, the paternal aunt, the maternal uncle, and the maternal aunt, together with the grandfather and grandmother. Those of the father''s side and those of the mother''s side each receive their prescribed portions, and here too the share of the husband or wife is taken out first.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'the first class comprises the children and the children of children the father the mother and one of the two spouses the sons son stands in the place of the son the sons daughter and the daughters children stand in the place of the daughter and where the mother is absent her mother stands in her place the second class comprises the father the mother and the brothers and sisters with the spouses share deducted first the third class comprises the brothers and sisters and their children whether of both parents of the father alone or of the mother alone the male taking the portion of two females this division being made after the share of the husband or wife is deducted the fourth class comprises the grandfather and grandmother together with the brothers sisters and their children the share of the husband or wife is likewise deducted first the fifth class comprises the paternal uncle the paternal aunt the maternal uncle and the maternal aunt together with the grandfather and grandmother those of the fathers side and those of the mothers side each receive their prescribed portions and here too the share of the husband or wife is taken out first', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 57, NULL, 'In every class, the children of each group of brothers take their father''s share, and the children of each group of sisters take their mother''s share.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'in every class the children of each group of brothers take their fathers share and the children of each group of sisters take their mothers share', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 58, NULL, 'The tables also set out what is forbidden in marriage and in the combining of wives:', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'the tables also set out what is forbidden in marriage and in the combining of wives', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 59, NULL, 'Forbidden forever: the mother, the maternal aunt, the paternal aunt, the daughter of the brother, the daughter of the sister, and the sister. Forbidden by suckling: the milk-mother, the milk-sister, the milk-aunt, the daughter of the milk-brother, and the daughter of the milk-sister, and all of like standing however far the line descends — for what is forbidden by lineage is forbidden by suckling. Also forbidden: the mother of the wife, the daughters of the wife where the marriage has been consummated, and the wife of the father.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'forbidden forever the mother the maternal aunt the paternal aunt the daughter of the brother the daughter of the sister and the sister forbidden by suckling the milk mother the milk sister the milk aunt the daughter of the milk brother and the daughter of the milk sister and all of like standing however far the line descends for what is forbidden by lineage is forbidden by suckling also forbidden the mother of the wife the daughters of the wife where the marriage has been consummated and the wife of the father', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'chapter', 'what outlives you: charity, endowment, and inheritance', '11. What Outlives You: Charity, Endowment, and Inheritance', 60, NULL, 'These prohibitions are set out in the tables alongside those that hold only under a condition, so that the lawful may be distinguished from the forbidden and no doubt remain.', '', NULL, NULL, NULL, NULL, 'sharh al masail 11 what outlives you charity endowment and inheritance', 'these prohibitions are set out in the tables alongside those that hold only under a condition so that the lawful may be distinguished from the forbidden and no doubt remain', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'episode', NULL, 'Lawful Earning and the Table', 0, 1, 'Lawful Earning and the Table The treatise opens where a person''s day actually opens — at work, and then at the table. Three teachings: that earning a lawful living is ranked with striving in the way of God and measured by whether a family is spared from having to ask; that the manners of eating, feeding, hosting and being hosted form a single discipline aimed away from the self; and that the boundary of the lawful runs from what may be eaten, through how an animal must be killed and what may be hunted, to what may be worn and displayed.
', '', NULL, NULL, NULL, NULL, 'sharh al masail lawful earning and the table', 'lawful earning and the table the treatise opens where a persons day actually opens at work and then at the table three teachings that earning a lawful living is ranked with striving in the way of god and measured by whether a family is spared from having to ask that the manners of eating feeding hosting and being hosted form a single discipline aimed away from the self and that the boundary of the lawful runs from what may be eaten through how an animal must be killed and what may be hunted to what may be worn and displayed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'episode', NULL, 'Sale, Debt, and the Trust', 0, 2, 'Sale, Debt, and the Trust The treatise turns to the transaction itself. Three teachings: that a sale stands on three pillars and five conditions, all of them defending against a single flaw — anything left indeterminate, from air to an uncaught fish to an unnamed garment; that all lending divides by intention alone, so that the loan made for God''s sake may yield its lender no benefit whatever while the worldly loan''s every rule points toward taking less; and that in hire, partnership, pre-emption, borrowing and safekeeping the governing category stops being ownership and becomes trust, with the ruling consistently favouring whoever holds the weaker position.
', '', NULL, NULL, NULL, NULL, 'sharh al masail sale debt and the trust', 'sale debt and the trust the treatise turns to the transaction itself three teachings that a sale stands on three pillars and five conditions all of them defending against a single flaw anything left indeterminate from air to an uncaught fish to an unnamed garment that all lending divides by intention alone so that the loan made for gods sake may yield its lender no benefit whatever while the worldly loans every rule points toward taking less and that in hire partnership pre emption borrowing and safekeeping the governing category stops being ownership and becomes trust with the ruling consistently favouring whoever holds the weaker position', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'episode', NULL, 'Pledge, Shared Wall, and Marriage', 0, 3, 'Pledge, Shared Wall, and Marriage The treatise finishes its law of property and turns to obligations between people. Three teachings: that the security in a pledge is the written record and not the goods, so that the pledge held in hand without a document is the form the law condemns while a deed goes on proving the loan after the object is destroyed; that what two neighbours owe each other is decided by harm rather than by title, from a judge compelling a man to build on his own land to a division of ground that must price the well and the pathway along with the field; and that abstaining from marriage is an injury a person does to himself — with the home relocated from the building to the couple, the license for more than one wife read as a permission its own second clause withdraws, and the choosing governed by character before beauty.
', '', NULL, NULL, NULL, NULL, 'sharh al masail pledge shared wall and marriage', 'pledge shared wall and marriage the treatise finishes its law of property and turns to obligations between people three teachings that the security in a pledge is the written record and not the goods so that the pledge held in hand without a document is the form the law condemns while a deed goes on proving the loan after the object is destroyed that what two neighbours owe each other is decided by harm rather than by title from a judge compelling a man to build on his own land to a division of ground that must price the well and the pathway along with the field and that abstaining from marriage is an injury a person does to himself with the home relocated from the building to the couple the license for more than one wife read as a permission its own second clause withdraws and the choosing governed by character before beauty', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'episode', NULL, 'The Marriage Contract and Its Bonds', 0, 4, 'The Marriage Contract and Its Bonds The treatise stops urging the reader to marry and starts explaining how a marriage is actually made. Three teachings: the choosing and the look, where the decision belongs to the discerning people of the household rather than to the couple, the ages are matched at around eighteen, the pool is narrowed to the community, and the glance a man is permitted is rationed to one; the contract and its terms, where a marriage concluded through the wrong person is void outright, a stipulation contrary to the Book is a nullity rather than a hard bargain, the husband''s four powers are each qualified by fairness in the same breath, and the marriage payment is kept small, kept the wife''s, and set by a judge rather than by the man paying it; and the forbidden degrees, which cannot be complied with but only discovered — kinship by blood, kinship manufactured by marriage, and kinship created by a single swallow of milk inside a child''s first two years.
', '', NULL, NULL, NULL, NULL, 'sharh al masail the marriage contract and its bonds', 'the marriage contract and its bonds the treatise stops urging the reader to marry and starts explaining how a marriage is actually made three teachings the choosing and the look where the decision belongs to the discerning people of the household rather than to the couple the ages are matched at around eighteen the pool is narrowed to the community and the glance a man is permitted is rationed to one the contract and its terms where a marriage concluded through the wrong person is void outright a stipulation contrary to the book is a nullity rather than a hard bargain the husbands four powers are each qualified by fairness in the same breath and the marriage payment is kept small kept the wifes and set by a judge rather than by the man paying it and the forbidden degrees which cannot be complied with but only discovered kinship by blood kinship manufactured by marriage and kinship created by a single swallow of milk inside a childs first two years', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('sharh-al-masail-ghulam-hussain', 'episode', NULL, 'Maintenance, Dissolution, and Inheritance', 0, 5, 'Maintenance, Dissolution, and Inheritance The treatise stops explaining how a marriage is made and starts explaining what it costs. Three teachings: what a household is owed, where the obligation survives a husband''s disappearance, runs at a median standard that is neither wasteful nor miserly, covers instruction as well as food, holds for a woman who does not pray, and follows a divorced woman through the nursing of her child; dissolution and the waiting period, where a judge investigates the complaint and may issue the divorce over an unwilling husband''s head, where the pronouncement must be spoken and not merely written, where a wife may buy her own release, and where the third divorce is closed against every staged workaround; and wealth that leaves a person''s hands — the gift that can be reclaimed, the endowment that cannot, the testament of the Father of Imams as the working model, the will that reaches only a third of an estate, and the fixed fractions that take the rest.
', '', NULL, NULL, NULL, NULL, 'sharh al masail maintenance dissolution and inheritance', 'maintenance dissolution and inheritance the treatise stops explaining how a marriage is made and starts explaining what it costs three teachings what a household is owed where the obligation survives a husbands disappearance runs at a median standard that is neither wasteful nor miserly covers instruction as well as food holds for a woman who does not pray and follows a divorced woman through the nursing of her child dissolution and the waiting period where a judge investigates the complaint and may issue the divorce over an unwilling husbands head where the pronouncement must be spoken and not merely written where a wife may buy her own release and where the third divorce is closed against every staged workaround and wealth that leaves a persons hands the gift that can be reclaimed the endowment that cannot the testament of the father of imams as the working model the will that reaches only a third of an estate and the fixed fractions that take the rest', '');
